Given the proposed neural network architecture, we estimate the
Average Treatment Effect for the Treated (ATT) using double machine
learning (DML) \citep{chernozhukov_doubledebiased_2018}. We estimate
ATT to compare our result with the original analysis based on text
matching.  Here, we propose to estimate the propensity score model as
a function of the estimated deconfounder, i.e.,
$\pi_t(\boldf(\bR_i), \bm{Z}_i) = \P(T_i = t \mid \boldf(\bR_i),
\bm{Z}_i)$ so that we do not directly condition on the
high-dimensional unstructured objects.

To ensure the asymptotic normality discussed later in this section,
the propensity score model must be Lipschitz-continuous; accordingly,
we employ a neural network with spectral normalization
\citep{gouk2021regularisation}. Practical implementation requires
careful tuning of the hyperparameters for both the outcome and
propensity score models, including network width and depth, learning
rate, batch size, dropout rate, and number of epochs.  We automate
this with advanced hyperparameter-optimization tools such as Optuna
\citep{akiba_optuna_2019}.

As an example, we present the entire estimation procedure in the case
of binary treatment $\cT = \{0,1\}$. Denote the observed data by
$\cD:=\{\cD_i\}_{i=1}^N$ where
$\cD_i := \{Y_i, T_i, \bR_i, \bm{Z}_i\}$. We use the following
$K$-fold cross-fitting procedure, assuming that $N$ is divisible by
$K$.
\begin{enumerate}
    \item Randomly partition the data into $K$ folds of equal size where the size of each fold is $n = N/K$.  The observation index is denoted by $I(i)\in \{1,\dots,K\}$ where $I(i)=k$ implies that the $i$th observation belongs to the $k$th fold.
    \item For each fold $k \in \{1, \cdots, K\}$, use observations with $I(i)\ne k$ as training data:
    \begin{enumerate}
    \item further split the training data into two folds, $I_1^{(-k)}$ and $I_2^{(-k)}$
    \item simultaneously obtain an estimated deconfounder and an estimated conditional outcome function on the first fold, which are denoted by $\hat\boldf^{(-k)}(\{\bR_i, \bm{Z}_i\}_{i \in I_1^{(-k)}}):=\boldf(\{\bR_i, \bm{Z}_i\}_{i \in I_1^{(-k)}}; \hat\blambda^{(-k)})$ and $\hat{\mu}_t^{(-k)}(\{\bR_i, \bm{Z}_i\}_{i \in I_1^{(-k)}}):=\mu_t(\boldf(\{\bR_i\}_{i \in I_1^{(-k)}}, \bm{Z}_i; \hat\blambda^{(-k)}); \hat\btheta^{(-k)})$, respectively, by solving the optimization problem given in Equation~\eqref{loss_text_original}, and
    \item obtain an estimated propensity score given the estimated deconfounder on the second fold, which is denoted by $\hat{\pi}^{(-k)}(\hat\boldf^{(-k)}(\{\bR_i\}_{i \in I_2^{(-k)}}), \bm{Z}_i):=\hat{\pi}^{(-k)} (\boldf(\{\bR_i\}_{i \in I_2^{(-k)}}; \hat\blambda^{(-k)}), \bm{Z}_i)$.
    \end{enumerate}
  \item Compute the ATT estimator $\hat{\tau}$ as a solution to:
    \begin{equation*}
      \frac{1}{nK}\sum_{k = 1}^K  \sum_{i: I(i) =k} \psi(\cD_i; \hat{\tau}, \hat{\boldf}^{(-k)}, \mu^{(-k)}_0, \hat\pi^{(-k)}) \ = \ 0, \label{eq:tau.hat}
      \end{equation*}
      where
      \begin{equation}
        \begin{aligned}
        & \psi(\cD_i; \tau, \boldf, \mu_0, \pi)\\
        & \ = \  \frac{T_i (Y_i - \mu_0(\boldf(\bR_i), \bm{Z}_i)}{\P(T_i = 1)} -
        \frac{\pi(\boldf(\bR_i), \bm{Z}_i) (1 - T_i) (Y_i - \mu_0(\boldf(\bR_i), \bm{Z}_i) ) }{\P(T_i = 1)(1 - \pi(\boldf(\bR_i), \bm{Z}_i))} - \frac{T_i \tau}{\P(T_i = 1)}.
        \end{aligned} \label{eq:psi}
      \end{equation}
\end{enumerate}


Finally, we establish the asymptotic properties of the proposed
estimator in the case of binary treatment. We assume that the
following regularity conditions hold. These conditions are similar to
those in \cite{imai2024causal} except that we also condition on the
observed covariates $\bm{Z}_i$.
\begin{assumption}[Regularity Conditions]\label{reg_text} \spacingset{1} Let $c_1$, $c_2$, and $q > 2$ be positive constants and $\delta_n$ be a sequence of positive constants approaching zero as the sample size $n$ increases.  Then, the following conditions hold.
  \begin{enumerate}[label=(\alph*)]
    \item \label{reg_text_primitive} (Primitive conditions) 
    \begin{align*}
        \E[|Y_i|^q]^{1/q} \leq c_1, &\quad \sup_{\br \in \mathcal{R}, \bm{z} \in \mathcal{Z}}\E [|Y_i - \mu_{T_i}(\boldf(\br), \bm{z} )|^2 \mid \bR_i = \br, \bm{Z}_i = \bm{z}] \leq c_1,\\
        &\E[ |Y_i - \mu_{T_i}(\boldf(\bR_i), \bm{Z}_i)|^{2} ]^{1/2} \geq c_2.
    \end{align*}
  \item (Outcome model estimation) \label{reg_text_outcome}
    \begin{align*}
      %& \E[\{\hat{\pi}(\boldf(\bR_i)) - \pi(\boldf(\bR_i))\}^2]^\frac{1}{2} \leq \delta_n,  \quad \E[\hat\mu_{T_i}(\hat\boldf(\bR_i)) - \mu_{T_i}(\boldf(\bR_i))\}^2]^{\frac{1}{2}} \leq \delta_n \\ %assuming \sqrt{n} convergence -> consistency not needed anymore
        &\E[|\hat{\mu}_{T_i}(\hat{\boldf}(\bR_i), \bm{Z}_i) - \mu_{T_i}(\boldf(\bR_i), \bm{Z}_i)|^q]^{1/q} \leq c_1, \quad \E[|\hat{\mu}_{T_i}(\hat{\boldf}(\bR_i), \bm{Z}_i) - \mu_{T_i}(\boldf(\bR_i), \bm{Z}_i)|^2]^{1/2} \leq \delta_n n^{-1/4}.
    \end{align*}
  \item (Deconfounder estimation) \label{reg_text_deconfounder}
   \begin{align*}
      & \E\left[\norm{\hat{\boldf}(\bR_i) - \boldf(\bR_i)}^q\right]^{1/q} \leq c_1, \quad \mathbb{E}\left[ \norm{\hat{\boldf}(\bR_i) - \boldf(\bR_i)}^2 \right]^{1/2} \leq \delta_n n^{-1/4}
    \end{align*}    
  \item (Propensity score estimation) \label{reg_text_propensity} $\pi(\cdot)$ is Lipschitz continuous at the every point of its support, and satisfies:
    \begin{align*}
      %& \E[\{\hat{\pi}(\boldf(\bR_i)) - \pi(\boldf(\bR_i))\}^2]^\frac{1}{2} \leq \delta_n,  \quad \E[\hat\mu_{T_i}(\hat\boldf(\bR_i)) - \mu_{T_i}(\boldf(\bR_i))\}^2]^{\frac{1}{2}} \leq \delta_n \\ %assuming \sqrt{n} convergence -> consistency not needed anymore
        & \E[|\hat{\pi}(\boldf(\bR_i), \bm{Z}_i) - \pi(\boldf(\bR_i), \bm{Z}_i)|^q]^{1/q} \leq c_1, \quad  \E[|\hat{\pi}(\boldf(\bR_i), \bm{Z}_i) - \pi(\boldf(\bR_i), \bm{Z}_i)|^2]^{1/2} \leq \delta_n n^{-1/4}.
    \end{align*}
  \end{enumerate}
\end{assumption}
These regularity conditions are standard in the DML literature, and it
is known that the neural network architecture with an appropriate
depth and width can achieve the required convergence rates
\citep{farrell_deep_2021}. The propensity score requires the Lipschitz
continuity condition, which can be satisfied by using a regularized
neural network architecture \citep{gouk2021regularisation}.

Given the above assumptions, the asymptotic normality of the proposed
estimator follows immediately from the DML theory.
\begin{theorem}[Asymptotic Normality of the ATT Estimator]\label{asymp_text} \spacingset{1}
Under Assumptions~\ref{consistency_confounder}--\ref{reg_text}, the estimator $\hat{\tau}$ obtained from the influence function $\psi$ satisfies asymptotic normality:
$$
\frac{\sqrt{n}(\hat{\tau} - \tau)}{\sigma} \xrightarrow[]{d} \mathcal{N}(0, 1)
$$
where $\sigma^2 = \E[\psi(\cD_i; \tau, \boldf, \mu_1, \mu_0, \pi_1)^2].$
\end{theorem}
We omit the proof as it is identical to Theorem~1 of \cite{imai2024causal}.

\subsection{Implementation Details for the Empirical Application}

We reanalyze the dataset used by \citet{roberts_adjusting_2020}, which
is based on data from the Weiboscope project
\citep{fu2013assessing}. This project collected Weibo posts in real
time and subsequently revisited them to determine whether they had
been censored. The original analysis focused on users who experienced
at least one instance of censorship during the first half of 2012, and
examined their subsequent posts in the second half of that year. To
construct the control group, the authors selected posts that had a
cosine similarity greater than 0.5 to a censored post and were posted
on the same day. Posts shorter than 15 characters were excluded. The
final dataset we analyze consists of 75,324 posts from 4,155 Weibo
users.

Based on the treatment and control ``focal'' posts, three outcome
variables were constructed:
\begin{enumerate}
\item The number of posts made by the same user within the four weeks following the focal post
\item The proportion of those posts that were censored (as indicated
  by a ``permission denied'' message)
\item The proportion of posts that went missing (as indicated by a ``Weibo does not exist'' message)
\end{enumerate}
It is important to note that the second and third outcomes capture
different types of post removals. As noted by \citet{fu2013assessing},
a ``permission denied'' message is a clear signal of censorship,
whereas ``Weibo does not exist'' may reflect either censorship or
voluntary deletion by the user. To adjust for users' baseline
behavior, the same three measures were also computed for the four-week
period preceding each focal post and included as confouding variables.

We apply the GPI methodology as follows. First, we use LLaMA~3 (8
billion parameters) and Gemma~3 (1 billion parameters) to regenerate
all posts in the dataset and extract the internal representation of
the last token. Due to the autoregressive nature of generative models,
this final-token representation captures the full information of each
post. The resulting internal representation, denoted by $\bR_i$, has a
dimensionality of 4096 for LLaMA3 and 1152 for Gemma3. Using this
representation, we estimate the deconfounder $\boldf(\bR_i)$ and the
outcome model $\mu_{T_i}(\boldf(\bR_i), \bm{Z}_i)$ via a neural
network architecture described in the previous section.

To train the model for each outcome variable, we employed two-fold
cross-validation on the full sample, following the recommendation of
\citet{bach2024hyperparameter}. The hyperparameter search space
included: 
\begin{itemize}
\item Learning rate: $10^{-7}$ to $10^{-4}$
\item Dropout rate: 0.05 to 0.3
\item Outcome model architecture: single-layer MLP with ReLU activation and 50, 100, or 200 hidden units
\item Deconfounder architecture: two-layer MLP with ReLU activation and hidden unit configurations of [256, 128], [512, 256], or [1024, 512]
\end{itemize}

We automated hyperparameter optimization using Optuna
\citep{akiba_optuna_2019}, selecting the best parameters based on
validation loss across 100 trials. For both hyperparameter tuning and
nuisance function estimation, models were trained for up to 10000
epochs, with early stopping triggered if validation loss failed to
improve for 5 consecutive epochs. We used the Adam optimizer with a
batch size of 256 and a weight decay of $10^{-8}$ to prevent
overfitting. To stabilize training, we applied gradient clipping with
a maximum norm of 1.0. The optimal hyperparameter configurations for
each outcome measure are reported in Table~\ref{tab:hyperparameters}. 

