\section{Proof of Proposition~\ref{prop:identification}}\label{proof:prop_identification}

\begin{proof}
Under the definition of the deep generative model (see Definition~\ref{deep_use}) and Assumption~\ref{det_dec}, we can write $\bU_i = \boldf^*(\bR_i)$ with some deterministic function $\boldf^*$. Then,
\begin{align*}
  \P(Y_i(t) = y) &= \int_{\mathcal{Z}} \int_{\cU} \P(Y_i(t) = y \mid \bm{Z}_i, \bU_i) dF(\bU_i) dF(\bm{Z}_i)\\
  &= \int_{\mathcal{Z}} \int_{\cU} \P(Y_i(t) = y \mid T_i = t, \bm{Z}_i, \bU_i) dF(\bU_i) dF(\bm{Z}_i)\\
  &= \int_{\mathcal{Z}} \int_{\cU} \P(Y_i = y \mid T_i = t, \bm{Z}_i, \bU_i) dF(\bU_i) dF(\bm{Z}_i)\\
  &= \int_{\mathcal{Z}} \int_{\cU} \P(Y_i = y \mid T_i = t, \bm{Z}_i, \boldf^*(\bR_i)) dF(\boldf^*(\bR_i)) dF(\bm{Z}_i)\\
  &= \int_{\mathcal{Z}} \int_{\mathbb{R}^q} \P(Y_i = y \mid T_i = t, \bm{Z}_i, \boldf^*(\bR_i)) dF(\bR_i) dF(\bm{Z}_i)
\end{align*}
where the second equality follows from Assumption~\ref{ignorability_confounder}, the third equality follows from Assumption~\ref{consistency_confounder}. Finally, suppose that there exists another function $\boldf(\bR_i)$ that satisfies the conditional independence relation $Y_i \indep \bR_i \mid T_i, \bm{Z}_i, \boldf(\bR_i)$. Then,
\begin{align*}
&\int_{\mathcal{Z}} \int_{\mathbb{R}^q} \P(Y_i = y \mid T_i = t, \bm{Z}_i, \boldf(\bR_i)) dF(\bR_i) dF(\bm{Z}_i)\\
= & \int_{\mathcal{Z}} \int_{\mathbb{R}^q} \P(Y_i = y \mid T_i = t, \bm{Z}_i, \boldf(\bR_i), \bR_i ) dF(\bR_i) dF(\bm{Z}_i)\\
= & \int_{\mathcal{Z}} \int_{\mathbb{R}^q} \P(Y_i = y \mid T_i = t, \bm{Z}_i, \boldf^*(\bR_i), \bR_i ) dF(\bR_i) dF(\bm{Z}_i)\\
= & \int_{\mathcal{Z}} \int_{\mathbb{R}^q} \P(Y_i = y \mid T_i = t, \bm{Z}_i, \boldf^*(\bR_i)) dF(\bR_i) dF(\bm{Z}_i)
\end{align*}
Thus, any function of $\bR_i$ that satisfies the conditional independence relation $Y_i \indep \bR_i \mid T_i, \bm{Z}_i, \boldf(\bR_i)$ leads to the same identification formula.
\end{proof}

