\title{Graph Neural Network-Based Reinforcement Learning for Controlling Biological Networks --~the GATTACA Framework}

\iftrue
\author{Andrzej Mizera, Jakub Zarzycki\\
\vspace{2em}\textbf{This work has been submitted to the IEEE for possible publication. Copyright may be transferred without notice, after which this version may no longer be accessible.}%
