\scalebox{0.95}{
\begin{minipage}{0.45\linewidth}
\begin{algorithm2e}[H]
    \label{algorithm_train}
    \caption{Training of Dot with DDIM}
    \SetAlgoLined
    \DontPrintSemicolon
    \SetKwInput{Part}{Part}
    \SetKwInOut{Require}{Require}
    \SetKwInOut{Return}{Return}
    \SetKwInOut{repeat}{repeat}
    \setcounter{AlgoLine}{0}
    %{\centering \nonl \textbf{Training} \\}
    \Require{Trained Dash model $\theta(\cdot,\cdot)$}
    \Require{Dot model $\eta(\cdot,\cdot,\cdot,\cdot,\cdot)$ to be trained}
    \Require{Schedule function $\phi(\cdot,\cdot,\cdot,\cdot)$}
    \Require{Dataset $\mathcal{D}$}
    \Require{Learning rate $\gamma$}

    \Repeat{convergence}
    {
    sample $\mathbf{x} \sim \mathcal{D}$  \\
    sample $\epsilon \sim \mathcal{N}(0, \mathbf{I})$ \\
    sample $t_{s}, t_{o} \sim U[0, T]$ ($t_{s} > t_{o}$) \\
    $\mathbf{x}_{t_{s}} = \alpha_{t_{s}}\mathbf{x} + \sigma_{t_{s}}\epsilon$ \\
    $\mathbf{z}_{t_{s}} = \theta(\mathbf{x}_{t_{s}}, t_{s})$ \\
    $\mathbf{x}_{t_{o}} = \phi(\mathbf{x}_{t_{s}}, \mathbf{z}_{t_{s}}, t_{s}, t_{o})$ \\
    $\mathbf{z}_{t_{o}} = \theta(\mathbf{x}_{t_{o}}, t_{o})$ \\
    $\hat{\mathbf{z}}_{t_{o}} = \mathbf{z}_{t_{s}} + \eta(\mathbf{x}_{t_{s}}, \mathbf{x}_{t_{o}},  \mathbf{z}_{t_{s}}, t_{s}, t_{o})$ \\
    $\eta \leftarrow \eta - \gamma \nabla_{\eta}\Vert \mathbf{z}_{t_{o}} - \hat{\mathbf{z}}_{t_{o}} \Vert_{2}^{2} $ \\
    }

\end{algorithm2e}
\end{minipage}
}
