\scalebox{0.95}{
\begin{algorithm2e}[H]
    \label{algorithm_inference}
    \caption{DDIM Sampling with Morse}
    \SetAlgoLined
    \SetKwInput{Part}{Part}
    \SetKwInOut{Require}{Require}
    \SetKwInOut{Return}{Return}
    \SetKwInOut{repeat}{repeat}
    \setcounter{AlgoLine}{0}
    %{\centering \nonl \textbf{Training} \\}
    \Require{Trained network Dash $\theta(\cdot,\cdot)$}
    \Require{Trained network Dot $\eta(\cdot,\cdot,\cdot,\cdot,\cdot)$}
    \Require{Schedule function $\phi(\cdot,\cdot,\cdot,\cdot)$}
    \Require{Sequence of time points $t_{n} > t_{n-1} > \dots > t_{0}$}
    \Require{Number of dash steps $d$}

    sample $\mathbf{x}_{t_{n}} \sim \mathcal{N}(0, \mathbf{I})$ \\
    uniformly sample $s_{d}, \dots, s_{0}$ from $t_{n}$ to $t_{0}$ %($r_{d}=n, r_{0}=0$)

    \For{$i\leftarrow n$ \KwTo $1$}{

    \eIf{$t_{i} \in \{s_{d}, \dots, s_{1}\}$}{
    $\mathbf{z}_{t_{i}} = \theta(\mathbf{x}_{t_{i}}, t_{i})$ \\
    $t_{s} = t_{i}$
    }{
    $\mathbf{z}_{t_{i}} = \mathbf{z}_{s} + \eta(\mathbf{x}_{t_{s}}, \mathbf{x}_{t_{i}}, \mathbf{z}_{t_{s}}, t_{s}, t_{i})$
    }
    $\mathbf{x}_{t_{i-1}} = \phi(\mathbf{x}_{t_{i}}, \mathbf{z}_{t_{i}}, t_{i}, t_{i-1})$
    }
    \Return{$\mathbf{x}_{t_{0}}$}
\end{algorithm2e}}
