\title{\textbf{A discontinuous Galerkin pressure correction scheme for the Oldroyd model of order one}}
\author{Pratyay Mondal\thanks{\tt m.pratyay@iitg.ac.in} and Rajen Kumar Sinha\thanks{{\tt rajen@iitg.ac.in} \\ Department of Mathematics, Indian Institute of Technology Guwahati, Guwahati-781039, India.}}
