\section{Algebraic framework for $q$MZVs}\label{sec:algebra}

\subsection{Preliminaries}

Let $\mathcal{C}=\mathbb{Q}[\hbar, \hbar^{-1}]$ be
the Laurent polynomial ring of the formal variable $\hbar$ over $\mathbb{Q}$.
We denote by $\widehat{\mathfrak{H}^{1}}$
the non-commutative polynomial ring over $\mathcal{C}$
with variables $e_{1}$ and $g_{k} \, (k\ge 1)$.
We set
\begin{align*}
        e_{k}=g_{k}+\hbar g_{k-1}
\end{align*}
for $k\ge 2$.
The set
$\mathcal{A}=\{e_{1}-g_{1}\} \sqcup \{g_{k} \mid k\ge 1\}$
is algebraically independent and generates $\widehat{\mathfrak{H}^{1}}$.
We denote by $\mathfrak{z}$ the free $\mathcal{C}$-module
spanned by $\mathcal{A}$.
We denote by $\widehat{\mathfrak{H}^{0}}$
the $\mathcal{C}$-submodule of $\widehat{\mathfrak{H}^{1}}$ spanned by
$1$ and the monomials of the form $u_{1}\cdots u_{r}$
$(u_{1}, \ldots , u_{r} \in \mathcal{A})$ with $u_{r}\not=e_{1}-g_{1}$.

Hereafter we assume that $0<q<1$.
We endow
$\mathbb{R}$ with the structure of a $\mathcal{C}$-module
such that $\hbar^{\pm 1}$ acts as multiplication by $(1-q)^{\pm 1}$.
For $m\ge 1$, we define the $\mathcal{C}$-linear map
$I_{q}(\, \cdot \, |\, m): \mathfrak{z}\to \mathbb{R}$ by
\begin{align*}
        I_{q}(e_{1}-g_{1}\,|\, m)=1-q, \qquad
        I_{q}(g_{k}\,|\, m)=\left(\frac{q^{m}}{[m]}\right)^{k}
        \quad (k\ge 1),
\end{align*}
where $[m]=(1-q^{m})/(1-q)$ is the $q$-integer.
We have
\begin{align*}
        I_{q}(e_{k}\,|\,m)=\frac{q^{(k-1)m}}{[m]^{k}}
        \qquad (k\ge 1).
\end{align*}

We define the $\mathcal{C}$-linear map
$Z_{q}: \widehat{\mathfrak{H}^{0}} \longrightarrow \mathbb{R}$ by
$Z_{q}(1)=1$ and
\begin{align*}
        Z_{q}(u_{1}\cdots u_{r})=
        \sum_{0<m_{1}<\cdots <m_{r}}
        \prod_{a=1}^{r}I_{q}(u_{a} \,|\, m_{a})
\end{align*}
for $u_{1}, \ldots , u_{r} \in \mathcal{A}$ with
$u_{r}\not=e_{1}-g_{1}$.
Then the Bradley-Zhao model \eqref{eq:BZ-model} is expressed as
\begin{align*}
        \zeta_{q}(\bk)=Z_{q}(e_{k_{1}} \cdots e_{k_{r}})
\end{align*}
for a tuple of positive integers $\bk=(k_{1}, \ldots , k_{r})$ with $k_{r}\ge 2$.

We extend the map $Z_{q}$
to the formal power series ring
$Z_{q}: \widehat{\mathfrak{H}^{0}}[[X]] \longrightarrow \mathbb{R}[[X]]$ by
\begin{align*}
        Z_{q}(\sum_{n\ge 0}w_{n}X^{n})=\sum_{n\ge 0}Z_{q}(w_{n})X^n
        \qquad
        (w_{n} \in \widehat{\mathfrak{H}^{0}}).
\end{align*}

%%%%%%%%%%%%%%

\subsection{Harmonic product}\label{sec:harmonic-product}

We define the symmetric $\mathcal{C}$-bilinear map
$\circ_{\hbar}:  \mathfrak{z} \times \mathfrak{z} \to
        \mathfrak{z}$ by
\begin{align*}
        (e_{1}-g_{1})\circ_{\hbar}(e_{1}-g_{1})=\hbar (e_{1}-g_{1}), \quad
        (e_{1}-g_{1})\circ_{\hbar} g_{k}=\hbar g_{k}, \quad
        g_{k}\circ_{\hbar} g_{l}=g_{k+l} \qquad (k, l\ge 1).
\end{align*}
It is associative,
that is,
$(u_{1} \circ_{\hbar} u_{2})\circ_{\hbar} u_{3}=u_{1}\circ_{\hbar}
        (u_{2} \circ_{\hbar} u_{3})$ for any $u_{1}, u_{2}, u_{3} \in \mathfrak{z}$.
For $u \in \mathfrak{z}$ and $n\ge 1$,
we define $u^{\circ_{\hbar}n}$ inductively by $u^{\circ_{\hbar}1}=u$ and
$u^{\circ_{\hbar}n}=(u^{\circ_{\hbar}(n-1)})\circ_{\hbar}u$ for $n\ge 2$.

The \textit{harmonic product} $\ast_{\hbar}$ on $\widehat{\mathfrak{H}^{1}}$
is the $\mathcal{C}$-bilinear binary operation
uniquely defined by the following properties:
\begin{enumerate}
        \item For any $w \in \widehat{\mathfrak{H}^{1}}$,
              it holds that $w \ast_{\hbar} 1=w$ and $1\ast_{\hbar} w=w$.
        \item For any $w, w'\in \widehat{\mathfrak{H}^{1}}$ and $u, v \in \mathcal{A}$,
              it holds that $(w u)\ast_{\hbar}(w' v)=(w\ast_{\hbar} w' v)u+(wu\ast_{\hbar} w')v+
                      (w\ast_{\hbar} w')(u\circ_{\hbar}v)$.
\end{enumerate}
The harmonic product is commutative and associative, and
$\widehat{\mathfrak{H}^{0}}$ is closed under it
since $g_{k}\circ_{\hbar} g_{l}=g_{k+l}$ for $k, l \ge 1$.
For $w \in \widehat{\mathfrak{H}^{1}}$
and $n\ge 1$,
we define $w^{\ast_{\hbar} n}$ inductively by
$w^{\ast_{\hbar} 1}=w$ and
$w^{\ast_{\hbar} n}=(w^{\ast_{\hbar}(n-1)})\ast_{\hbar}w$
for $n\ge 2$.

Since
\begin{align}
        I_{q}(u\circ_{\hbar} v\,|\, m)=I_{q}(u \,|\, m)I_{q}(v \,|\, m)
        \qquad
        (u, v \in \mathfrak{z}, \, m\ge 1),
        \label{eq:I-hom}
\end{align}
the map $Z_{q}$ is a homomorphism with
respect to the harmonic product.
Namely, it holds that
\begin{align}
        Z_{q}(w \ast_{\hbar} w')=Z_{q}(w) Z_{q}(w')
        \label{eq:Zq-harmonic}
\end{align}
for any $w, w' \in \widehat{\mathfrak{H}^{0}}$.

We extend the harmonic product to
the formal power series ring $\widehat{\mathfrak{H}^{1}}[[X]]$
by
$f(X)\ast_{\hbar}g(X)=\sum_{n \ge 0}(\sum_{k+l=n}a_{k}\ast_{\hbar}b_{l})X^{n}$
for $f(X)=\sum_{k\ge 0}a_{k}X^{k}$ and $g(X)=\sum_{l \ge 0}b_{l}X^{l}$.
We also extend the map $\circ_{\hbar}$ to
the $\mathcal{C}$-module
$\mathfrak{z}[[X]]=\{\sum_{n\ge 0}a_{n}X^{n}\mid a_{n} \in \mathfrak{z} \, (n\ge 0)\}$
by $f(X)\circ_{\hbar}g(X)=\sum_{n \ge 0}(\sum_{k+l=n}a_{k}\circ_{\hbar}b_{l})X^{n}$.

For $f(X) \in X \widehat{\mathfrak{H}^{1}}[[X]]$, we define
the exponential by
\begin{align*}
        \exp_{\ast_{\hbar}}(f(X))=1+\sum_{n=1}^{\infty}\frac{1}{n!}
        (f(X))^{\ast_{\hbar} n}
\end{align*}
which is well-defined as an element of
$\widehat{\mathfrak{H}^{1}}[[X]]$ because
$f(X)$ does not have a constant term.
Then we have
\begin{align*}
        Z_{q}(\exp_{\ast_{\hbar}}{(f(X))})=\exp{(Z_{q}(f(X)))}
\end{align*}
for any $f(X)\in X\widehat{\mathfrak{H}^{0}}[[X]]$.
%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Bachmann's identity}

We rewrite Bachmann's identity \eqref{eq:Bachmann} in the algebraic framework.
First we see that
\begin{align*}
        A_{r}(q)=(1-q)^{-2r}\sum_{0<m_{1}<\cdots <m_{r}}
        \prod_{a=1}^{r}I_{q}(e_{2}\mid m_{a})=Z_{q}(\hbar^{-2r}e_{2}^{r}).
\end{align*}
Next the function $G_{k}(q)$ is realized as follows.

\begin{prop}\label{prop:phik-G}
        For $k\ge 1$, we set
        \begin{align}
                \phi_{k}=\sum_{j=1}^{k}(j-1)!
                {k\brace j}
                \hbar^{k-j}g_{j}.
                \label{eq:def-phi}
        \end{align}
        Then we have $Z_{q}(\hbar^{-k}\phi_{k})=G_{k}(q)$.
\end{prop}

\begin{proof}
        We consider the generating function
        \begin{align*}
                \Phi(T)=\sum_{k\ge 1}\frac{T^{k-1}}{(k-1)!}Z_{q}(\hbar^{-k}\phi_{k})=
                \sum_{k\ge 1}T^{k-1}
                \sum_{j=1}^{k}\frac{(j-1)!}{(k-1)!}{k\brace j}
                \sum_{m>0}
                \left(\frac{q^{m}}{1-q^{m}}\right)^{j}.
        \end{align*}
        By using \eqref{eq:stirling-second-exp},
        we see that
        \begin{align*}
                \Phi(T) & =
                \sum_{j\ge 1}\sum_{m>0}
                (j-1)! \left(\frac{q^{m}}{1-q^{m}}\right)^{j}
                \frac{d}{dT}\frac{(e^{T}-1)^{j}}{j!}                            \\
                        & =-\sum_{m>0}
                \frac{d}{dT}\log{\left(1-\frac{q^{m}}{1-q^{m}}(e^{T}-1)\right)} \\
                        & =
                \sum_{m>0} \frac{q^{m}e^{T}}{1-q^{m}e^{T}}
                =\sum_{m>0} \frac{e^{T+y}}{1-e^{T+y}}
                \bigg|_{y=m\log{q}}.
        \end{align*}
        Since
        \begin{align*}
                \frac{e^{T+y}}{1-e^{T+y}}=
                e^{T\frac{d}{dy}}\frac{e^{y}}{1-e^{y}}=
                \sum_{k\ge 1}\frac{T^{k-1}}{(k-1)!}\left(\frac{d}{dy}\right)^{k-1}
                \sum_{n\ge 1}e^{ny}=
                \sum_{k \ge 1}\frac{T^{k-1}}{(k-1)!}\sum_{n \ge 1}n^{k-1}e^{ny},
        \end{align*}
        we find that
        \begin{align*}
                \Phi(T)=\sum_{m>0}
                \sum_{k\ge 1}\frac{T^{k-1}}{(k-1)!}
                \sum_{n \ge 1}n^{k-1}q^{mn}=
                \sum_{k\ge 1}\frac{T^{k-1}}{(k-1)!}G_{k}(q).
        \end{align*}
\end{proof}

Proposition \ref{prop:phik-G} implies that
the identity \eqref{eq:Bachmann} is written as
\begin{align*}
        Z_{q}\left(\frac{1}{1-\hbar^{-2}e_{2}X^2}\right)=
        \exp{\left(2
        \sum_{k\ge 1}\frac{(-1)^{k-1}}{(2k)!}Z_{q}(\hbar^{-2k}\phi_{2k})
        (2\arcsin{(X/2)})^{2k}
        \right)}.
\end{align*}
Since the map $Z_{q}$ is a homomorphism with respect to the harmonic product,
the above equality follows from
\begin{align}
        \frac{1}{1-\hbar^{-2}e_{2}X^2}=\exp_{\ast_{\hbar}}{\left(
                2\sum_{k\ge 1}\frac{(-1)^{k-1}}{(2k)!} \hbar^{-2k}\phi_{2k}
                (2\arcsin{(X/2)})^{2k}
                \right)},
        \label{eq:Bachmann3}
\end{align}
which is an identity of formal power series
with coefficients in $\widehat{\mathfrak{H}^{0}}$.
In the next section we prove a general identity which contains \eqref{eq:Bachmann3}
as a special case.

\begin{rem}\label{rem:KMS}
        Let $N$ be a positive integer and $S$ a non-empty subset of $\mathbb{Z}/N\mathbb{Z}$.
        For $m \in \mathbb{Z}$, we write $m \in S$ if $(m \, \mathrm{mod}\, N)\in S$.
        For $\epsilon \in \{ +1, -1\}$ and $r\ge 1$, set
        \begin{align*}
                A_{S, N, \epsilon, r}(q)=
                \sum_{\substack{0<m_{1}<\cdots <m_{r}
                \\ m_{1}, \ldots , m_{r} \in S}}
                \frac{\epsilon^{r}q^{m_{1}+\cdots +m_{r}}}
                {(1-\epsilon q^{m_{1}})^{2}\cdots (1-\epsilon q^{m_{r}})^{2}}.
        \end{align*}
        Kang, Matsusaka and Shin
        \cite{KMS} proves a generalization of \eqref{eq:Bachmann} which states that
        \begin{align}
                1+\sum_{r\ge 1}A_{S, N, \epsilon, r}(q)X^{2r}=
                \exp{\left(2\sum_{k\ge 1}\frac{(-1)^{k-1}}{(2k)!}G_{S, N, \epsilon, 2k}(q)
                (2\arcsin{(X/2)})^{2k}\right)},
                \label{eq:KMS}
        \end{align}
        where $G_{S, N, \epsilon, k}(q)$ is defined by
        \begin{align*}
                G_{S, N, \epsilon, k}(q)
                =\sum_{n\ge 1}\left(
                \sum_{\substack{d\mid n
                \\ n/d \in S}}\epsilon^{d}d^{k-1} \right)
                q^{n}
        \end{align*}
        for $k\ge 1$.
        By setting $N=1$ and $\epsilon=+1$, we recover \eqref{eq:Bachmann}.

        The identity \eqref{eq:KMS} can be derived from \eqref{eq:Bachmann3}
        as follows.
        For $\epsilon \in \{ +1, -1\}$ and $m\ge 1$, set
        \begin{align*}
                I_{q, \epsilon}(e_{1}-g_{1}\,|\, m)=1-q, \qquad
                I_{q, \epsilon}(g_{k}\,|\, m)=
                \left((1-q)\frac{\epsilon q^{m}}{1-\epsilon q^{m}}\right)^{k}
                \quad (k\ge 1).
        \end{align*}
        We define the $\mathcal{C}$-linear map
        $Z_{q, S, N, \epsilon}: \widehat{\mathfrak{H}^{0}} \longrightarrow \mathbb{R}$ by
        $Z_{q, S, N, \epsilon}(1)=1$ and
        \begin{align*}
                Z_{q, S, N, \epsilon}(u_{1}\cdots u_{r})=
                \sum_{\substack{0<m_{1}<\cdots <m_{r}
                \\ m_{1}, \ldots, m_{r} \in S}}
                \prod_{a=1}^{r}I_{q, \epsilon}(u_{a} \,|\, m_{a})
        \end{align*}
        for $u_{1}, \ldots , u_{r}\in \mathcal{A}$ with $u_{r}\not=e_{1}-g_{1}$.
        Then we have
        \begin{align*}
                Z_{q, S, N, \epsilon}(\hbar^{-2r}e_{2}^{r})=
                A_{S, N, \epsilon, r}(q), \quad
                Z_{q, S, N, \epsilon}(\phi_{k})=G_{S, N, \epsilon, k}(q).
        \end{align*}

        It can be checked that
        the relation \eqref{eq:I-hom} with $I_{q}$ replaced by $I_{q, \epsilon}$
        also holds.
        Hence the map
        $Z_{q, S, N, \epsilon}$ is a homomorphism with respect to
        the harmonic product,
        and the identity \eqref{eq:KMS} follows from
        \eqref{eq:Bachmann3}.
\end{rem}

