\section{General identity}\label{sec:main}

In this section we prove a general identity
which contains \eqref{eq:Bachmann3} as a special case.
Hereafter we set
\begin{align*}
        \epsilon_{N}=\exp{(2\pi i /N)} \qquad (N \ge 1).
\end{align*}

We set
\begin{align*}
        \mathcal{P}=\left\{P(z) \in \mathbb{Q}[z] \mid P(0)=P(1)=0 \right\}
\end{align*}
and define the $\mathbb{Q}$-linear map
$\psi: \mathcal{P} \to \mathfrak{z}$ by
$\psi(z^{n})=(-\hbar)^{-n}g_{n}$ for $n\ge 1$.
For example, we have
\begin{align*}
        \psi(z^{N-1}(z-1))=(-\hbar)^{-N}g_{N}-(-\hbar)^{-(N-1)}g_{N-1}=(-\hbar)^{-N}e_{N}
        \qquad (N\ge 2).
\end{align*}
The image of the map $\psi$ coincides with the $\mathbb{Q}$-module
spanned by the set $\{\hbar^{-k}e_{k}\}_{k\ge 2}$.
For simplicity of notation, we write $\psi_{P}$ instead of $\psi(P(z))$.

The general identity is given as follows.

\begin{thm}\label{thm:main1}
        Suppose that $P(z)\in \mathcal{P}\setminus\{0\}$ and $L\ge 1$.
        Set $N=\deg{P}\ge 2$.
        Then it holds that
        \begin{align}
                \frac{1}{1+(\psi_{P})^{\circ_{\hbar}L}X^{NL}}=
                \exp_{\ast_{\hbar}}{\left(-\sum_{k\ge 2}\frac{\hbar^{-k}}{k!}\phi_{k}
                        \sum_{m=1}^{NL}\left(\mathop{\mathrm{Log}}{(1-\alpha(\epsilon_{NL}^{m}X))}\right)^{k}
                        \right)},
                \label{eq:main1}
        \end{align}
        where
        $\alpha(X)$ is a convergent power series satisfying
        $\alpha(0)=0$ and
        \begin{align}
                1-x^{N}P(z)=\prod_{m=1}^{N}(1-\alpha(\epsilon_{N}^{m}x)z)
                \label{eq:def-alpha}
        \end{align}
        in a neighborhood of $x=0$.
\end{thm}

\begin{rem}\label{rem:existence-alpha}
        We see the existence of such a power series $\alpha(X)$ as follows.
        Set $R(z)=z^{N}P(1/z)$. Since $R(0)\not=0$,
        we can take a holomorphic branch of $R(z)^{1/N}$
        in a neighborhood of $z=0$.
        Then the function $f(x, z)=z-x\,R(z)^{1/N}$
        is holomorphic in a neighborhood of $(x, z)=(0, 0)$
        and $\partial f/\partial z$ does not vanish at $(0, 0)$.
        Hence there exists a unique holomorphic function $z=\alpha(x)$ satisfying
        $\alpha(0)=0$ and $f(x, \alpha(x))=0$ in a neighborhood of $x=0$.
                {}From the definition of $f$, it holds that $\alpha(x)^{N}=x^{N}R(\alpha(x))$,
        and hence $z=1/\alpha(x)$ is a root of the polynomial $1-x^{N}P(z)$.
        Although the function $\alpha(x)$ depends on the choice of the branch of $R(z)^{1/N}$,
        the set $\{\alpha(\epsilon_{N}^{m}x)\}_{m=1}^{N}$ does not
        and its elements are distinct around $x=0$.
        Therefore we have the factorization \eqref{eq:def-alpha}.
\end{rem}

\begin{rem}
        The logarithms part of the right-hand side of \eqref{eq:main1} can be
        calculated algebraically from $P(z)$ in principle as follows.
        It follows from \eqref{eq:stirling-first-log} that
        \begin{align}
                \sum_{m=1}^{NL}(\mathop{\mathrm{Log}}(1-\alpha(\epsilon_{NL}^{m}X)))^{k}=(-1)^{k}
                \sum_{s \ge k}\frac{k!}{s!}
                {s \brack k} %\left[ s \atop k \right] 
                \sum_{m=1}^{NL}(\alpha(\epsilon_{NL}^{m}X))^{s}.
                \label{eq:rem-log-sum}
        \end{align}
        On the other hand, from \eqref{eq:def-alpha}, we have
        \begin{align*}
                1-X^{NL}(P(z))^{L}=\prod_{a=1}^{L}(1-\epsilon_{L}^{a}X^{N}P(z))=
                \prod_{m=1}^{NL}(1-\alpha(\epsilon_{NL}^{m}X)z).
        \end{align*}
        By taking the logarithmic derivative with respect to $z$, we see that
        \begin{align*}
                \frac{LX^{NL}P'(z)(P(z))^{L-1}}{1-X^{NL}(P(z))^{L}}=\sum_{m=1}^{NL}
                \frac{\alpha(\epsilon_{NL}^{m}X)}{1-\alpha(\epsilon_{NL}^{m}X)z}=
                \sum_{s\ge 1}z^{s-1}\sum_{m=1}^{NL}(\alpha(\epsilon_{NL}^{m}X))^{s}.
        \end{align*}
        Hence we can write the power sum
        $\sum_{m=1}^{NL}(\alpha(\epsilon_{NL}^{m}X))^{s}$ for $s\ge 1$
        as a power series in $X^{NL}$ with rational coefficients
        by expanding the left-hand side at $z=0$.
        Thus we obtain a formula for the logarithmic part \eqref{eq:rem-log-sum}.
        Note that the logarithmic part becomes zero when $k=1$
        because $\prod_{m=1}^{NL}(1-\alpha(\epsilon_{NL}^{m}X))=1$
        under the assumption that $P(1)=0$.
\end{rem}

Now we start to prove Theorem \ref{thm:main1}.
We first show that the desired equality \eqref{eq:main1} with $L\ge 2$
follows from that with $L=1$.

\begin{prop}\label{prop:frac-prod-ast}
        For any $f(X), g(X) \in \mathfrak{z}[[X]]$, it holds that
        \begin{align}
                \frac{1}{1+Xf(X)}\ast_{\hbar}\frac{1}{1+Xg(X)}=
                \frac{1}{1+\left\{(f(X)+g(X))X-(f(X)\circ_{\hbar}g(X))X^{2}\right\}}
                \label{eq:frac-prod-ast}
        \end{align}
        in the $\mathcal{C}$-module $\mathfrak{z}[[X]]$.
\end{prop}

\begin{proof}
        Denote by $I$ the left-hand side.
        We see
        \begin{align*}
                I & =\left(1-\frac{1}{1+Xf(X)}Xf(X)\right)\ast_{\hbar}
                \left(1-\frac{1}{1+Xg(X)}Xg(X)\right)                  \\
                  & =1-\frac{Xf(X)}{1+Xf(X)}-\frac{Xg(X)}{1+Xg(X)}+
                \frac{X}{1+Xf(X)}f(X)\ast_{\hbar} \frac{X}{1+Xg(X)}g(X)
        \end{align*}
        and
        \begin{align*}
                 &
                \frac{X}{1+Xf(X)}f(X)\ast_{\hbar} \frac{X}{1+Xg(X)}g(X)                  \\
                 & =\left(\frac{X}{1+Xf(X)}\ast_{\hbar}\frac{Xg(X)}{1+Xg(X)}\right)f(X)+
                \left(\frac{Xf(X)}{1+Xf(X)}\ast_{\hbar}\frac{X}{1+Xg(X)}\right)g(X)      \\
                 & \quad {}+
                X^{2}I(f(X)\circ_{\hbar}g(X))                                            \\
                 & =X\left(\frac{1}{1+Xf(X)}-I\right)f(X)+
                X\left(\frac{1}{1+Xg(X)}-I\right)g(X)+
                X^{2}I(f(X)\circ_{\hbar}g(X)).
        \end{align*}
        Thus we find
        \begin{align*}
                I=1-I\left\{(f(X)+g(X))X-(f(X)\circ_{\hbar}g(X))X^{2}\right\}.
        \end{align*}
        This completes the proof.
\end{proof}

Set $\mathcal{C}_{\mathbb{C}}=\mathbb{C}[\hbar, \hbar^{-1}]=
        \mathbb{C}\otimes_{\mathbb{Q}}\mathcal{C}$.
We extend the coefficient ring $\mathcal{C}$ of
$\mathfrak{z}$ and $\widehat{\mathfrak{H}^{1}}$
to $\mathcal{C}_{\mathbb{C}}$.
Then the equality \eqref{eq:frac-prod-ast} still holds for any
power series $f(X)$ and $g(X)$ with coefficients in
$\mathfrak{z}_{\mathbb{C}}=\mathcal{C}_{\mathbb{C}}\otimes_{\mathcal{C}}\mathfrak{z}$.

\begin{cor}\label{cor:cyclotomic-prod}
        For any $u \in \mathfrak{z}_{\mathbb{C}}$ and $L\ge 1$, it holds that
        \begin{align*}
                \frac{1}{1+uX} \ast_{\hbar} \frac{1}{1+\epsilon_{L}uX} \ast_{\hbar}
                \cdots \ast_{\hbar} \frac{1}{1+\epsilon_{L}^{L-1}uX}=
                \frac{1}{1+u^{\circ_{\hbar} L}X^{L}}.
        \end{align*}
\end{cor}

\begin{proof}
        By using Proposition \ref{prop:frac-prod-ast} repeatedly,
        we see that the left-hand side is equal to
        \begin{align*}
                \left(1+\sum_{a=1}^{L}(-1)^{a-1}
                e_{a}(1, \epsilon_{L}, \ldots, \epsilon_{L}^{L-1})
                u^{\circ_{\hbar} a}X^{a} \right)^{-1},
        \end{align*}
        where
        $e_{a}(t_{1}, \ldots , t_{L})=\sum_{1\le j_{1}<\cdots <j_{a}\le L}t_{j_{1}}\cdots t_{j_{a}}$
        is the elementary symmetric polynomial.
        The desired equality follows from
        $        e_{a}(1, \epsilon_{L}, \ldots , \epsilon_{L}^{L-1})=(-1)^{L-1}\delta_{a, L}$
        for $1\le a \le L$.
\end{proof}

Now suppose that \eqref{eq:main1} holds for $L=1$.
By using Corollary \ref{cor:cyclotomic-prod}, we see that
\begin{align*}
         &
        \frac{1}{1+(\psi_{P})^{\circ_{\hbar}L}X^{NL}}  \\
         & =\frac{1}{1+\psi_{P}X^{N}}\ast_{\hbar}
        \frac{1}{1+\psi_{P}(\epsilon_{NL}X)^{N}}\ast_{\hbar}
        \frac{1}{1+\psi_{P}(\epsilon_{NL}^{2}X)^{N}}\ast_{\hbar} \cdots
        \ast_{\hbar}
        \frac{1}{1+\psi_{P}(\epsilon_{NL}^{L-1}X)^{N}} \\
         & =
        \exp_{\ast_{\hbar}}{\left(
                -\sum_{a=0}^{L-1}\sum_{k\ge 2}\frac{\hbar^{-k}}{k!}\phi_{k}
                \sum_{m=1}^{N}\left(\mathop{\mathrm{Log}}{(1-\alpha(\epsilon_{N}^{m}\epsilon_{NL}^{a}X))}\right)^{k}
                \right)}.
\end{align*}
It is equal to the right-hand side of \eqref{eq:main1} because
$\{\epsilon_{N}^{m}\epsilon_{NL}^{a}\mid 1\le m \le N, \, 0\le a\le L-1\}=
        \{\epsilon_{NL}^{m}\mid 1\le m \le NL\}$.
Thus it suffices to show the desired identity \eqref{eq:main1}
in the case of $L=1$.

To prove the identity \eqref{eq:main1} with $L=1$,
we use the following formula.

\begin{prop}\label{prop:exp-ast}
        \cite[Corollary 5.1]{HI}\,
        For any $u \in \mathfrak{z}$, it holds that
        \begin{align*}
                \frac{1}{1-uX}=
                \exp_{\ast_{\hbar}}{\left(
                        \sum_{n\ge 1}\frac{(-1)^{n-1}}{n}u^{\circ_{\hbar}n}X^{n}
                        \right)}
        \end{align*}
        in the formal power series ring $\widehat{\mathfrak{H}^{1}}[[X]]$.
\end{prop}

Set
\begin{align*}
        \Psi(X)=\sum_{r\ge 1}        \frac{X^{Nr}}{r}
        \left(\psi_{P}\right)^{\circ_{\hbar}r}.
\end{align*}
Proposition \ref{prop:exp-ast} implies that
\begin{align*}
        \frac{1}{1+\psi_{P}X^{N}}=\exp_{\ast_{\hbar}}(-\Psi(X)).
\end{align*}

Set $P(z)=\sum_{j=1}^{N}c_{j}z^{j}$ with $c_{j} \in \mathbb{Q}$.
Then $\psi_{P}=\sum_{j=1}^{N}c_{j}(-\hbar)^{-j}g_{j}$
and
\begin{align*}
        \Psi(X)
         & =\sum_{r\ge 1}\frac{X^{Nr}}{r}
        \sum_{j_{1}, \ldots , j_{r}=1}^{N}(-\hbar)^{-\sum_{a=1}^{r}j_{a}}
        c_{j_{1}} \cdots c_{j_{r}} g_{j_{1}+\cdots +j_{r}} \\
         & =\sum_{l \ge 1}(-\hbar)^{-l}g_{l}
        \sum_{r\ge 1}\frac{X^{Nr}}{r}
        \sum_{\substack{j_{1}+\cdots +j_{r}=l              \\ 1\le j_{1}, \ldots , j_{r}\le N}}
        c_{j_{1}} \cdots c_{j_{r}}.
\end{align*}
By using \eqref{eq:stirling-duality},
we see that
\begin{align*}
        g_{k}=\frac{1}{(k-1)!}\sum_{j=1}^{k}{k\brack j}
        (-\hbar)^{k-j}\phi_{j}
        \qquad (k\ge 1)
\end{align*}
{}from the definition \eqref{eq:def-phi} of $\phi_{k}$.
Hence
\begin{align*}
        \Psi(X)=\sum_{k\ge 1}(-\hbar)^{-k}\phi_{k}
        \sum_{r\ge 1}\frac{X^{Nr}}{r}
        \sum_{l\ge 1}
        \frac{1}{(l-1)!}{l \brack k}
        \sum_{\substack{j_{1}+\cdots +j_{r}=l \\ 1\le j_{1}, \ldots , j_{r}\le N}}
        c_{j_{1}} \cdots c_{j_{r}}.
\end{align*}
It follows from \eqref{eq:stirling-first-harmonic} and
the assumption $P \in \mathcal{P}$ that
the term with $k=1$ of the right-hand side vanishes because
\begin{align*}
        \sum_{l\ge 1}\frac{1}{(l-1)!}
        {l \brack 1}
        \sum_{\substack{j_{1}+\cdots +j_{r}=l \\ 1\le j_{1}, \ldots , j_{r}\le N}}
        c_{j_{1}} \cdots c_{j_{r}}=
        \left(\sum_{1\le j \le N}c_{j}\right)^{r}=(P(1))^{r}=0.
\end{align*}
For the terms with $k\ge 2$, we use the following formula.
\begin{lem}\label{lem:stirring-integral}
        For $k \ge 2$ and $l\ge 1$, it holds that
        \begin{align*}
                \frac{1}{(l-1)!}{l \brack k}=
                \frac{1}{(k-1)!}
                \left(\prod_{a=1}^{k-1}\int_{0}^{1}dz_{a}\right)
                G_{l}(z_{1}, \ldots , z_{k-1}),
        \end{align*}
        where $G_{l}(z_{1}, \ldots z_{k-1})$ is given by
        \begin{align*}
                G_{l}(z_{1}, \ldots , z_{k-1})=
                \prod_{j=1}^{k-1}\frac{1}{1-z_{j}}+
                \sum_{a=1}^{k-1}\frac{z_{a}^{l-1}}{z_{a}-1}
                \prod_{\substack{j=1 \\ j\not=a}}^{k-1}\frac{1}{z_{a}-z_{j}}.
        \end{align*}
\end{lem}

\begin{proof}
        By using \eqref{eq:stirling-first-harmonic},
        we see that
        \begin{align*}
                \frac{1}{(l-1)!}{l \brack k}=
                \sum_{l>m_{1}>\cdots >m_{k-1}>0}\frac{1}{m_{1}\cdots m_{k-1}}=
                \left(\prod_{a=1}^{k-1}\int_{0}^{1}dy_{a}\right)
                \sum_{l>m_{1}>\cdots >m_{k-1}>0} \prod_{a=1}^{k-1}y_{a}^{m_{a}-1}.
        \end{align*}
        It holds that
        \begin{align*}
                \sum_{l>m_{1}>\cdots >m_{k-1}>0} \prod_{a=1}^{k-1}y_{a}^{m_{a}-1}=
                \sum_{a=0}^{k-1}(-1)^{a}
                \frac{(y_{1}\cdots y_{a})^{l-1}}{y_{a+1}\cdots y_{k-1}}
                \prod_{j=1}^{a}\frac{1}{1-y_{j}\cdots y_{a}}
                \prod_{j=a+1}^{k-1}\frac{y_{a+1}\cdots y_{j}}{1-y_{a+1}\cdots y_{j}}
        \end{align*}
        (see, e.g., \cite[Proposition 3.3]{INY}).
        By changing the variables $y_{a}$ to $z_{a}=y_{1}\cdots y_{a} \, (1\le a<k)$,
        we obtain the desired formula because
        $G_{l}(z_{1}, \ldots , z_{k-1})$ is symmetric with respect to
        $z_{1}, \ldots , z_{k-1}$.
\end{proof}

Thus we find that
\begin{align*}
        \Psi(X)=\sum_{k\ge 1}\frac{(-\hbar)^{-k}}{(k-1)!}\phi_{k}
        \sum_{r\ge 1}\frac{X^{Nr}}{r}
        \sum_{l\ge 1}
        \left(\prod_{a=1}^{k-1}\int_{0}^{1}dz_{a}\right)
        G_{l}(z_{1}, \ldots , z_{k-1})
        \sum_{\substack{j_{1}+\cdots +j_{r}=l \\ 1\le j_{1}, \ldots , j_{r}\le N}}
        c_{j_{1}} \cdots c_{j_{r}}.
\end{align*}
Since
\begin{align*}
        \sum_{l\ge 1}G_{l}(z_{1}, \ldots , z_{k-1})
        \sum_{\substack{j_{1}+\cdots +j_{r}=l \\ 1\le j_{1}, \ldots , j_{r}\le N}}
        c_{j_{1}} \cdots c_{j_{r}}
        =(P(1))^{r}\prod_{j=1}^{k-1}\frac{1}{1-z_{j}}+
        \sum_{a=1}^{k-1}\frac{(P(z_{a}))^{r}}{z_{a}(z_{a}-1)}
        \prod_{\substack{j=1                  \\ j\not=a}}^{k-1}\frac{1}{z_{a}-z_{j}}
\end{align*}
and the first term is zero because $P \in \mathcal{P}$,
it holds that
\begin{align*}
        \Psi(X) & =
        \sum_{k\ge 2}\frac{(-\hbar)^{-k}}{(k-1)!}\phi_{k}
        \sum_{r\ge 1}\frac{X^{Nr}}{r}
        \left(\prod_{a=1}^{k-1}\int_{0}^{1}dz_{a}\right)
        \sum_{a=1}^{k-1}\frac{(P(z_{a}))^{r}}{z_{a}(z_{a}-1)}
        \prod_{\substack{j=1 \\ j\not=a}}^{k-1}\frac{1}{z_{a}-z_{j}} \\
                & =
        \sum_{k\ge 2}\frac{(-\hbar)^{-k}}{(k-1)!}\phi_{k}
        \left(\prod_{a=1}^{k-1}\int_{0}^{1}dz_{a}\right)
        \sum_{a=1}^{k-1}\frac{(-\mathop{\mathrm{Log}}{(1-X^{N}P(z_{a}))})}{z_{a}(z_{a}-1)}
        \prod_{\substack{j=1 \\ j\not=a}}^{k-1}\frac{1}{z_{a}-z_{j}}.
\end{align*}
Now we set
\begin{align*}
        F_{k}(x)=        \left(\prod_{a=1}^{k-1}\int_{0}^{1}dz_{a}\right)
        \sum_{a=1}^{k-1}\frac{(-\mathop{\mathrm{Log}}{(1-x^{N}P(z_{a}))})}{z_{a}(z_{a}-1)}
        \prod_{\substack{j=1 \\ j\not=a}}^{k-1}\frac{1}{z_{a}-z_{j}}
\end{align*}
for $k \ge 2$,
which is a holomorphic function defined in a neighborhood of $x=0$.
Then
\begin{align*}
        \Psi(X)=\sum_{k\ge 2}\frac{(-\hbar)^{-k}}{(k-1)!}\phi_{k}F_{k}(X).
\end{align*}
Hence, to verify \eqref{eq:main1} with $L=1$,
it suffices to show
\begin{align}
        F_{k}(x)=\frac{1}{k}\sum_{m=1}^{N}
        \left(-\mathop{\mathrm{Log}}(1-\alpha(\epsilon_{N}^{m}x))\right)^{k},
        \label{eq:F_k}
\end{align}
where $\alpha(x)$ is a convergent series satisfying \eqref{eq:def-alpha}.

Since $P \in \mathcal{P}$, we can set $P(z)=z(z-1)Q(z)$ with $Q(z)\in \mathbb{Q}[z]$.
Then
\begin{align*}
        F_{k}'(x)=Nx^{N-1}
        \left(\prod_{a=1}^{k-1}\int_{0}^{1}dz_{a}\right)
        \sum_{a=1}^{k-1}\frac{Q(z_{a})}{1-x^{N}P(z_{a})}
        \prod_{\substack{j=1 \\ j\not=a}}^{k-1}\frac{1}{z_{a}-z_{j}}.
\end{align*}
For simplicity of notation,
we set $\alpha_{m}=\alpha(\epsilon_{N}^{m}x)$
for $1\le m \le N$.
Then, since $\deg{Q}\le \deg{P}-2$ and
$1-x^{N}P(z)=\prod_{m=1}^{N}(1-\alpha_{m}z)$, it holds that
\begin{align*}
         &
        \sum_{a=1}^{k-1}\frac{Q(z_{a})}{1-x^{N}P(z_{a})}
        \prod_{\substack{j=1                                  \\ j\not=a}}^{k-1}\frac{1}{z_{a}-z_{j}}=
        \sum_{a=1}^{k-1}\mathrm{Res}_{w=z_{a}}dw
        \frac{Q(w)}{1-x^{N}P(w)}
        \prod_{j=1}^{k-1}\frac{1}{w-z_{j}}                    \\
         & =-\sum_{m=1}^{N}\mathrm{Res}_{w=\alpha_{m}^{-1}}dw
        \frac{Q(w)}{1-x^{N}P(w)}\prod_{j=1}^{k-1}\frac{1}{w-z_{j}}
        =x^{-N}\sum_{m=1}^{N}
        \frac{Q(\alpha_{m}^{-1})}{P'(\alpha_{m}^{-1})}
        \prod_{j=1}^{k-1}\frac{\alpha_{m}}{1-\alpha_{m}z_{j}}.
\end{align*}
We have $1-x^{N}P(\alpha_{m}^{-1})=0$
in a neighborhood of $x=0$.
By differentiating both sides with respect to $x$ and
using $P(z)=z(z-1)Q(z)$, we see that
\begin{align*}
        \frac{Q(\alpha_{m}^{-1})}{P'(\alpha_{m}^{-1})}=\frac{x}{N(1-\alpha_{m})}\,\frac{d\alpha_{m}}{dx}.
\end{align*}
Thus we find that
\begin{align*}
        F_{k}'(x)
         & =\sum_{m=1}^{N}\frac{1}{1-\alpha_{m}}\frac{d\alpha_{m}}{dx}
        \left(\prod_{a=1}^{k-1}\int_{0}^{1}dz_{a}\right)
        \prod_{j=1}^{k-1}\frac{\alpha_{m}}{1-\alpha_{m}z_{j}}                 \\
         & =\sum_{m=1}^{N}\frac{1}{1-\alpha_{m}}\frac{d\alpha_{m}}{dx}
        \left(\int_{0}^{1}dz \, \frac{\alpha_{m}}{1-\alpha_{m}z}\right)^{k-1} \\
         & =\sum_{m=1}^{N}\frac{1}{1-\alpha_{m}}\frac{d\alpha_{m}}{dx}
        \left(-\mathop{\mathrm{Log}}(1-\alpha_{m})\right)^{k-1}
        =\frac{d}{dx}\left(\frac{1}{k}\sum_{m=1}^{N}
        \left(-\mathop{\mathrm{Log}}(1-\alpha_{m})\right)^{k}\right).
\end{align*}
Since $F_{k}(0)=0$ and $\alpha_{m}|_{x=0}=0$ for $1\le m \le N$,
we obtain \eqref{eq:F_k}.
This completes the proof of \eqref{eq:main1} with $L=1$.


