\section{A solvable case}\label{sec:solvable}

In order to write the formula \eqref{eq:main1} explicitly,
we need to find a power series $\alpha(x)$ satisfying \eqref{eq:def-alpha}
and calculate the logarithm $\mathrm{Log}(1-\alpha(x))$.
As an example where such a calculation can be performed,
we consider the case where
\begin{align*}
        P(z)=z^{N-1}(z-1) \qquad (N\ge 2).
\end{align*}
Then we have $\psi_{P}=(-\hbar)^{-N}e_{N}$
as seen in the beginning of Section \ref{sec:main}.

\begin{prop}\label{prop:varphi}
        Define the power series $\varphi(\theta; x)$ in $x$ by
        \begin{align}
                \varphi(\theta; x)=\sum_{k\ge 1}\frac{x^{k}}{k!}\prod_{a=1}^{k-1}(k\theta-a).
                \label{eq:def-varphi}
        \end{align}
        Set
        \begin{align}
                \alpha(x)=1-e^{\varphi(1/N; -x)}.
                \label{eq:alpha-varphi}
        \end{align}
        Then, for $P(z)=z^{N-1}(z-1)$, we have
        \begin{align}
                1-x^{N}P(z)=\prod_{m=1}^{N}(1-\alpha(\epsilon_{N}^{m}x)z).
                \label{eq:alpha-factorize}
        \end{align}
\end{prop}

See Appendix \ref{sec:app2} for the proof of Proposition \ref{prop:varphi}.
It implies the following identity.

\begin{thm}\label{thm:main2}
        For $N\ge 2$ and $L\ge 1$, it holds that
        \begin{align}
                \frac{1}{1+\hbar^{-NL}e_{N}^{\circ_{\hbar L}}X^{NL}}=
                \exp_{\ast_{\hbar}}{\left(-\sum_{k\ge 2}\frac{\hbar^{-k}}{k!}\phi_{k}
                        \sum_{m=1}^{NL}\left(\varphi(1/N; \epsilon_{NL}^{m}X)\right)^{k}
                        \right)},
                \label{eq:main-eN}
        \end{align}
        where $\varphi(\theta; x)$ is defined by \eqref{eq:def-varphi}.
\end{thm}

\begin{proof}
        Substitute \eqref{eq:alpha-varphi} into \eqref{eq:main1}
        and change $X \to -X$.
\end{proof}

As seen below the series $\varphi(1/N; x)$ with $N=2$ is essentially equal to
the arcsin function.
Thus we obtain Bachmann's identity
within the algebraic framework.

\begin{cor}
        For $L\ge 1$, it holds that
        \begin{align}
                \frac{1}{1+(-1)^{L}\hbar^{-2L}e_{2}^{\circ_{\hbar}L}X^{2L}}=
                \exp_{\ast_{\hbar}}{\left(2
                        \sum_{k\ge 1}\frac{(-1)^{k-1}}{(2k)!}\hbar^{-2k}\phi_{2k}
                        \sum_{m=1}^{L}
                        \left( 2\arcsin{\frac{e^{m\pi i/L}X}{2}} \right)^{2k}
                        \right)}.
                \label{eq:main-e2}
        \end{align}
        In particular, the equality \eqref{eq:Bachmann3} holds.
\end{cor}

\begin{proof}
        We have
        \begin{align*}
                \varphi(\frac{1}{2}; x)=x\,
                {}_{2}F_{1}\left(\frac{1}{2}, \frac{1}{2}, \frac{3}{2}; -\frac{x^{4}}{2}\right)=
                -2i\arcsin{\frac{ix}{2}},
        \end{align*}
        where ${}_{2}F_{1}(\alpha, \beta, \gamma; z)$ is
        the Gauss hypergeometric series.
        Substitute it into \eqref{eq:main-eN} with $N=2$ and
        change $X$ to $iX$.
        Then the terms with odd $k$ vanish because
        the arcsin function is odd.
        Thus we obtain \eqref{eq:main-e2}.
\end{proof}

We write the sum over $1\le m \le NL$
in the right-hand side of $\eqref{eq:main-eN}$ more explicitly.

\begin{prop}\label{prop:varphi-power}
        For $k\ge 1$, it holds that
        \begin{align*}
                \frac{\left(\varphi(\theta; x)\right)^{k}}{k!}=
                \sum_{n\ge 1}\frac{x^{n}}{n!}
                \sum_{j\ge k}(-1)^{n-j}
                {n \brack j}
                \binom{j-1}{k-1}(n\theta)^{j-k}.
        \end{align*}
\end{prop}

See Appendix \ref{sec:app2} for the proof of
Proposition \ref{prop:varphi-power}.

For $n\ge 1$, we set $H_{0}(n)=1$ and
\begin{align*}
        H_{r}(n)=\sum_{0<m_{1}<\cdots <m_{r}<n}\frac{1}{m_{1}\cdots m_{r}}
\end{align*}
for $r\ge 1$.
Note that $H_{r}(n)=0$ if $1\le n\le r$.
For $m \ge 0$ and $n_{1}, n_{2} \ge 1$, we set
\begin{align*}
        C_{m}(n_{1}, n_{2})=\sum_{a=0}^{m}(-1)^{m-a}
        H_{a}(n_{1})H_{m-a}(n_{2}).
\end{align*}
We have $C_{m}(n_{1}, n_{2})=0$ if $m\ge n_{1}+n_{2}-1$.

\begin{thm}
        For $N\ge 2$ and $L \ge 1$, it holds that
        \begin{align}
                 &
                \frac{1}{1+(-1)^{(N-1)L}\hbar^{-NL}e_{N}^{\circ_{\hbar} L}X}
                \label{eq:main-eN-explicit}    \\
                 & =\exp_{\ast_{\hbar}}{\left(
                \frac{N}{(N-1)L}\sum_{n\ge 1}
                \frac{X^{n}}{n^{2}\binom{NLn}{Ln}}
                \sum_{k=2}^{NLn}C_{k-2}(Ln, (N-1)Ln)\hbar^{-k}\phi_{k}
                \right)}.
                \nonumber
        \end{align}
\end{thm}

\begin{proof}
        For $k\ge 1$, we define the polynomial $D_{k}(x)$ by
        \begin{align*}
                D_{k}(x)=\sum_{j\ge k}(-1)^{NLn-j}{NLn \brack j}
                \binom{j-1}{k-1}x^{j-k}.
        \end{align*}
        {}From Proposition \ref{prop:varphi-power} and
        \begin{align*}
                \sum_{m=1}^{NL}(\epsilon_{NL}^{m}x)^{n}=\left\{
                \begin{array}{ll}
                        NL \, x^{n} & (NL \mid  n)          \\
                        0           & (\textrm{otherwise}),
                \end{array}
                \right.
        \end{align*}
        we see that
        \begin{align*}
                \frac{1}{k!}\sum_{m=1}^{NL}(\varphi(1/N; \epsilon^{m}_{NL}x))^{k}=
                NL\sum_{n\ge 1}\frac{x^{NLn}}{(NLn)!}D_{k}(Ln).
        \end{align*}
        It follows from \eqref{eq:shifted-factorial} that
        \begin{align*}
                D_{k}(x)
                 & =\frac{1}{(k-1)!}\left(\frac{d}{dx}\right)^{k-1}
                \sum_{j\ge 1}(-1)^{NLn-j}{NLn \brack j}
                x^{j}                                               \\
                 & =\frac{1}{(k-1)!}\left(\frac{d}{dx}\right)^{k-1}
                \prod_{a=1}^{NLn-1}(x-a)                            \\
                 & =\sum_{\substack{p+q+r=k-1                       \\ p, q, r\ge 0}}
                \frac{1}{p!q!r!}
                \left\{\left(\frac{d}{dx}\right)^{p}\prod_{a=1}^{Ln-1}(x-a)\right\}
                \left\{\left(\frac{d}{dx}\right)^{q}(x-Ln)\right\}
                \left\{\left(\frac{d}{dx}\right)^{r}\prod_{a=Ln+1}^{NLn-1}(x-a)\right\}.
        \end{align*}
        We set $x=Ln$. Then only the terms with $q=1$ remain.
        Hence
        \begin{align*}
                D_{k}(Ln)
                 & =\sum_{\substack{p+r=k-2                                     \\ p, r\ge 0}}
                \frac{1}{p!r!}
                \left\{\left(\frac{d}{dx}\right)^{p}\prod_{a=1}^{Ln-1}(x-a)\right\}
                \left\{\left(\frac{d}{dx}\right)^{r}\prod_{a=Ln+1}^{NLn-1}(x-a)\right\}\bigg|_{x=Ln}
                \\
                 & =(Ln-1)!((N-1)Ln-1)!
                \sum_{\substack{p+r=k-2                                         \\ p, r\ge 0}}
                (-1)^{(N-1)Ln-1-r}
                H_{p}(Ln)H_{r}((N-1)Ln)
                \\
                 & =(-1)^{(N-1)Ln-1}\frac{(NLn)!}{(N-1)(Ln)^{2}\binom{NLn}{Ln}}
                C_{k-2}(Ln, (N-1)Ln).
        \end{align*}
        Therefore, the exponent in the right-hand side of \eqref{eq:main-eN}
        is equal to
        \begin{align*}
                 &
                {}-\sum_{k\ge 2}\frac{\hbar^{-k}}{k!}\phi_{k}
                \sum_{m=1}^{NL}\left(\varphi(1/N; \epsilon_{NL}^{m}X)\right)^{k}
                =-\sum_{k\ge 2}\hbar^{-k}\phi_{k}NL\sum_{n\ge 1}
                \frac{x^{NLn}}{(NLn)!}D_{k}(Ln) \\
                 & =\frac{N}{(N-1)L}
                \sum_{n\ge 1}\frac{((-1)^{(N-1)L}X^{NL})^{n}}{n^2 \binom{NLn}{Ln}}
                \sum_{k\ge 2}C_{k-2}(Ln, (N-1)Ln)\hbar^{-k}\phi_{k}.
        \end{align*}
        By changing $X^{NL} \to (-1)^{(N-1)L}X$, we obtain the desired identity.
\end{proof}

\begin{rem}
        If $N=2$, we have $C_{m}(Ln, (N-1)Ln)=C_{m}(Ln, Ln)$ for $m\ge 0$.
        It holds that, for $m\ge 0$ and $n\ge 1$,
        \begin{align*}
                C_{m}(n, n)=\sum_{a=0}^{m}(-1)^{m-a}H_{a}(n)H_{m-a}(n)=
                \left\{
                \begin{array}{ll}
                        (-1)^{m/2}H_{m/2}^{(2)}(n) & (\hbox{$m$: even}) \\
                        0                          & (\hbox{$m$: odd})
                \end{array}
                \right.
        \end{align*}
        where $H_{0}^{(2)}(n)=1$ and
        \begin{align*}
                H_{r}^{(2)}(n)=\sum_{0<m_{1}<\cdots <m_{r}<n}
                \frac{1}{m_{1}^{2}\cdots m_{r}^{2}}
        \end{align*}
        for $r\ge 1$.
        It is known that
        \begin{align}
                \left(2\arcsin{(X/2)}\right)^{2k}=(2k)!
                \sum_{n\ge k} \frac{H_{k-1}^{(2)}(n)}{n^2 \binom{2n}{n}}X^{2n}
                \label{eq:arcsin-expansion}
        \end{align}
        for $k\ge 1$ (see \cite{BC}).
        By changing $X\to X^{2L}$ in \eqref{eq:main-eN-explicit} and using
        \eqref{eq:arcsin-expansion},
        we recover \eqref{eq:main-e2}.
\end{rem}

Applying the map $Z_{q}$ to both sides of \eqref{eq:main-eN-explicit},
we obtain the following identity.

\begin{cor}
        Suppose that $N\ge 2$ and $L\ge 1$.
        We set
        \begin{align*}
                A_{r}^{(N, L)}(q)=
                \sum_{0<m_{1}<\cdots <m_{r}}
                \left(\frac{q^{(N-1)(m_{1}+\cdots +m_{r})}}
                {(1-q^{m_{1}})^{N} \cdots (1-q^{m_{r}})^{N}}
                \right)^{L}
        \end{align*}
        for $r\ge 1$.
        Then it holds that
        \begin{align*}
                 &
                1+\sum_{r\ge 1}(-1)^{((N-1)L-1)r}A_{r}^{(N, L)}(q)X^{r} \\
                 & =
                \exp{\left(
                \frac{N}{(N-1)L}\sum_{n\ge 1}
                \frac{X^{n}}{n^{2}\binom{NLn}{Ln}}
                \sum_{k=2}^{NLn}C_{k-2}(Ln, (N-1)Ln)G_{k}(q)
                \right)}.
        \end{align*}
\end{cor}

