\section{Application to $\omega$MZVs}\label{sec:omega-MZV}

\subsection{Definition of $\omega$MZV}

We assume that $\omega >0$.
Let $M(\mathbb{C})$ be
the field of meromorphic functions on $\mathbb{C}$.
We endow $M(\mathbb{C})$ with the structure of a $\mathcal{C}$-module
such that $\hbar^{\pm 1}$ acts as multiplication by $(2\pi i \omega)^{\pm 1}$.
Then we define the $\mathcal{C}$-linear map
$J_{\omega}: \mathfrak{z} \to M(\mathbb{C})$ by
\begin{align*}
        J_{\omega}(e_{1}-g_{1} \, | \, t)=2\pi i \omega, \qquad
        J_{\omega}(g_{k} \, | \, t)=\left(
        \frac{2\pi i \omega \, e^{2\pi i \omega t}}{1-e^{2\pi i \omega t}}
        \right)^{k}
        =\left(        \frac{2\pi i \omega }{e^{-2\pi i \omega t}-1}
        \right)^{k}
\end{align*}
for $k \ge 1$.

For $u_{1}, \ldots , u_{r} \in \mathcal{A}$ such that $u_{r}\not=e_{1}-g_{1}$,
we consider the multiple integral
\begin{align}
        Z_{\omega}(u_{1}\cdots u_{r})=
        \prod_{a=1}^{r}\int_{{}-\epsilon+i\,\mathbb{R}}\frac{dt_{a}}{e^{2\pi i t_{a}}-1}
        \prod_{a=1}^{r}J_{\omega}(u_{a}\,|\, t_{1}+\cdots +t_{a}),
        \label{eq:def-omega-zeta}
\end{align}
where $\epsilon$ is a constant satisfying $0<\epsilon<\min\{1, 1/r \omega\}$.

\begin{prop}\label{prop:omega-zeta-convergence}
        If $\omega>0$, the integral \eqref{eq:def-omega-zeta} is absolutely convergent.
        It does not depend on $\epsilon$.
\end{prop}

\begin{rem}
        Although we assumed that $0<\omega<2$ for absolute convergence
        in the previous paper \cite{T-omega},
        the condition can be relaxed to $\omega>0$ as shown in the following proof.
\end{rem}

\begin{proof}
        {}From the assumption we can set $u_{r}=g_{k}$ with $k \ge 1$.
        Set $t_{a}=-\epsilon+iu_{a}$ with $u_{a} \in \mathbb{R}$ for  $1\le a \le r$.
        Then the integrand is estimated from above by
        $C\exp{(\pi S(u))}$, where $C$ is a positive constant which depends on
        $\epsilon, \omega, r$ and $k$, and $S(u)$ is given by
        \begin{align*}
                S(u)=\sum_{a=1}^{r}(u_{a}-|u_{a}|)-k\omega
                \left(\sum_{a=1}^{r}u_{a}+\left|\sum_{a=1}^{r}u_{a}\right|\right)
        \end{align*}
        (see the proof of \cite[Proposition 3.1]{T-omega}).
        Since $\omega>0$ and $k\ge 1$, we have
        \begin{align*}
                S(u) \le
                \sum_{a=1}^{r}(u_{a}-|u_{a}|)-\omega
                \left(\sum_{a=1}^{r}u_{a}+\left|\sum_{a=1}^{r}u_{a}\right|\right)
                =(1-\omega)\sum_{a=1}^{r}u_{a}-\sum_{a=1}^{r}|u_{a}|-
                \omega\left|\sum_{a=1}^{r}u_{a}\right|.
        \end{align*}
        Take a constant $\rho$ such that $-\omega<\rho<\min{\{\omega, 2-\omega\}}$.
        The right-hand side is equal to
        \begin{align*}
                \rho\sum_{a=1}^{r}u_{a}-\omega\left|\sum_{a=1}^{r}u_{a}\right|+
                \sum_{a=1}^{r}((1-\omega-\rho)u_{a}-|u_{a}|).
        \end{align*}
        It is estimated from above by
        \begin{align*}
                |\rho|\left|\sum_{a=1}^{r}u_{a}\right|-\omega\left|\sum_{a=1}^{r}u_{a}\right|+
                \sum_{a=1}^{r}(|1-\omega-\rho||u_{a}|-|u_{a}|).
        \end{align*}
        Since $|\rho|<\omega$, we obtain
        \begin{align*}
                S(u)\le -(1-|1-\omega-\rho|)\sum_{a=1}^{r}|u_{a}|.
        \end{align*}
        It holds that $|1-\omega-\rho|<1$ because $-\omega<\rho<2-\omega$.
        Therefore the integral \eqref{eq:def-omega-zeta} is absolutely convergent
        and independent of $\epsilon$.
\end{proof}

We define, by abuse of notation, the $\mathcal{C}$-linear map
$Z_{\omega}: \widehat{\mathfrak{H}^{0}} \to \mathbb{C}$ by
$Z_{\omega}(1)=1$ and \eqref{eq:def-omega-zeta}.
We call the value $Z_{\omega}(w)$ with $w \in \widehat{\mathfrak{H}^{0}}$
an \textit{$\omega$-deformed multiple zeta value} ($\omega$MZV).

\begin{prop}\cite[Theorem 4.5]{T-omega}
        For any $w, w' \in \widehat{\mathfrak{H}^{0}}$,
        it holds that $Z_{\omega}(w \ast_{\hbar} w')=Z_{\omega}(w)Z_{\omega}(w')$.
\end{prop}

Therefore, we can apply the results in the previous section to
$\omega$MZVs.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Function $G_{s}(\omega)$ and its series expression}

Here we calculate $Z_{\omega}(\hbar^{-k}\phi_{k})$ for $k\ge 1$,
which is a corresponding object to the $q$-series
$G_{k}(q)=\sum_{n\ge 1}\sigma_{k-1}(n)q^{n}$.

\begin{prop}\label{prop:G-omega}
        For $k\ge 1$, it holds that
        \begin{align*}
                Z_{\omega}(\hbar^{-k}\phi_{k})=
                \int_{-\epsilon+i\,\mathbb{R}}dt\,
                \frac{(-t)^{k-1}}{(e^{2\pi i t}-1)(e^{-2\pi i \omega t}-1)}.
        \end{align*}
\end{prop}

To show Proposition \ref{prop:G-omega},
we use the following results.

\begin{prop}\cite[Proposition 3.5]{T-omega}\label{prop:omega-MZV-explicit}
        Let $r$ be a positive integer and suppose that
        $0<\epsilon<\min{\{1, 1/r\omega\}}$.
        It holds that
        \begin{align*}
                 &
                Z_{\omega}((e_{1}-g_{1})^{\alpha_{1}}g_{\beta_{1}+1} \cdots
                (e_{1}-g_{1})^{\alpha_{r}}g_{\beta_{r}+1})        \\
                 & =\prod_{a=1}^{r}\int_{-\epsilon+i\,\mathbb{R}}
                \frac{dt_{a}}{e^{2\pi i t_{a}}-1}
                \prod_{a=1}^{r}\left\{
                (-2\pi i \omega)^{\alpha_{a}}
                \binom{t_{a}+\alpha_{a}}{\alpha_{a}}
                \left(\frac{2\pi i \omega \, e^{2\pi i \omega (t_{1}+\cdots +t_{a})}}
                {1-e^{2\pi i \omega (t_{1}+\cdots +t_{a})}}
                \right)^{\beta_{a}+1}
                \right\}
        \end{align*}
        for any non-negative integers $\alpha_{1}, \ldots , \alpha_{r}$
        and $\beta_{1}, \ldots , \beta_{r}$.
\end{prop}


\begin{prop}\cite[Theorem 4.3]{T-omega}\label{prop:omega-duality}
        For any $r\ge 1$ and $\alpha_{1}, \ldots , \alpha_{r}, \beta_{1}, \ldots , \beta_{r}\ge 0$,
        it holds that
        \begin{align*}
                Z_{\omega}((e_{1}-g_{1})^{\alpha_{1}}g_{\beta_{1}+1} \cdots
                (e_{1}-g_{1})^{\alpha_{r}}g_{\beta_{r}+1})=
                Z_{\omega}((e_{1}-g_{1})^{\beta_{r}}g_{\alpha_{r}+1} \cdots
                (e_{1}-g_{1})^{\beta_{1}}g_{\alpha_{1}+1}).
        \end{align*}
\end{prop}

\begin{proof}[Proof of Proposition \ref{prop:G-omega}]
        Proposition \ref{prop:omega-duality} implies that
        $Z_{\omega}(g_{j})=Z_{\omega}((e_{1}-g_{1})^{j-1}g_{1})$ for $j\ge 1$.
        Therefore, it follows from Proposition \ref{prop:omega-MZV-explicit} that
        \begin{align*}
                Z_{\omega}(\hbar^{-k}\phi_{k}) & =
                \sum_{j=1}^{k}(j-1)!{k \brace j}
                (2\pi i \omega)^{-j}Z_{\omega}((e_{1}-g_{1})^{j-1}g_{1}) \\
                                               & =
                \int_{-\epsilon+i\,\mathbb{R}}
                \frac{dt}{(e^{2\pi i t}-1)(e^{-2\pi i \omega t}-1)}
                \sum_{j=1}^{k}(j-1)!{k \brace j}
                (-1)^{j-1}\binom{t+j-1}{j-1}.
        \end{align*}
        By using \eqref{eq:stirling-duality} and \eqref{eq:shifted-factorial},
        we see that
        \begin{align*}
                 &
                \sum_{j=1}^{k}(j-1)!{k \brace j}
                (-1)^{j-1}\binom{t+j-1}{j-1}
                =\sum_{j=1}^{k}(-1)^{j-1}{k \brace j}
                \prod_{a=1}^{j-1}(t+a)
                \\
                 & =\sum_{l=0}^{k-1}t^{l}\sum_{j=l+1}^{k}
                (-1)^{j-1}
                {k \brace j}{j \brack l+1}=(-t)^{k-1}.
        \end{align*}
        Thus we obtain the desired formula.
\end{proof}

Motivated by Proposition \ref{prop:G-omega},
we introduce the function
\begin{align}
        G_{s}(\omega)=\int_{C} dt\,
        \frac{(-t)^{s-1}}{(e^{2\pi i t}-1)(e^{-2\pi i \omega t}-1)}
        \label{eq:def-G-omega}
\end{align}
for a parameter $s \in \mathbb{C}$,
where $(-t)^{s-1}=e^{(s-1)\mathrm{Log}{(-t)}}$
is the principal value.
The contour $C$ is defined to be a rotation about $t=0$ of
the line $-\epsilon+i\mathbb{R}$ with $0<\epsilon<\min\{1,1/\omega\}$
which separates the poles at
$\mathbb{Z}_{\ge 0} \cup (\omega^{-1}\mathbb{Z}_{\ge 0})$ from those at
$\mathbb{Z}_{\le -1} \cup (\omega^{-1}\mathbb{Z}_{\le -1})$.
The integral is independent of the rotation angle because
the integrand behaves as $e^{-c|t|}$ with some $c>0$ as $|t|\to +\infty$
in any closed angle with vertex at $t=0$ contained in
the region $\mathbb{C}\setminus(\mathbb{R} \cup \omega^{-1}\mathbb{R})$.

The function $G_{s}(\omega)$ is holomorphic on
the cut plane $\mathbb{C}'=\mathbb{C}\setminus\mathbb{R}_{\le 0}$.
It has the following series expression.

\begin{prop}\label{prop:G-series}
        If $\mathrm{Re}s>2$, it holds that
        \begin{align}
                G_{s}(\omega)=(2\pi)^{-s}\Gamma(s)\left(
                e^{-s\pi i/2}
                \sum_{m\ge 0, \, n\ge 1}(m+n\omega)^{-s}-
                e^{s\pi i/2}
                \sum_{m\ge 1, \, n\ge 0}(m+n\omega)^{-s}
                \right).
                \label{eq:G-series}
        \end{align}
        If $s=2$, we have
        \begin{align}
                G_{2}(\omega)=(2\pi i)^{-2}\zeta(2)\left(\omega^{-2}-1\right)-
                \frac{1}{4\pi i \omega}.
                \label{eq:G-at-two}
        \end{align}
\end{prop}

\begin{proof}
        We may assume that $\omega>0$.

        First we consider the case where $\mathrm{Re}s>2$.
        Set $C_{\epsilon, \pm}=\{ix \mid \pm x \ge \epsilon\}$
        and $C_{\epsilon, 0}=\{\epsilon e^{i\theta} \mid \pi/2\le \theta\le 3\pi/2\}$.
        We deform the contour $C=-\epsilon+i\,\mathbb{R}$
        to $(C_{\epsilon, -})^{-1}\cup (C_{\epsilon, 0})^{-1} \cup C_{\epsilon, +}$.
        We denote the integrand of the right-hand side of \eqref{eq:def-G-omega}
        by $f(t)$.
        In the limit as $\epsilon \to +0$, it holds that
        \begin{align*}
                \int_{C_{\epsilon, +}}f(t)\,dt
                 & =
                \int_{\epsilon}^{\infty} idx\,(-ix)^{s-1}
                \frac{-e^{-2\pi \omega x}}{(1-e^{-2\pi x})(1-e^{-2\pi \omega x})} \\
                 & \to
                e^{-s\pi i/2}
                \int_{0}^{\infty} dx\,x^{s-1}
                \frac{e^{-2\pi \omega x}}{(1-e^{-2\pi x})(1-e^{-2\pi \omega x})}.
        \end{align*}
        since $\mathrm{Re}s>2$.
        It is equal to
        \begin{align*}
                e^{-s\pi i/2}\sum_{m\ge 0, \, n\ge 1}
                \int_{0}^{\infty} dx\,x^{s-1}e^{-2\pi (m+n\omega)x}=
                (2\pi)^{-s}\Gamma(s)e^{-s\pi i/2}\sum_{m\ge 0, \, n\ge 1} (m+n\omega)^{-s}.
        \end{align*}
        Similarly we find that
        \begin{align*}
                \int_{C_{\epsilon, -}}f(t)\,dt \to
                -(2\pi)^{-s}\Gamma(s)e^{s\pi i/2}\sum_{m\ge 1, \, n\ge 0} (m+n\omega)^{-s}
        \end{align*}
        as $\epsilon \to +0$ by setting $t=-ix$.
        Since $|f(t)|=O(|t|^{\mathrm{Re}s-3})$ as $t\to 0$,
        the integral $\int_{C_{\epsilon, 0}}f(t)\,dt$ vanishes
        in the limit as $\epsilon \to +0$ if $\mathrm{Re}s>2$.
        Thus we get \eqref{eq:G-series}.

        Next we consider the case of $s=2$.
        Then
        \begin{align*}
                \left(\int_{C_{\epsilon, +}}+\int_{(C_{\epsilon, -})^{-1}}\right)f(t)\,dt=
                \left(\int_{\epsilon}^{\infty}+\int_{-\infty}^{-\epsilon}\right)dx\,
                \frac{x}{(e^{-2\pi x}-1)(e^{2\pi \omega x}-1)}.
        \end{align*}
        By changing the variable $x$ to $-x$ in the second term, we get
        \begin{align*}
                 &
                \int_{\epsilon}^{\infty}dx\, \left(
                \frac{x}{(e^{-2\pi x}-1)(e^{2\pi \omega x}-1)}-\frac{x}{(e^{2\pi x}-1)(e^{-2\pi \omega x}-1)}
                \right)                                   \\
                 & =\int_{\epsilon}^{\infty}dx\, x \left(
                \frac{1}{e^{2\pi x}-1}-\frac{1}{e^{2\pi \omega x}-1}
                \right)                                   \\
                 & \to
                \int_{0}^{\infty}\frac{x}{e^{2\pi x}-1}dx-
                \int_{0}^{\infty}\frac{x}{e^{2\pi \omega x}-1}dx
                =\left(1-\omega^{-2}\right) (2\pi)^{-2}\zeta(2)
        \end{align*}
        in the limit as $\epsilon \to +0$.
        Since $f(t)=-(2\pi i)^{-2}\omega^{-1}t^{-1}+O(1)$ as $t \to 0$,
        it holds that
        \begin{align*}
                \int_{(C_{\epsilon, 0})^{-1}}f(t)\, dt \to -\pi i
                \left(-\frac{1}{(2\pi i)^{2}\omega}\right)=
                \frac{1}{4\pi i \omega}
                \qquad (\epsilon \to +0).
        \end{align*}
        Thus we obtain \eqref{eq:G-at-two}.
\end{proof}


