\subsection{A generating series of $\omega$MZVs}

By applying the map $Z_{\omega}$ to both sides of
\eqref{eq:main-eN} or \eqref{eq:main-eN-explicit},
we obtain a formula for the generating series
of the $\omega$MZVs $Z_{\omega}((e_{N}^{\circ_{\hbar}L})^{r}) \, (r\ge 1)$
with fixed $N\ge 2$ and $L\ge 1$.
For simplicity, we write it only in the case of $N=2$.

It holds that
\begin{align}
        \log{\frac{\sin{\pi i x}}{\pi i x}}=
        \sum_{k\ge 1}\frac{(-1)^{k-1}}{k}\zeta(2k)x^{2k}=
        \sum_{n\ge 1}\frac{B_{2n}}{(2n)!}\frac{(2\pi x)^{2n}}{2n},
        \label{eq:bernoulli-even}
\end{align}
where $B_{n}$ is the Bernoulli number.
As an $\omega$-deformation of the Bernoulli number,
we define the set of polynomials $\{B_{2m}(\omega)\}_{m\ge 1}$
by the expansion
\begin{align}
        \log{\left(\frac{\sin{(\omega^{-1}\arcsin{(\pi i \omega x)})}}{\pi i x}\right)}=
        \sum_{n=1}^{\infty}\frac{B_{2n}(\omega)}{(2n)!}\frac{(2\pi x)^{2n}}{2n}.
        \label{eq:bernoulli-omega}
\end{align}
For example, we have
\begin{align*}
        B_{2}(\omega)
         & =-\frac{\omega^{2}-1}{6},                                                                             \\
        B_{4}(\omega)
         & =\frac{11\omega^{4}-10\omega^2-1}{30}=\frac{(\omega^2-1)(11\omega^2+1)}{30},                          \\
        B_{6}(\omega)
         & =-\frac{191\omega^6-168\omega^4-21\omega^2-2}{84}=-\frac{(\omega^2-1)(191\omega^4+23\omega^2+2)}{84}, \\
        B_{8}(\omega)
         & =\frac{2497\omega^8-2160\omega^6-294\omega^4-40\omega^2-3}{90}=
        \frac{(\omega^2-1)(11\omega^2+1)(227\omega^4+10\omega^2+3)}{90}.
\end{align*}
It follows from the definition that
$B_{2n}(\omega) \to B_{2n}$ in the limit as $\omega \to 0$.

\begin{thm}
        For $L\ge 1$, it holds that
        \begin{align*}
                1+\sum_{r\ge 1}(-1)^{(L-1)r}
                Z_{\omega}((e_{2}^{\circ_{\hbar} L})^{r})X^{r}=
                \exp{\left(L\sum_{n\ge 1}X^{n}
                        \left(-\frac{1}{\pi i \omega}\frac{(2\pi i \omega)^{2Ln}}{(Ln)^{2}\binom{2Ln}{Ln}}+
                        \frac{B_{2Ln}(\omega)}{(2Ln)!}\frac{(2\pi )^{2Ln}}{2Ln}
                        \right)
                        \right)}.
        \end{align*}
\end{thm}

\begin{proof}
        We apply the map $Z_{\omega}$ to both sides of \eqref{eq:main-e2},
        and change $X \to 2\pi i \omega X$.
        Then we obtain
        \begin{align}
                1+\sum_{r\ge 1}(-1)^{(L-1)r}Z_{\omega}((e_{2}^{\circ_{\hbar}L})^{r})X^{2Lr}=
                \exp{\left(\sum_{m=1}^{L}H(e^{m\pi i/L}X)\right)},
                \label{eq:e2-omega-generating}
        \end{align}
        where
        \begin{align*}
                H(X)=2\sum_{k\ge 1}
                \frac{(-1)^{k-1}}{(2k)!}Z_{\omega}(\hbar^{-2k}\phi_{2k})
                \sum_{m=1}^{L}\left(2\arcsin{(\pi i \omega X)}\right)^{2k}.
        \end{align*}
        It follows from Corollary \ref{cor:G-integer} and \eqref{eq:bernoulli-even}
        that
        \begin{align}
                H(X)
                 & =\sum_{k\ge 1}\frac{(-1)^{k-1}}{k}
                \left(\zeta(2k)(2\pi i)^{-2k}(\omega^{-2k}-1)-\frac{\delta_{k1}}{4\pi i \omega}\right)
                \left(2\arcsin{(\pi i \omega X)}\right)^{2k}
                \label{eq:formula-HX}
                \\
                 & =-\frac{\arcsin^{2}(\pi i \omega X)}{\pi i \omega}+
                \log{\frac{\sin{(\omega^{-1}\arcsin{(\pi i \omega X)})}}{\pi i X}}.
                \nonumber
        \end{align}
        By using \eqref{eq:arcsin-expansion} with $k=1$ and \eqref{eq:bernoulli-omega},
        we obtain
        \begin{align*}
                H(X)=-\frac{1}{\pi i \omega}
                \sum_{n\ge 1}\frac{(2\pi i \omega X)^{2n}}{n^2 \binom{2n}{n}}+
                \sum_{n\ge 1}\frac{B_{2n}(\omega)}{(2n)!}\frac{(2\pi X)^{2n}}{2n}.
        \end{align*}
        Now we get the desired equality by using
        \begin{align*}
                \sum_{m=1}^{L}(e^{m\pi i/L}X)^{2n}=\left\{
                \begin{array}{ll}
                        L\,X^{2n} & (L\mid n) \\ 0 & (\hbox{otherwise})
                \end{array}
                \right.
        \end{align*}
        and changing $X^{2L} \to X$.
\end{proof}



\begin{cor}\label{cor:omega-MZV-222}
        It holds that
        \begin{align*}
                1+\sum_{r\ge 1}Z_{\omega}(e_{2}^{r})X^{2r}=
                \frac{\sin{(\omega^{-1}\arcsin{(\pi i \omega X)})}}{\pi i X}
                \exp{\left(-\frac{\arcsin^{2}{(\pi i \omega X)}}{\pi i \omega}\right)}.
        \end{align*}
\end{cor}

\begin{proof}
        It follows from \eqref{eq:e2-omega-generating} with $L=1$ and
        \eqref{eq:formula-HX} because $H(-X)=H(X)$.
\end{proof}


