\section{Stirling numbers}\label{sec:app-stirling}

Stirling numbers ${m\brack n}$ and ${m\brace n}$
are defined by the initial condition
\begin{align*}
        {m\brack 0}={0 \brack m}=\delta_{m, 0}, \qquad
        {m\brace 0}={0\brace m}=\delta_{m, 0}
\end{align*}
and the recurrence relations
\begin{align}
        {m+1 \brack n }={m \brack n-1}+m{m \brack n},
        \qquad
        {m+1 \brace n}={m \brace n-1}+n{m \brace n}
        \label{eq:recurrence-stirling}
\end{align}
for $m, n \in \mathbb{Z}$.
It holds that ${m \brack n}={m \brace n}=0$ if $1\le m<n$.
In this paper we use the following relations.
See, e.g., \cite{AIK} for the proof.
\begin{align}
         &
        \frac{(e^{T}-1)^{m}}{m!}=\sum_{n\ge 1}
        {n \brace m }\frac{T^{n}}{n!} \qquad (m\ge 1),
        \label{eq:stirling-second-exp}
        \\
         &
        \frac{(-\log{(1-T)})^{m}}{m!}=\sum_{n\ge 1}
        {n \brack m}\frac{T^{n}}{n!} \qquad (m\ge 1),
        \label{eq:stirling-first-log}
        \\
         &
        \sum_{j\ge 0}(-1)^{j}{m \brace j} {j \brack n}=(-1)^{m}\delta_{m,n}
        \qquad (m, n\ge 0),
        \label{eq:stirling-duality}  \\
         &
        \prod_{a=1}^{m}(z+a)
        =\sum_{a=0}^{m}{m+1 \brack a+1} z^{a} \qquad (m\ge 0),
        \label{eq:shifted-factorial} \\
         &
        \sum_{l=0}^{n}(-1)^{l}\binom{n}{l}l^{m}=
        (-1)^{n}n!{ m \brace n} \qquad (m, n\ge 0).
        \label{eq:binom-power-sum}
\end{align}
{}From \eqref{eq:shifted-factorial}, we see that
\begin{align}
        { l \brack 1}=(l-1)!, \quad
        {l \brack k}=(l-1)!\sum_{l>m_{1}>\cdots >m_{k-1}>0}
        \frac{1}{m_{1} \cdots m_{k-1}} \qquad (l\ge 1, k\ge 2).
        \label{eq:stirling-first-harmonic}
\end{align}

