\section{Properties of the power series $\varphi(\theta; x$)}\label{sec:app2}

\begin{lem}
        For $m\ge 0$ and $n\ge 1$, it holds that
        \begin{align*}
                \sum_{k=0}^{n}(-1)^{k}\binom{n}{k}(k+1)^{m}=
                (-1)^{n}n! { m+1 \brace n+1 }.
        \end{align*}
        In particular, if $n>m\ge 0$, then we have
        \begin{align}
                \sum_{k=0}^{n-1}(-1)^{k}\binom{n}{k}(k+1)^{m}=
                (-1)^{n-1}(n+1)^{m}.
                \label{eq:lem-power-sum}
        \end{align}
\end{lem}

\begin{proof}
        We have
        \begin{align*}
                \sum_{k=0}^{n}(-1)^{k}\binom{n}{k}(k+1)^{m} & =
                \sum_{k=0}^{n}(-1)^{k}
                \left(\binom{n+1}{k+1}-\binom{n}{k+1}\right)
                (k+1)^{m}                                                                                     \\
                                                            & =\sum_{k=0}^{n+1}(-1)^{k-1}\binom{n+1}{k}k^{m}-
                \sum_{k=0}^{n}(-1)^{k-1}\binom{n}{k}k^{m}.
        \end{align*}
        It follows from \eqref{eq:recurrence-stirling} and \eqref{eq:binom-power-sum}
        that the right-hand side is equal to
        \begin{align*}
                (-1)^{n}(n+1)! {m \brace n+1}-
                (-1)^{n-1}n! {m \brace n}=
                (-1)^{n}n! { m+1 \brace n+1}.
        \end{align*}
\end{proof}


\begin{lem}\label{lem:key-strange}
        For $n\ge 0$, it holds that
        \begin{align}
                \frac{1}{x-y}\left(\prod_{a=1}^{n}(x-a)-\prod_{a=1}^{n}(y-a)\right)=
                \sum_{k=0}^{n-1}\binom{n}{k}
                \prod_{a=1}^{k}\left(\frac{k+1}{n+1}y-a\right)
                \prod_{a=1}^{n-1-k}\left(x-\frac{k+1}{n+1}y-a\right).
                \label{eq:lem-key-strange}
        \end{align}
\end{lem}

\begin{proof}
        It is trivial when $n=0$. We assume that $n\ge 1$.
        Both sides are monic polynomials in $x$ of
        degree $n-1$.
        Hence it suffices to show that they are equal at
        $x=m$ for $1\le m \le n$.
        We denote the right-hand side by $P(x)$.

        Suppose that $1\le m \le n$.
        We calculate
        \begin{align*}
                P(m) & =\sum_{k=0}^{n-1}(-1)^{k}\binom{n}{k}
                \prod_{a=1}^{k}\left(-\frac{k+1}{n+1}y+a\right)
                \prod_{a=m-n+1+k}^{m-1}\left(-\frac{k+1}{n+1}y+a\right) \\
                     & =\sum_{k=0}^{n-1}(-1)^{k}\binom{n}{k}
                \prod_{a=1}^{m-1}\left(-\frac{k+1}{n+1}y+a\right)
                \prod_{a=m-n+1+k}^{k}\left(-\frac{k+1}{n+1}y+a\right)   \\
                     & =\sum_{k=0}^{n-1}(-1)^{k}\binom{n}{k}
                \prod_{a=1}^{m-1}\left(-\frac{k+1}{n+1}y+a\right)
                \prod_{a=1}^{n-m}\left((k+1)(1-\frac{y}{n+1})-a\right).
        \end{align*}
        By using \eqref{eq:shifted-factorial},
        we see that the right-hand side is equal to
        \begin{align*}
                 &
                \sum_{a=0}^{m-1}\sum_{b=0}^{n-m}(-1)^{n-m-b}
                {m \brack a+1} {n-m+1 \brack b+1}
                \left(-\frac{y}{n+1}\right)^{a}
                \left(1-\frac{y}{n+1}\right)^{b} \\
                 & {}\qquad \times
                \sum_{k=0}^{n-1}(-1)^{k}\binom{n}{k}(k+1)^{a+b}.
        \end{align*}
        By applying \eqref{eq:lem-power-sum} to the sum over $0\le k\le n-1$
        and using \eqref{eq:shifted-factorial} again,
        we obtain
        \begin{align*}
                 &
                \sum_{a=0}^{m-1}\sum_{b=0}^{n-m}(-1)^{n-m-b}
                {m \brack a+1}{n-m+1 \brack b+1}
                \left(-\frac{y}{n+1}\right)^{a}
                \left(1-\frac{y}{n+1}\right)^{b}(-1)^{n-1}(n+1)^{a+b} \\
                 & =(-1)^{n-1}
                \sum_{a=0}^{m-1}
                {m \brack a+1 }(-y)^{a}
                \sum_{b=0}^{n-m}
                (-1)^{n-m-b}
                {n-m+1 \brack b+1}
                (n+1-y)^{b}                                           \\
                 & =
                (-1)^{n-1}\prod_{a=1}^{m-1}(-y+a)\prod_{a=1}^{n-m}(n+1-y-a)=
                \prod_{a=1}^{m-1}(y-a)\prod_{a=m+1}^{n}(y-a),
        \end{align*}
        which is equal to the left-hand side of \eqref{eq:lem-key-strange}
        at $x=m$.
\end{proof}

\begin{lem}\label{lem:exp-strange}
        It holds that
        \begin{align}
                e^{\lambda \varphi(\theta; x)}=1+\lambda \sum_{n=1}^{\infty}\frac{x^{n}}{n!}
                \prod_{a=1}^{n-1}(\lambda+n\theta-a).
                \label{eq:exp-strange}
        \end{align}
\end{lem}

\begin{proof}
        Denote the left-hand side by $\Psi(x)$
        and set $\Psi(x)=\sum_{n\ge 0}d_{n}x^{n}$.
        The power series $\Psi(x)$ is uniquely determined from $\Psi(0)=1$ and
        the differential equation
        \begin{align*}
                \Psi'(x)=\lambda
                \left(\sum_{k\ge 0}\frac{x^{k+1}}{k!}\prod_{a=1}^{k}((k+1)\theta-a)\right)
                \Psi(x),
        \end{align*}
        which imply that $d_{0}=1$ and
        the recurrence relation
        \begin{align*}
                d_{n+1}=\frac{\lambda}{n+1}\sum_{k=0}^{n}\frac{d_{n-k}}{k!}
                \prod_{a=1}^{k}((k+1)\theta-a)
        \end{align*}
        for $n\ge 0$.
        We prove
        \begin{align*}
                d_{n}=\frac{\lambda}{n!}\prod_{a=1}^{n-1}(\lambda+n\theta-a)
        \end{align*}
        for $n\ge 1$ by induction on $n$.
        It holds when $n=1$ since $d_{1}=\lambda d_{0}=\lambda$.
        Suppose that $n\ge 1$.
                {}From the induction hypothesis, we see that
        \begin{align*}
                d_{n+1}=\frac{\lambda}{(n+1)!}\left(
                \prod_{a=1}^{n}((n+1)\theta-a)+\lambda
                \sum_{k=0}^{n-1}\binom{n}{k}
                \prod_{a=1}^{k}((k+1)\theta-a)
                \prod_{a=1}^{n-k-1}(\lambda+(n-k)\theta-a)
                \right).
        \end{align*}
        By using \eqref{eq:lem-key-strange} with
        $x=\lambda+(n+1)\theta$ and $y=(n+1)\theta$,
        we see that the sum over $0\le k \le n-1$ is equal to
        \begin{align*}
                \frac{1}{\lambda}\left(
                \prod_{a=1}^{n}(\lambda+(n+1)\theta-a)-\prod_{a=1}^{n}((n+1)\theta-a)
                \right).
        \end{align*}
        Thus we obtain
        \begin{align*}
                d_{n+1}=\frac{\lambda}{(n+1)!}\prod_{a=1}^{n}(\lambda+(n+1)\theta-a).
        \end{align*}
        This completes the proof.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:varphi-power}]
        We expand both sides of \eqref{eq:exp-strange}
        into a power series of $\lambda$.
        We see that
        \begin{align*}
                 &
                \lambda \sum_{n\ge 1}\frac{x^{n}}{n!}
                \prod_{a=1}^{n-1}(\lambda+n\theta-a)=
                \lambda \sum_{n\ge 1}\frac{x^{n}}{n!}
                \sum_{j\ge 1}(-1)^{n-j}{n \brack j}
                (\lambda+n\theta)^{j-1}                                    \\
                 & =              \lambda \sum_{n\ge 1}\frac{x^{n}}{n!}
                \sum_{j\ge 1}(-1)^{n-j}{n \brack j}
                \sum_{k=1}^{j}\binom{j-1}{k-1}(n\theta)^{j-k}\lambda^{k-1} \\
                 & =\sum_{k\ge 1}\lambda^{k}
                \sum_{n\ge 1}\frac{x^{n}}{n!}
                \sum_{j\ge k}(-1)^{n-j}{n \brack j}
                \binom{j-1}{k-1}(n\theta)^{j-k}.
        \end{align*}
        Hence the desired equality holds.
\end{proof}

\begin{prop}
        It holds that
        \begin{align}
                e^{\varphi(\theta; x)}-xe^{\theta\varphi(\theta; x)}=1.
                \label{eq:varphi-rel}
        \end{align}
\end{prop}

\begin{proof}
        Lemma \ref{lem:exp-strange} implies that
        \begin{align*}
                 &
                e^{\varphi(\theta; x)}-xe^{\theta \varphi(\theta; x)} \\
                 & =1+\sum_{n\ge 1}\frac{x^{n}}{n!}
                \prod_{a=1}^{n-1}(1+n\theta-a)-x\left(
                1+\theta \sum_{n\ge 1} \frac{x^{n}}{n!}
                \prod_{a=1}^{n-1}((n+1)\theta-a)
                \right)                                               \\
                 & =1+x+\theta \sum_{n\ge 2}\frac{x^{n}}{(n-1)!}
                \prod_{a=1}^{n-2}(n\theta-a)-x \left(
                1+\theta \sum_{n\ge 2}\frac{x^{n-1}}{(n-1)!}
                \prod_{a=1}^{n-2}(n\theta-a)
                \right)=1.
        \end{align*}
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:varphi}]
        Set $\theta=1/N$ and change $x \to -x$ in
        \eqref{eq:varphi-rel}.
        {}From the obtained equation, we see that
        $\alpha(x)^{N}=x^{N}(1-\alpha(x))$.
        It implies \eqref{eq:alpha-factorize}
        as noted in Remark \ref{rem:existence-alpha}.
\end{proof}


