\section{Relationship between Exponential Flow and Translation Operators}\label{appA1}
\stepcounter{equationschapter}
%\setcounter{equationschapter}{1}
\renewcommand{\theequation}{A.\arabic{equation}}

In this appendix, we derive a formula that establishes a connection between the shift of the argument $\x$ of a smooth function $V(\x)$ by $\X_\tau$ and the exponential map generated by the vector field ${\bm \xi}$, which induces the shift $\X_\tau$. The key identity is:
\bal{nbv5t}
\exp\left(\tau L_{\bm\xi}\right)V(\x)&=&V(\x+\X_\tau)\;,
\ea
where $L_{\bm\xi} = \xi^i \partial_i$ is the Lie derivative along ${\bm \xi}$, and $\X_\tau = \X_\tau(\x)$ is defined by Eq. \eqref{f3}. This identity can also be expressed in the form:
\bal{nb05}
\exp\left(\tau L_{\bm\xi}\right)V(\x)&=&V\left(\exp\left(\tau L_{\bm\xi}\right)\x\right)\;,
\ea
which illustrates the property of {\it equivariance} in the context of Lie diffeomorphism theory.

To prove Eq. \eqref{nbv5t}, we consider the propagation of the gravitational potential $V(\x)$ from the point $\x$ to the point $\x_\tau$ along the integral curve of the congruence defined by Eq. \eqref{f1}, using the exponential map: 
\bal{vb6c4a}
V_\tau&:=&e^{\tau L_{\bm\xi}}V({\bm x})=\sum_{n=0}^\infty\frac{\tau^n}{n!}L_{\bm\xi}^n V({\bm x})\;.
\ea
The operator $L_{\bm\xi}^n$ can be expanded as:
\bal{jk8ba}
\sum_{n=0}^\infty\frac{\tau^n}{n!}L_{\bm\xi}^n V({\bm x})&=&
\sum_{n=0}^\infty\sum_{p=0}^n\frac{\tau^n}{n!}{\bf B}^{i_1i_2\ldots i_p}_{n,p}\left(L_{\bm\xi}\x,L_{\bm\xi}^2\x,...,L_{\bm\xi}^{n-p+1}\x\right)\pd_{i_1i_2\ldots i_p} V({\bm x})\;,
\ea
where, each of the the arguments $L_{\bm\xi}\x=(L_{\bm\xi}x^i)$, $L^2_{\bm\xi}\x=(L^2_{\bm\xi}x^i)$, and so on, have one free index, and 
\bal{het65}\hspace{-1cm}
{\bf B}^{i_1i_2\ldots i_p}_{n,p}\left(L_{\bm\xi}\x,L_{\bm\xi}^2\x,...,L_{\bm\xi}^{n-p+1}\x\right)&=&\sum_{j_1=0}^n...\sum_{j_n=0}^n\frac{n!}{j_1!j_2! ... j_{n-p+1}!}\left\{\Biggl[\frac{L_{\bm\xi}\x}{1!}\Biggr]^{j_1}\Biggl[\frac{L^2_{\bm\xi}\x}{2!}\Biggr]^{j_2}...\Biggl[\frac{L_{\bm\xi}^{n-p+1}\x}{(n-p+1)!}\Biggr]^{j_n-p+1}\right\}_{(i_1i_2\ldots i_p)}
\ea
denotes the incomplete Bell polynomial \citep{Johnson_2002} of tensor rank $p$. The sum in Eq. \eqref{het65} is taken over all sequences $j_1, j_2, j_3, ..., j_{n-p+1}$ of non-negative integers such that the following two constraints are satisfied:
\bal{nbvrt6}
j_1+j_2+j_3+...+j_{n-p+1}=p\qquad\quad,\quad\qquad j_1+2j_2+3j_3+...+(n-p+1)j_{n-p+1}=n\;.
\ea
In particular, ${\bf B}_{0,0}=1$,  ${\bf B}_{n,0}= 0\;\;\forall n\ge1$, and ${\bf B}_{0,k}= 0\;\;\forall k\ge 1$. The symmetry of ${\bf B}^{i_1i_2\ldots i_p}_{n,p}$ is understood with respect to all free vector indices in its argument, for instance,
\bse
\bal{nytc5}
{\bf B}^{i_1i_2}_{5,2}\left(L_{\bm\xi}\x,L_{\bm\xi}^2\x,L^3_{\bm\xi}\x,L^4_{\bm\xi}\x\right)&=&
10L^2_{\bm\xi}x^{(i_1}L^3_{\bm\xi}x^{i_2)}+5L_{\bm\xi}x^{(i_1}L^4_{\bm\xi}x^{i_2)}\;,\\
{\bf B}^{i_1i_2i_3}_{6,3}\left(L_{\bm\xi}\x,L_{\bm\xi}^2\x,L^3_{\bm\xi}\x,L^4_{\bm\xi}\x\right)&=&
15L^2_{\bm\xi}x^{(i_1}L^2_{\bm\xi}x^{i_2}L^2_{\bm\xi}x^{i_3)}+60L_{\bm\xi}x^{(i_1}L^2_{\bm\xi}x^{i_2}L^2_{\bm\xi}x^{i_3)}+15L_{\bm\xi}x^{(i_1}L_{\bm\xi}x^{i_2}L^4_{\bm\xi}x^{i_3)}\;,
\ea
\ese
and so on.

Reordering the summation in Eq. \eqref{jk8ba}, we obtain: 
\bal{zvtf5a}
&&\sum_{n=0}^\infty\sum_{p=0}^n\frac{\tau^n}{n!}{\bf B}^{i_1i_2\ldots i_p}_{n,p}\left(L_{\bm\xi}\x,L_{\bm\xi}^2\x,...,L_{\bm\xi}^{n-p+1}\x\right)\pd_{i_1i_2\ldots i_p} V({\bm x})\\\nonumber
&&\hspace{6cm}=\,\sum_{p=0}^\infty\pd_{i_1i_2\ldots i_p} V({\bm x})\sum_{n=p}^\infty\frac{\tau^n}{n!}{\bf B}^{i_1i_2\ldots i_p}_{n,p}\left(L_{\bm\xi}\x,L_{\bm\xi}^2\x,...,L_{\bm\xi}^{n-p+1}\x\right)\;.
\ea
Using the generating function for Bell polynomials \citep{bellpol}, we find:
\bal{oin7ga}
\sum_{n=p}^\infty\frac{\tau^n}{n!}{\bf B}^{i_1i_2\ldots i_p}_{n,p}\left(L_{\bm\xi}\x,L_{\bm\xi}^2\x,...,L_{\bm\xi}^{n-p+1}\x\right)&=&\frac{1}{p!}\left(\sum_{n=1}^\infty\frac{\tau^n}{n!}L_{\bm\xi}^nx^{i_1}\right)\left(\sum_{n=1}^\infty\frac{\tau^n}{n!}L_{\bm\xi}^nx^{i_2}\right)\ldots\left(\sum_{n=1}^\infty\frac{\tau^n}{n!}L_{\bm\xi}^nx^{i_p}\right)\;.
\ea
Applying Eq. \eqref{f3}, this becomes:
\bal{jku5c}
\sum_{n=p}^\infty\frac{\tau^n}{n!}{\bf B}^{i_1i_2\ldots i_p}_{n,p}\left(L_{\bm\xi}\x,L_{\bm\xi}^2\x,...,L_{\bm\xi}^{n-p+1}\x\right)&=&
\frac{1}{p!}X^{i_1}_\tau X^{i_2}_\tau\ldots X^{i_p}_\tau\;.
\ea
Substituting this results into Eq. \eqref{zvtf5a}, we obtain:
\bal{bvtc5a}
V_\tau&=&\sum_{p=0}^\infty\frac{1}{p!}X^{i_1}_\tau X^{i_2}_\tau\ldots X^{i_p}_\tau\,\pd_{i_1i_2\ldots i_p} V({\bm x})=V\left({\bm x}+{\bm X}_\tau\right)\;,
\ea
which follows directly from the Taylor expansion. Comparing this with Eq. \eqref{vb6c4a}, we confirm the validity of Eq. \eqref{nbv5t}, thus completing the proof.

\section{Independent Proof of Pullback Transformation Formula of Gravitational Potential}\label{pulBB}
\stepcounter{equationschapter}
%\setcounter{equationschapter}{1}
\renewcommand{\theequation}{B.\arabic{equation}}

To demonstrate the correctness of Eq.~\eqref{xsa2}, we employ the radial gauge and spherical coordinates. In these coordinates, the gravitational potential ${\cal U}_\tau$ from Eq.~\eqref{vg6f} takes the form:
\bal{apb1}
{\cal U}_\tau&=&G\int\limits_{\V_\tau}\frac{\rho_\tau({\bm y}')}{|\x-{\bm y}'|}|{\bm y}'|^2dy'd^2\Omega\;,
\ea
where ${\bm y}':={\bm y}_\tau=\x'+\X'_\tau$ in accordance with Eq. \eqref{nb5c}. In the radial gauge, we have $\x'=r'{\bm n}$ and $\X'_\tau=X'_\tau{\bm n}$, with $X'_\tau=X'_\tau(\x')$. Using spherical coordinates, Eq.~\eqref{apb1} becomes: 
\bal{apb2}
{\cal U}_\tau&=&G\int\limits_{\cal V}\frac{\rho_\tau({\bm x}'+\X'_{\tau})}{|{\bm x}-\left({\bm x}'+\X'_{\tau}\right)|}\left|{\bm x}'+\X'_{\tau}\right|^2\left(1+\frac{\pd X'_\tau}{\pd r'}\right)dr'd^2\Omega\;.
\ea
We now expand the integrand in a Taylor series around the point $\x'$, yielding: 
\bal{apb3}
{\cal U}_\tau&=&G\int\limits_{\cal V}\sum_{n=0}^\infty\frac{{X'_\tau}^n}{n!}\frac{\pd^n}{\pd r'^n}\left[\frac{\rho_\tau(\x')r'^2}{|\x-\x'|}\right]dr'd^2\Omega+G\int\limits_{\cal V}\sum_{n=0}^\infty\frac{{X'_\tau}^n}{n!}\frac{\pd^n}{\pd r'^n}\left[\frac{\rho_\tau(\x')r'^2}{|\x-\x'|}\right]\frac{\pd X'_\tau}{\pd r'}dr'd^2\Omega\;.
\ea
Next, we isolate the $n=0$ term in the first sum on the right-hand side of Eq.~\eqref{apb3} and shift the summation index in the remaining terms via $n \to n+1$. This transforms the first integral into: 
\bal{apb4}
 \int\limits_{\cal V}\sum_{n=0}^\infty\frac{{X'_\tau}^n}{n!}\frac{\pd^n}{\pd r'^n}\left[\frac{\rho_\tau(\x')r'^2}{|\x-\x'|}\right]dr'd^2\Omega&=&\int\limits_{\V}\frac{\rho_\tau(\x')d^3x'}{|\x-\x'|}+
\int\limits_{\cal V}\sum_{n=0}^\infty\frac{{X'_\tau}^{n+1}}{(n+1)!}\frac{\pd^{n+1}}{\pd r'^{n+1}}\left[\frac{\rho_\tau(\x')r'^2}{|\x-\x'|}\right]dr'd^2\Omega \;. 
\ea
The second terms on the right-hand sides of Eqs.~\eqref{apb3} and \eqref{apb4} can be combined into a single expression involving a total derivative with respect to the radial coordinate. Thus, Eq.~\eqref{apb3} simplifies to: 
\bal{apb5}
{\cal U}_\tau&=&G\int\limits_{\V}\frac{\rho_\tau(\x')d^3x'}{|\x-\x'|}+G\int\limits_{\cal V}\sum_{n=0}^\infty\frac{\pd}{\pd r'}\left\{\frac{{X'_\tau}^{n+1}}{(n+1)!}\frac{\pd^{n}}{\pd r'^{n}}\left[\frac{\rho_\tau(\x')r'^2}{|\x-\x'|}\right]\right\}dr'd^2\Omega\;,
\ea
Finally, we observe that the second integral in Eq.~\eqref{apb5} can be evaluated as a surface integral over the boundary of the spherically symmetric unperturbed reference configuration of radius $r = a$. This yields:
\bal{apb6}
\U_\tau(\x)&=&G\int_{\cal V}\frac{\rho_\tau({\bm x}')d^3x'}{|{\bm x}-{\bm x}'|}+ G\oint_{{\mathbb S}^2}d^2\Omega({\bm n}_a) \sum_{n=0}^\infty\frac{X^{n+1}_\tau({\bm a})}{(n+1)!}\frac{\pd^n}{\pd a^n} \left[\frac{a^2\rho_\tau({\bm a})}{|{\bm x}-{\bm a}|}\right]\;. 
\ea 
This final expression for ${\cal U}_\tau$ matches exactly with Eq.~\eqref{xsa2}, thereby confirming their equivalence.

\section{Compatibility Conditions for the Master Equation of the Height Function}\label{antisym}
\stepcounter{equationschapter}
%\setcounter{equationschapter}{1}
\renewcommand{\theequation}{C.\arabic{equation}}

Due to the symmetry of the second partial derivatives the anti-symmetric part of equation \eqref{xc8} must vanish identically
\bal{ii1}
M^{-1}_{[ip}({\bm X})\pd_p\left[M^{-1}_{j]q}({\bm X})\pd_q U({\bm x})\right]=0\;.
\ea
In order to prove it, let us take the partial derivatives and account for the symmetry of the second partial derivative of the potential $U$ in the above equation. Then, it takes on a simpler form
\bal{ii2}
n^qM^{-1}_{[ip}({\bm X})\pd_pM^{-1}_{j]q}({\bm X})&=&0\qquad\qquad\Longrightarrow \qquad\qquad~M^{-1}_{[ip}\pd_pN_{j]}=0\;, 
\ea
where we have introduced a new vector
\bal{oo3}
N^i&:=&M^{-1}_{iq}n^q\;.
\ea
Equation \eqref{ii2} can be further transformed. We contract it with a direct matrix $M_{ai}$ and get
\bal{pp1}
M_{ai}M^{-1}_{[ip}\pd_pN_{j]}=\frac12\left(\pd_aN_j-M_{ai}M^{-1}_{jp}\pd_pN_{i}\right)&=&0\;.
\ea
Multiply it again with the direct matrix $M_{bj}$ and contract with respect to the index $j$. It yields
\bal{pp2}
M_{bj}\pd_aN_j-M_{aj}\pd_bN_j&=&0\;
\ea
Integrate this equation by parts and take into account that due to  definition, $A_{ab}=\pd_a X^b$, the following symmetry property is valid, $\pd_a M_{bj}=\pd_b M_{aj}$. Hence, equation \eqref{pp2} is equivalent to
\bal{pp3s}
\pd_a\left(M_{bj}N_j\right)-\pd_b\left(M_{aj}N_j\right)&=&\pd_{[a}n_{b]}=r^{-1}{\cal P}^{[ab]}\equiv 0\;.
\ea
It means that equation {\eqref{ii1} is satisfied for arbitrary vector field $X^i$ and that the anti-symmetric part of the right hand side of equation \eqref{xc8} vanishes identically, q.e.d.

\section{Calculating the Deformation Gradient Matrix}\label{appB}
\stepcounter{equationschapter}
%\setcounter{equationschapter}{1}
\renewcommand{\theequation}{D.\arabic{equation}}
This appendix examines the properties of the displacement gradient matrix $A_{ij}$ and its inverse $B_{ij}$ in the context of an ideal fluid. In such a case, the displacement vector of a level surface is aligned with the radial direction, and can be expressed as $X^i = n^i X(\bm{x})$, where $n^i$ is the radial unit vector and $X(\bm{x})$ is a scalar function.

By applying the Leibniz rule, the partial derivative of $X^i$ decomposes into the derivative of the unit vector $n^i$ and the derivative of the scalar function $X$. The derivative of $n^i$ is given by:
\bal{xc15}
\pd_i n^j&=&\frac{{\cal P}^{ij}}{r}\;,
\ea
where ${\cal P}^{ij} = \delta^{ij} - n^i n^j$ is the projection operator onto the plane orthogonal to $n^i$. The deformation gradient is then: 
\bal{xc16}
A_{pi}&=&\pd_pX^i={\cal P}^{ip}\frac{X}{r}+n^i\pd_pX={\cal P}^{pq}\left(\frac{X}{r}\delta^{iq}+n^i\pd_qX\right)+n^in^pn^q\pd_qX\;.
\ea
Differentiating again yields:
\bal{uyb6}
\pd_{pq}X^i&=&-\left(n^i{\cal P}^{pq}+n^q{\cal P}^{ip}+n^p{\cal P}^{iq}\right)\frac{X}{r^2}+\frac{1}{r}\left({\cal P}^{ip}\pd_qX+{\cal P}^{iq}\pd_pX\right)+n^i\pd_{pq}X\;.
\ea
Contracting indices in Eq. \eqref{uyb6} gives the Laplacian of the displacement vector:
\bal{pmex5}
\Delta X^i&=&n^i\left(\Delta X-\frac{2X}{r^2}\right)+\frac{2}{r}{\cal P}^{ip}\pd_pX\;.
\ea

From Eq. \eqref{xc16}, we also obtain the identity: 
\bal{ek1}
A_{pi}{\cal P}^{iq}&=&\left({\cal P}^{ip}\frac{X}{r}+n^i\pd_pX\right){\cal P}^{iq}={\cal P}^{pq}\frac{X}{r}\;.
\ea
This identity facilitates the computation of the projection of the inverse matrix $B_{ij}$. Using the definition of $B_{ij}$ and Eq. \eqref{ek1}, we find:
\bal{ek2}
B_{ij}{\cal P}^{jq}&=&\sum_{n=1}^\infty(-1)^nA_{ip_1}A_{p_1p_2}...A_{p_{n-1}j}{\cal P}^{jq}
=\sum_{n=1}^\infty\left(-\frac{X}{r}\right)^n{\cal P}^{iq}=\left[\left(1+\frac{X}{r}\right)^{-1}-1\right]{\cal P}^{iq}\;,
\ea
and thus
\bal{ek3}
M^{-1}_{ij}{\cal P}^{jq}&=&\left(1+\frac{X}{r}\right)^{-1}{\cal P}^{iq}\;.
\ea
In particular, the contraction yields:
\bal{ek4}
M^{-1}_{pq}{\cal P}^{pq}&=&2\left(1+\frac{X}{r}\right)^{-1}\;.
\ea 

Projecting the deformation gradient onto the unit vector $n^i$ gives:
\bal{ek5}
n^pA_{pi}&=&n^iX'\;,
\ea
where $X' = n^p \partial_p X$ is the radial derivative of $X$. Applying this in the definition of $B_{ij}$ leads to:
\bal{ek6}
n^jB_{ji}&=&\sum_{n=1}^\infty(-1)^nn^jA_{jp_1}A_{p_1p_2}...A_{p_{n-1}i}=n^i\sum_{n=1}^\infty(-X')^n=\frac{n^i}{1+X'}-n^i\;,
\ea
and therefore:
\bal{ek7}
n^jM^{-1}_{ji}&=&\frac{n^i}{1+X'}\;.
\ea
From this, we also obtain:
\bal{ek8}
M^{-1}_{pq}n^pn^q&=&\frac{1}{1+X'}\;,\\\nonumber
{\cal P}^{ip}M^{-1}_{pj}&=&M^{-1}_{ij}-n^in^pM^{-1}_{pj}=M^{-1}_{ij}-\frac{n^in^j}{1+X'}\;.
\ea 
Additional identities involving contractions of $A_{ij}$ with $n^i$ include:
\bal{ek9}
A_{pi}n^i&=&\pd_pX={\cal P}^{pq}\pd_q X+X'n^p\;,\\
A_{qp}A_{pi}n^i&=&A_{qp}\pd_pX={\cal P}^{qp}\left(X'+\frac{X}{r}\right)\pd_pX+X'^2n^q\;,\\
A_{bq}A_{qp}A_{pi}n^i&=&A_{bq}A_{qp}\pd_pX=A_{bq}{\cal P}^{qp}\frac{X}{r}\pd_pX+X'A_{bq}\pd_qX\nonumber\\\nonumber
&=&{\cal P}^{bp}\left(X'+\frac{X}{r}\right)\frac{X}{r}\pd_pX+X'^2\pd_bX\\&=&{\cal P}^{bp}\left(X'^2+X'\frac{X}{r}+\frac{X^2}{r^2}\right)\pd_pX+X'^3n^b\;,\\\nonumber
A_{ab}A_{bq}A_{qp}A_{pi}n^i&=&A_{ab}A_{bq}A_{qp}\pd_pX=A_{ab}A_{bq}{\cal P}^{qp}\frac{X}{r}\pd_pX+X'A_{ab}A_{bq}\pd_qX\\\nonumber
&=&A_{ab}{\cal P}^{bp}\left(X'+\frac{X}{r}\right)\frac{X}{r}\pd_pX+X'^2A_{ab}\pd_bX\\
&=&{\cal P}^{ap}\left(X'+\frac{X}{r}\right)\frac{X^2}{r^2}\pd_pX+X'^2\left({\cal P}^{ap}\frac{X}{r}\pd_pX+X'\pd_aX\right)\nonumber\\
&=&{\cal P}^{ap}\left(X'^3+X'^2\frac{X}{r}+X'\frac{X^2}{r^2}+\frac{X^3}{r^3}\right)\pd_pX+X'^4n^a\;.
\ea
Finally, the vector $N^i = M^{-1}_{ij} n^j$ is given by:
\bal{ek10}
N^i=M^{-1}_{ij}n^j&=&-\frac{{\cal P}^{ij}\pd_j X}{\ds~\Biggl(1+X'\Biggr)\left(1+\frac{X}{r}\right)}+\frac{n^i}{1+X'}\;.
\ea

\section{Wigner's Formalism to Decomposing Legendre Polynomial Products}\label{wignerdecomp}
\stepcounter{equationschapter}
%\setcounter{equationschapter}{1}
\renewcommand{\theequation}{E.\arabic{equation}}

The Wigner decomposition is a mathematical technique that employs Wigner matrices -- objects closely associated with angular momentum theory in quantum mechanics -- to decompose products of Legendre polynomials into linear combinations of Legendre polynomials of various degrees \citep{gelfand_1963}. This decomposition is grounded in the completeness of the Legendre polynomials, which form an orthogonal basis for the space of square-integrable functions on the interval $[-1, 1]$.

Since the product of a finite number of Legendre polynomials is itself a polynomial, it can be uniquely expanded in terms of this orthogonal basis. The Wigner decomposition provides a systematic way to perform this expansion, particularly useful in problems involving spherical symmetry, such as those encountered in gravitational and quantum field theories.

\subsection{Expressing the Wigner Matrix through Clebsch-Gordan Coefficients}
The Wigner matrix is defined as a square of the Clebsch-Gordan coefficients  
\bal{wig1}
T^{nml}\equiv \left(C^{nml}\right)^2\;,
\ea 
where $n, m, l\in \mathbb{N}=\{0,1,2,3,...\}$ are natural numbers and the Clebsch-Gordan coefficient 
\bal{k1e}
C^{nml}&=&(-1)^{n-m}\sqrt{2l+1}\left(\begin{array}{ccc}
  n & m & l \\
  0& 0 & 0 \\
\end{array}\right)\;,
\ea
is proportional to the Wigner $3j$ symbols,
\bal{k2s}
\left(\begin{array}{ccc}
  n & m & l \\
  0& 0 & 0 \\
\end{array}\right)&=&\frac{(-1)^ss!}{(s-n)!(s-m)!(s-l)!}\sqrt{\frac{(2s-2n)!(2s-2m)!(2s-2l)!}{(2s+1)!}}\,\delta_{\mathbb{A}}^n\delta_{\mathbb{B}}^m\delta_{\mathbb{C}}^l\delta^{2s}_{2\mathbb{N}}\;,\ea
with $2s\equiv n+m+l$, and $\delta^{n}_{\mathbb{A}}$, $\delta^{m}_{\mathbb{B}}$, and so on, are the indicator functions. The indicator functions are generalizations of the Kronecker symbol extended to a set of indices, for example,
\bal{knn}
\delta^{n}_{\mathbb{A}}&=&\biggl\{\begin{array}{ll}
  1&\;,\qquad \mbox{if}\; n\in \mathbb{A}\;,\\
  0&\;,\qquad \mbox{if}\; n\not\in \mathbb{A}\;,
\end{array} 
\ea
%\bal{k8n}
%\chi_{2\mathbb{N}}(2s)&=&\biggl\{\begin{array}{ll}
% 1&\;,\qquad \mbox{if}\; 2s=n+m+l\in 2\mathbb{N}\;,\\
%  0&\;,\qquad \mbox{if}\; 2s=n+m+l\not\in 2\mathbb{N}\;,
%\end{array}
%\ea
the set of even integers, $2\mathbb{N}=\{0,2,4,6,...\}$, and the sets $\mathbb{A}, \mathbb{B}, \mathbb{C}$ are defined by the rules
\bal{g5c3}
\mathbb{A}=\{|l-m|,...,l+m\}\qquad,\qquad\mathbb{B}=\{|l-n|,...,l+n\}\qquad,\qquad\mathbb{C}=\{|n-m|,...,n+m\}\;,
\ea
After computing the square of the $3j$ symbols we get the Wigner matrix $T^{nml}$ in explicit form, 
\bal{nxv5}
T^{nml}&=&\frac{2l+1}{2\pi }\frac{(s-n+1)_{-\frac12}(s-m+1)_{-\frac12}(s-l+1)_{-\frac12}}{(s+1)_{\frac12}}\,\delta_{\mathbb{A}}^n\delta_{\mathbb{B}}^m\delta_{\mathbb{C}}^l\delta^{2s}_{2\mathbb{N}}\;,
\ea
where $(a)_p=a(a+1)...(a+n-1)$ is the Pochhammer symbol -- cf. \eqref{s12}. 

We notice that the Wigner $3j$ symbols are fully symmetric with respect to the interchange of a pair of indices, while the Wigner matrix $T^{mnl}$ is symmetric only with respect to the first two indices, 
\bal{iu9}
T^{nml}=T^{(nm)l}\;.
\ea
Moreover, it satisfies the following two identities,
\bal{nb67v}
T^{0ml}=\delta^{ml}\;,\qquad\qquad T^{mn0}=\frac{\delta^{nm}}{2n+1}\;,
\ea
where $\delta^{nm}$ is the Kronecker symbol (the unit matrix). 

\subsection{Wigner's Decomposition of Legendre Polynomial Products}

The Wigner decomposition provides a systematic method for expressing the product of multiple Legendre polynomials as a linear combination of Legendre polynomials of various degrees. This is achieved through an iterative application of the binary product decomposition formula, which relies on Wigner $3j$-symbols or equivalent coefficients $T^{nml}$.

In the first step, the product of two Legendre polynomials is expanded as:
\bal{k1s}
P_{n}(\cos\theta)P_{m}(\cos\theta)&=&\sum_{l=|n-m|}^{n+m}T^{nml}P_{l}(\cos\theta)\;,
\ea
where the coefficients $T^{nml}$ encode the coupling between the angular momenta associated with the degrees $n$ and $m$.

To compute the product of three Legendre polynomials, the decomposition is applied iteratively:
\bal{k1sw}
P_{n_1}(\cos\theta)P_{n_2}(\cos\theta)P_{n_3}(\cos\theta)&=&\sum_{a_2=|n_2-a_1|}^{n_2+a_1}\sum_{a_3=|n_3-a_2|}^{n_3+a_2}T^{0n_1a_1}T^{a_1n_2a_2}T^{a_2n_3a_3}P_{a_3}(\cos\theta)\;,
\ea
where the intermediate indices $a_1$, $a_2$, and $a_3$ arise from successive pairwise decompositions.

More generally, the Wigner decomposition for the product of $k$ Legendre polynomials takes the form:
\bal{k1hv}
P_{n_1}(\cos\theta)\ldots P_{n_k}(\cos\theta)&=&\sum_{a_2=|n_2-n_1|}^{n_2+n_1}\ldots\sum_{a_{k}=|n_k-a_{k-1}|}^{n_k+a_{k-1}}T^{n_1n_2a_2}T^{a_2n_3a_3}\ldots T^{a_{k-1}n_ka_k}P_{a_k}(\cos\theta)\;.
\ea
This recursive structure is particularly useful in applications involving spherical harmonics, such as quantum mechanics, geophysics, and gravitational potential theory.


\subsection{Wigner's Decomposition of Legendre Polynomial Derivative Products}

To compute the product of derivatives of two Legendre polynomials, we begin by differentiating both sides of Eq. \eqref{k1s} twice with respect to $\cos\theta$, then multiply the result by $\sin^2\theta$. This procedure leverages the differential identity satisfied by Legendre polynomials:
\bal{c45d}
\frac{d}{d\cos\theta}\left[\sin^2\theta\frac{dP_n(\cos\theta)}{d\cos\theta}\right]&=&-n(n+1)P_n(\cos\theta)\;.
\ea
Applying this identity to the differentiated form of Eq. \eqref{k1s}, we obtain the following expression for the product of the derivatives:
\bal{xc20ss}
\sin^2\theta{P}_n'(\cos\theta)P_m'(\cos\theta)&=&\frac12\sum_{l=|n-m|}^{n+m}\left[n(n+1)+m(m+1)-l(l+1)\right]T^{nml}P_{l}(\cos\theta)\;.
\ea
This result expresses the product of the derivatives of two Legendre polynomials as a weighted sum of Legendre polynomials, with weights determined by the coupling coefficients $T^{nml}$ and the eigenvalues of the Legendre differential operator.

\subsection{Integrals Involving Products of Legendre Polynomials}

Wigner's decomposition provides a powerful tool for evaluating definite integrals involving products of Legendre polynomials. By expressing such products as linear combinations of Legendre polynomials, integration becomes straightforward due to their orthogonality properties. For instance, using Eq. \eqref{k1s} along with the orthogonality relation:
\bal{pm64}
\int_{0}^{\pi} P_{n}(\cos\theta)P_m(\cos\theta)\sin\theta d\theta&=&\frac{2}{2n+1}\delta_{nm} \;,
\ea
we can directly compute integrals of Legendre polynomial products.

For the triple product, applying Eq. \eqref{k1sw} yields:
\bal{pm87}
\int_{0}^{\pi} P_{n}(\cos\theta)P_{m}(\cos\theta)P_{l}(\cos\theta)\sin\theta d\theta&=&\frac{2}{2l+1}T^{nml}\;,
\ea
where the coefficient $T^{nml}$ is symmetric under permutations of its indices, as follows from its definition via Wigner $3j$-symbols (see Eq. \eqref{wig1}) and their inherent symmetries (cf. Eq. \eqref{k2s}).

This process generalizes to the product of $k$ Legendre polynomials:
\bal{yv65}\hspace{-0.8cm}
\int_{0}^{\pi} P_{n_1}(\cos\theta)...P_{n_k}(\cos\theta)\sin\theta d\theta&=&\frac{2}{2n_k+1}\sum_{a_2=|n_2-n_1|}^{n_2+n_1}\ldots\sum_{a_{k-2}=|n_{k-2}-a_{k-3}|}^{n_{k-2}+a_{k-3}}T^{n_1n_2a_2}T^{a_2n_3a_3}\ldots T^{a_{k-2}n_{k-1}n_k}\;,
\ea
Additionally, the integral of the product of derivatives of Legendre polynomials can be evaluated using Eq. \eqref{xc20ss}, resulting in:
\bal{o6gt}
\int_0^\pi\frac{dP_n(\cos\theta)}{d\theta}\frac{dP_m(\cos\theta)}{d\theta}\sin\theta d\theta&=&\frac{2n(n+1)}{2n+1}\delta^{mn}\;.
\ea 

\section{Differential Equation for Gravitational Field Perturbations in Polytropic Models}\label{secD}
\stepcounter{equationschapter}
%\setcounter{equationschapter}{1}
\renewcommand{\theequation}{F.\arabic{equation}}
\subsection{General Equation}
The polytropic equation of state is given by
\bal{k1}
p&=&{\mathsf K}_0\rho^{1+\frac{1}{n}}\;,
\ea
where ${\mathsf K}_0$ is a constant and $n$ is the polytropic index. This relation simplifies the computation of the coefficients $h_l$ in the power series expansion \eqref{s8} of the gravitational field perturbation $K$ in terms of the density perturbation $\varrho$.

We begin by evaluating the function ${\cal A}$ defined in Eq. \eqref{pnv34}: 
\bal{k2}
{\cal A}=\frac{1}{\rho}\frac{\pd p}{\pd\rho}=\left(1+\frac{1}{n}\right)p  \;.
\ea
Differentiating ${\cal A}$ yields: 
\bal{k3}
h_{l}&=&\pd_\rho^{{l}-1}A=K_0\frac{\ds n\;\Gamma\left(2+\frac{1}{n}\right)}{\ds\Gamma\left(1+\frac{1}{n}-{l}\right)}\rho^{-{l}+\frac{1}{n}}\;.
\ea 
Substituting these coefficients into Eq. \eqref{s8} allows the summation to be performed explicitly, resulting in an exact analytic relationship between the gravitational and density perturbations: 
\bal{k4}
K=(1+n){\mathsf K}_0\left[\left(\rho+\varrho\right)^{\frac{1}{n}}-\rho^{\frac{1}{n}}\right]\;.
\ea
Solving for $\varrho$ gives: 
\bal{k5}
\varrho&=&\left(\rho^{\frac{1}{n}}+\frac{K}{(1+n){\mathsf K}_0}\right)^n-\rho\;.
\ea
This expression can be used to derive two equivalent forms of the gravitational field perturbation equation.

{\bf First approach}: Expanding Eq. \eqref{k5} using the generalized binomial theorem \citep[Eq. 1.111]{gradryzh} yields:
\bal{k5a}
\varrho&=&\rho\sum_{{l}=1}^n\frac{b_{l}}{{l}!}\left(\frac{K}{{\mathsf K}_0}\right)^{l}\;,
\ea
with coefficients
\bal{k5b}
b_{l}&=&(-1)^{l}(1+n)^{-{l}}(-n)_{l}\rho^{-\frac{{l}}{n}}\;,
\ea
where $(-n)_{l}=(-n)(-n+1)...(-n+{l}-1)$ is the Pochhammer symbol. Substituting Eq. \eqref{k5b} into Eq. \eqref{41cs} leads to a non-linear field equation (c.f. Eq. \eqref{fe87}):  
\bal{k5c}
\Delta K+4\pi G\rho  \sum_{{l}=1}^n\frac{b_{l}}{{l}!}\left(\frac{K}{{\mathsf K}_0}\right)^{l}&=&0\;,
\ea
which can be solved iteratively.

{\bf Second approach}: Define a new function
\bal{k5d}
F&:=&\rho^{\frac{1}{n}}+\frac{K}{(1+n){\mathsf K}_0}\;,
\ea
and add the Laplacian of $\rho^{1/n}$ to both sides of Eq. \eqref{41cs}:
\bal{k5e}
\Delta\rho^{\frac{1}{n}}&=&\frac{\rho^{\frac{1}{n}-1}}{n}\left[\rho''+\frac{2\rho'}{r}+\left(\frac{1}{n}-1\right)\frac{\rho'^2}{\rho}\right]\;.
\ea
This transforms the equation into: 
\bal{k5f}
\Delta F+\kappa^2 F^n&=&\frac{\rho^{\frac{1}{n}-1}}{n}\left[\rho''+\frac{2\rho'}{r}+\left(\frac{1}{n}-1\right)\frac{\rho'^2}{\rho}\right]+\kappa^2\rho\;,
\ea
where 
\bal{k5g}
\kappa&=&\sqrt{\frac{4\pi G}{(1+n){\mathsf K}_0}}\;.
\ea
The right-hand side of Eq. \eqref{k5f} vanishes due to the Lane-Emden equation, yielding the final form:
\bal{unf1}
\Delta F+\kappa^2 F^n&=&0\;.
\ea
This non-linear PDE (except for $n = 1$) is equivalent to Eq. \eqref{k5c} but expressed in a more compact form. It generally requires numerical methods for solution.

\subsection{Special Cases of Polytropes}
Three particular cases of polytropes are of special interest and warrant separate treatment.
\subsubsection{Polytrope of index $n=0$}

For $n = 0$, the density $\rho$ is constant, implying $\varrho = 0$. The gravitational field perturbation satisfies the Laplace equation: 
\bal{bbb21}
\Delta K=0\;,
\ea 
valid both inside and outside the fluid body.

\subsubsection{Polytrope of index $n=1$}

For $n = 1$, Eq. \eqref{k5a} simplifies to: 
\bal{k7}
\varrho=\frac{K}{2{\mathsf K}_0}\;,
\ea
leading to the Helmholtz equation:
\bal{k7a}
\Delta K+\frac{2\pi G}{{\mathsf K}_0}K&=&0\;.
\ea
This equation admits an exact analytic solution, which can be used to determine the shape function $f = X/r$ via Eq. \eqref{oper23}, bypassing the need to solve the non-linear equation \eqref{cre5a}. Further details are provided in Section \ref{subD2}.

\subsubsection{Polytrope of index $n=\infty$} 
The case $n = \infty$ corresponds to an isothermal sphere, relevant for modeling systems like globular clusters \citep{horedt_2004book}. Here, Eq. \eqref{k5a} becomes: 
\bal{k8}
\varrho=\left(e^{K/{\mathsf K}_0}-1\right)\rho\;
\ea
leading to the field equation:
\bal{k8a}
\Delta K+4\pi G\rho e^{K/{\mathsf K}_0}&=&4\pi G\rho\;.
\ea
The density profile $\rho(r)$ is obtained numerically from the Lane-Emden equation. Since $\rho$ does not vanish at any finite radius, the solution extends to infinity, implying infinite mass. In practice, the model is truncated at a finite radius for astrophysical applications \citep{horedt_2004book}.

