\section{Solution with one tipping}\label{appA}
\subsection{Proof of Proposition \ref{prop1}}\label{appA1}
We derive the optimal strategies for regions within coalition $S$ by maximizing their collective net emissions-associated benefit: 
\begin{equation}
\max_{\{q_{i}\}_{i\in S}}\ \sum_{i\in S}\int_{0}^{+\infty}e^{-rt}\left(\left(1+\tau\right)\left(\alpha_{i}q_{i}-\frac{1}{2}\beta_{i}{q_{i}}^{2}+\epsilon_{i}\right)-\frac{1}{2}\rho_{i}T^{2}-\eta_{i}T-L_{i}\right)dt
\end{equation}

Where temperature evolution follows: 
\begin{equation}
\frac{dT\left(t\right)}{dt}=\lambda\left(\sum_{i\in S}q_{i}+\sum_{j\notin S}q_{j}\right)
\end{equation}

With derived Hamilton-Jacobi-Bellman (HJB) equation through standard dynamic programming method, the value function satisfies: 
\begin{equation}
rV^{1}\left(T\right) = \max_{\{q_{i}\}_{i\in S}}\left[
\begin{split}
&\sum_{i\in S}\left(\left(1+\tau\right)\left(\alpha_{i}q_i-\frac{1}{2}\beta_{i}{q_i}^{2}+\epsilon_{i}\right)-\frac{1}{2}\rho_{i}T^{2}-\eta_{i}T-L_{i}\right)  \\
 & \ \ \ \ \ \ \ \ \ +\lambda\frac{dV^1\left(T\right)}{dT}\left(\sum_{i\in S}q_i+\sum_{j\notin S}q_j\right)
\end{split}
\right]
\end{equation}

\noindent where $\frac{dV^{1}\left(T\right)}{dT}$ is the first-order derivative of the value function $V^{1}(T)$ with respect to the state variable $T$. 

The first-order conditions yield optimal emissions for coalition members: 
\begin{equation}
q_{i}^{1*}\left(T\right)=\frac{\left(1+\tau\right)\alpha_{i}+\lambda \frac{dV^{1}\left(T\right)}{dT}}{\left(1+\tau\right)\beta_{i}}
\end{equation}

The derivation of the Markov strategy of region $j$ outside the coalition is similar.


By substituting the optimal strategies for member and non-member regions into the Hamilton-Jacobi-Bellman (HJB) equations, we obtain:  
\begin{equation}
\begin{split}
rV^{1}\left(T\right) = & \sum_{i\in S}\left[\frac{\left(1+\tau\right)^{2}{\alpha_{i}}^{2}-\lambda^{2}\left(\frac{dV^{1}\left(T\right)}{dT}\right)^{2}}{2\left(1+\tau\right)\beta_{i}}+\left(1+\tau\right)\epsilon_{i}-\frac{1}{2}\rho_{i}T^{2}-\eta_{i}T-L_{i}\right]  \\
& +\left(\lambda A+\lambda^{2}\frac{d{U^1}\left(T\right)}{dT}\right)\frac{dV^{1}\left(T\right)}{dT}
 \end{split}
\end{equation}

for coalition members, and for each non-member region $j\notin S$:
\begin{equation}
\begin{split}
rW_{j}^{1}\left(T\right) = & \frac{{\alpha_{j}}^{2}-\lambda^{2}\left(\frac{dW_{j}^{1}\left(T\right)}{dT}\right)^{2}}{2\beta_{j}}+\epsilon_{j}-\frac{1}{2}\rho_{j}T^{2}-\eta_{j}T-L_{j}  \\
  & +\left(\lambda A+\lambda^{2}\frac{d{U^1}\left(T\right)}{dT}\right)\frac{dW_{j}^{1}\left(T\right)}{dT}
 \end{split}
\end{equation}
\noindent where $A\equiv\sum_{i \in S}\frac{\alpha_{i}}{\beta_{i}}+\sum_{j \notin S}\frac{\alpha_{j}}{\beta_{j}}$, $U^1\left(T\right)=\sum_{i\in S}\frac{V^{1}\left(T\right)}{\left(1+\tau\right)\beta_{i}}+\sum_{j\notin S}\frac{W^{1}_{j}\left(T\right)}{\beta_{j}}$, $\frac{d{U^1}\left(T\right)}{dT}$ is the first derivative of $U^1\left(T\right)$ with respect to $T$.

Given the linear-quadratic structure of the game, we postulate quadratic forms for the value functions: 
\begin{equation}
\begin{cases}
V^{1}\left(T\right)=v_{0}+v_{1}T+\frac{1}{2}v_{2}T^{2}\\
W^{1}_{j}\left(T\right)=w_{j,0}+w_{j,1}T+\frac{1}{2}w_{j,2}T^{2}
\end{cases}
\end{equation}
\noindent where $v_{0}$, $v_{1}$, $v_{2}$, $w_{j,0}$, $w_{j,1}$, and $w_{j,2}$ are undetermined coefficients\footnote{To simplify our discussion, these undetermined coefficients will be used repeatedly in the following individual sections}.

Substituting these into the HJB equations yields three coupled systems for the coefficients: 

For coalition members:
\begin{equation}
\begin{cases}
\frac{1}{2}rv_{2}=\sum_{i\in S}\left(\frac{\lambda^{2}{v_{2}}^{2}}{2\left(1+\tau\right)\beta_{i}}-\frac{1}{2}\rho_{i}\right)+v_{2}\lambda^{2}\sum_{j\notin S}\frac{w_{j,2}}{\beta_{j}}\\
rv_{1}=\sum_{i\in S}\left(\frac{\lambda^{2}v_{1}v_{2}}{\left(1+\tau\right)\beta_{i}}-\eta_{i}\right)+\lambda Av_{2}+\lambda^{2}\sum_{j\notin S}\frac{v_{1}w_{j,2}+v_{2}w_{j,1}}{\beta_{j}}\\
rv_{0}=\sum_{i\in S}\left(\frac{\left(1+\tau\right)^{2}{\alpha_{i}}^{2}+\lambda^{2}{v_{1}}^{2}}{2\left(1+\tau\right)\beta_{i}}+\left(1+\tau\right)\epsilon_{i}-L_{i}\right)+v_{1}\left(\lambda A+\lambda^{2}\sum_{j\notin S}\frac{w_{j,1}}{\beta_{j}}\right)
\end{cases}\label{eq:linear_quad_coalition}
\end{equation}

For non-members ($\forall j\notin S$):
\begin{equation}
\begin{cases}
\frac{1}{2}rw_{j,2}=-\frac{\lambda^{2}{w_{j,2}}^{2}}{2\beta_{j}}-\frac{1}{2}\rho_{j}+w_{j,2}\lambda^{2}\left(\sum_{i\in S}\frac{v_{2}}{\left(1+\tau\right)\beta_{i}}+\sum_{j\notin S}\frac{w_{j,2}}{\beta_{j}}\right)\\
\begin{split}
rw_{j,1}=& -\frac{\lambda^{2}w_{j,1}w_{j,2}}{\beta_{j}}-\eta_{j}+\lambda Aw_{j,2}\\
&+\lambda^{2}\left(\sum_{i\in S}\frac{w_{j,1}v_{2}+w_{j,2}v_{1}}{\left(1+\tau\right)\beta_{i}}+w_{j,1}\sum_{j\notin S}\frac{w_{j,2}}{\beta_{j}}+w_{j,2}\sum_{j\notin S}\frac{w_{j,1}}{\beta_{j}}\right)
\end{split}\\
rw_{j,0}=\frac{{\alpha_{j}}^{2}-\lambda^{2}{w_{j,1}}^{2}}{2\beta_{j}}+\epsilon_{j}-L_{j}+w_{j,1}\left(\lambda A+\lambda^{2}\left(\sum_{i\in S}\frac{v_{1}}{\left(1+\tau\right)\beta_{i}}+\sum_{j\notin S}\frac{w_{j,1}}{\beta_{j}}\right)\right)
\end{cases}\label{eq:linear_quad_noncoalition}
\end{equation}

