\subsection{Proof of Proposition \ref{Prop2}}\label{appA3}
Consider member regions maximizing their expected net emissions-associated benefit collectively: 
\begin{equation}
\max_{\{q_{i}\}_{i \in S}} E\sum_{i\in S}\left[
\begin{split}
& \int_{0}^{t_{1}}e^{-rt}\left(\left(1+\tau\right)\left(\alpha_{i}q_{i}-\frac{1}{2}\beta_{i}{q_{i}}^{2}+\epsilon_{i}\right)-\frac{1}{2}\rho_{i}T^{2}-\eta_{i}T\right)dt  \\
& +\int_{t_{1}}^{+\infty}e^{-rt}\left(
\begin{split}
&\left(1+\tau\right)\left(\alpha_{i}q_{i}-\frac{1}{2}\beta_{i}{q_{i}}^{2}+\epsilon_{i}\right)\\
& -\frac{1}{2}\rho_{i}T^{2}-\eta_{i}T-L_{i}\\
\end{split}
\right)dt\\
\end{split}
\right]   
\end{equation}

The state variable evolves as $\frac{dT}{dt} = \lambda\left(\sum_{i\in S}q_i + \sum_{j\notin S}q_j\right)$, $T(0) = T_0$. And with hazard rate $H(T) = \chi \max(0, T-\underline{T})$, The value function ${V^{2}}\left(T\right)$ satisfies: 
\begin{equation}
rV^{2}\left(T\right)= \max_{\{q_i\}_{i \in S}}\left[
\begin{split}
&\sum_{i\in S}\left(\left(1+\tau\right)\left(\alpha_{i}q_{i}-\frac{1}{2}\beta_{i}{q_{i}}^{2}+\epsilon_{i}\right)-\frac{1}{2}\rho_{i}T^{2}-\eta_{i}T\right)  \\
 & +\lambda\frac{dV^{2}\left(T\right)}{dT}\left(\sum_{i\in S}q_{i}+\sum_{j\notin S}q_{j}\right)  \\
 &+H\left(T\right)\left(V^{1}\left(T\right)-V^{2}\left(T\right)\right)
 \end{split}
 \right]
\end{equation}

The first-order condition yields:
\begin{equation}
q_{i}^{2*}\left(T\right)=\frac{\left(1+\tau\right)\alpha_{i}+\lambda \frac{dV^{2}\left(T\right)}{dT}}{\left(1+\tau\right)\beta_{i}}
\end{equation}

The derivation of the Markov strategy of region $j$ outside the coalition is similar.

From the definition of $H(T)$, when $T<\underline{T}$, there is $H(T)=0$. The HJB equations in state 1 will be identical to HJB equations in state 2 in form. Thus, the value functions $V^2$ and $W^2_j$ can be conform to a quadratic form. 

For temperature levels $T\ge \underline{T}$, substituting the optimal emission strategies $q_{i}^{2*}$ and $q_{j}^{2*}$ into the HJB equations, we can obtain:
\begin{equation}
\begin{aligned}
    (r+\chi T)V^{2}\left(T\right) = 
&\sum_{i\in S} \left( \frac{(1+\tau)\alpha_i^2}{2\beta_i}+(1+\tau)\epsilon_i-\frac{1}{2}\rho_iT^2-\eta T\right)  \\
& +\frac{\lambda^2}{2(1+\tau)\beta_{I}}(\frac{d V^2(T)}{d T})^2+\lambda A\frac{dV^2(T)}{dT}\\
 & +\frac{\lambda^2}{\beta_{J}}\frac{dV^2(T)}{dT}\frac{dW_j^2(T)}{dT}+\chi TV^{1}(T)
\end{aligned}
\end{equation}
\begin{equation}
\begin{aligned}
    (r+\chi T)W^{2}_j\left(T\right) = 
& \frac{\alpha_i^2}{2\beta_i}-\frac{\lambda^2}{2\beta_j}(\frac{dW_j^2(T)}{dT})^2+\epsilon_j-\frac{1}{2}\rho_jT^2-\eta_jT \\
& +\frac{\lambda^2}{\beta_{J}}(\frac{dW_j^2(T)}{dT})^2+\lambda A\frac{dW_j^2(T)}{dT}_T \\
 & +\frac{\lambda^2}{(1+\tau)\beta_{I}}\frac{dV^2(T)}{dT}\frac{dW_j^2(T)}{dT}+\chi TW_j^{1}(T)
\end{aligned}
\end{equation}
where $\frac{1}{\beta_{J}} = \sum_{j\notin S}\frac{1}{\beta_j}$.

It is easy to verify that when the value functions $V^2$ and $W^2_j$ are quadratic polynomials or cubic polynomials, the highest terms on both sides of these two equations are the same. This means that the value functions $V^2$ and $W^2_j$ can be quadratic polynomials or cubic polynomials. 

\subsection{Numerical solution with Chebyshev polynomial approximation}\label{appA4}
We employ Chebyshev polynomial approximation on $\left[\underline{T},\overline{T}\right]$:

\begin{equation}
\hat{V}\left(T\right)=\sum_{k=0}^{K}a_{k}\mathcal{T_{\mathit{k}}}\left(z\left(T\right)\right)
\end{equation}

\noindent where $z\left(T\right )=\frac {2T-\underline{T}-\overline{T}}{\overline{T}-\underline{T}}$ maps to $\left[-1,1\right]$, $a_{k}$ is the Chebyshev coefficients, $\mathcal{T_{\mathit{k}}}\left(z\left(T\right)\right)$ are Chebyshev polynomials adapted to $\left[\underline{T},\overline{T}\right]$ for $k=0,1,2,...$ with degree-$K$. 

We choose $K+1$ Chebyshev nodes, $T_{d}=\left(z_{d}+1\right)\left(\overline{T}-\underline{T}\right)/2+\underline{T}$, with $z_{d}=-\cos\left(\frac{\left(2d-1\right)\pi}{\left(2\left(K+1 \right)\right)}\right)$ for $d=1,...,K+1$. The Lagrange values $\left(T_{d},v_{d}\right)$: $d=1,...,K+1$ are given (where $v_{d}=V(T_{d})$), and the coefficients $a_{k}$ can be computed: 
\begin{equation}
\begin{cases}
a_{0}=\frac{1}{K+1}\sum_{d=1}^{K+1}v_{d}  \\
a_{k}=\frac{2}{K+1}\sum_{d=1}^{K+1}v_{d}\mathcal{T_{\mathit{k}}}\left(z\left(T_{d}\right)\right),\ \ \ k=1,...,K
\end{cases}
\end{equation}

See \citet{judd1998numerical} and \citet{cai2013shape} for more details. We then assume:  
\begin{equation}
\begin{cases}
V^{2}\left(T\right)=\sum_{k=0}^{K}a_{k}\phi_{k}\left(T \right)\\
W^{2}_{j}\left(T\right)=\sum_{k=0}^{K}b_{k,j}\phi_{k}\left(T \right)
\end{cases}
\end{equation}
for $T\in[\underline{T},\overline{T}]$, where $\phi_{k}(T)$ are Chebyshev basis functions with coefficients $a_k$ and $b_{k,j}$ for $V^{2}\left(T\right)$ and $W^{2}_{j}\left(T\right)$, respectively. We solve 
\begin{equation}
\begin{split}
0=&-\left[r+H\left(T_{d}\right)\right]\sum_{k=0}^{K}a_{k}\phi_{k}(T_{d})  \\
&+\sum_{i\in S}\left[\frac{\left(1+\tau\right)^{2}{\alpha_{i}}^{2}-\lambda^{2}\left(\sum_{k=0}^{K}a_{k}{\phi_{k}}_{T_{d}}(T_{d})\right)^{2}}{2\left(1+\tau\right)\beta_{i}}+\left(1+\tau\right)\epsilon_{i}-\frac{1}{2}\rho_{i}{T_{d}}^{2}-\eta_{i}T_{d}\right]  \\
&+\left(\lambda A+\lambda^{2}\frac{d{U^2}\left(T_{d}\right)}{dT_{d}}\right)\sum_{k=0}^{K}a_{k}{\phi_{k}}_{T_{d}}(T_{d})\\
&+H\left(T_{d}\right)\left(v_{0}+v_{1}T_{d}+\frac{1}{2}v_{2}{T_{d}}^{2}\right)\\
\end{split}
\end{equation}
\begin{equation}
\begin{split}
0=&-\left[r+H\left(T_{d}\right)\right]\sum_{k=0}^{K}b_{k,j}\phi_{k}(T_{d})  \\
&+\frac{{\alpha_{j}}^{2}-\lambda^{2}\left(\sum_{k=0}^{K}b_{k,j}{\phi_{k}}_{T_{d}}(T_{d})\right)^{2}}{2\beta_{j}}+\epsilon_{j}-\frac{1}{2}\rho_{j}{T_{d}}^{2}-\eta_{j}T_{d}  \\
&+\left(\lambda A+\lambda^{2}\frac{d{U^2}\left(T_{d}\right)}{dT_{d}}\right)\sum_{k=0}^{K}b_{k,j}{\phi_{k}}_{T_{d}}(T_{d})+H\left(T_{d}\right)\left(w_{j,0}+w_{j,1}T_{d}+\frac{1}{2}w_{j,2}{T_{d}}^{2}\right)\\
\end{split}
\end{equation}

For each non-member region ($j\notin S$) and Chebyshev node ($d=1,...,K+1$). We use the analytical solutions $V^{2}\left(\underline{T}\right)$ and $W^{2}_{j}\left(\underline{T}\right)$ at $T=\underline{T}$ as boundary conditions, where ${\phi_{k}}_{T_{d}}$ denotes the first derivative of $\phi_{k}(T_{d})$ at $T_d$. The resulting system comprises $(m+1)(1+n-m)$ unknown coefficients ($a_{k}$ and $b_{k,j}$) and $\left(K+1\right)\left(1+n-m\right)$ equations, which we solve numerically using MATLAB's fsolve. Regarding the selection of nodes for the solution, we compared both $K=4$ and $K=6$ options and found virtually no difference in computational efficiency between the two. Therefore, we opted for $K=4$. For details, please refer to the Supplement S1.

