\section{Solution with two tippings}\label{appB}
\subsection{Model solution after two tippings occurred}\label{appB1}
After both tipping events have occurred (State 1), coalition members and non-members solve their respective optimization problems:
\begin{equation}
\max_{q_{i}}\ \sum_{i\in S}\int_{0}^{\infty}e^{-rt}\left(
\begin{split}
&\left(1+\tau\right)\left(\alpha_{i}q_{i}(t)-\frac{1}{2}\beta_{i}q_{i}(t)^{2}+\epsilon_{i}\right)\\
&-\frac{1}{2}\rho_{i}T(t)^{2}-\eta_{i}T(t)-L^1_{i}-L^2_{i}    
\end{split}
\right)dt
\end{equation}
\begin{equation}
\max_{q_{j}} \int_{0}^{\infty}e^{-rt}\left(
\begin{split}
&\alpha_{j}q_{j}(t)-\frac{1}{2}\beta_{j}q_{j}(t)^{2}+\epsilon_{j}\\
&-\frac{1}{2}\rho_{j}T(t)^{2}-\eta_{j}T(t)-L^1_{j}-L^2_{j}\\
\end{split}
\right)dt
\end{equation}
for each $j\notin S$.

The HJB equations yield optimal strategies:
\begin{equation}
\begin{cases}
q_{i}^{1*}\left(T\right)=\frac{\left(1+\tau\right)\alpha_{i}+\lambda \frac{dV^{1}\left(T\right)}{dT}}{\left(1+\tau\right)\beta_{i}}\\
q_{j}^{1*}\left(T\right)=\frac{\alpha_{j}+\lambda \frac{dW^{1}_{j}\left(T\right)}{dT}}{\beta_{j}}
\end{cases}
\end{equation}

