}{r}$}
& {\footnotesize{}$w_{j,0}=\frac{
\begin{aligned}
& \frac{{\alpha_{j}}^{2}-\lambda^{2}\left(w_{j,1}\right)^{2}}{2\beta_{j}}+\epsilon_{j}-L^1_{j}-L^2_{j} \\
& \quad +\left(\lambda^{2}u_{1}+\lambda A\right)w_{j,1}\\
\end{aligned}
}{r}$}\\
\hline
\end{tabular}
\label{A2}
\end{table}

\noindent where $u_{1}=\frac{\left(\sum_{i\in S}\frac{1}{\left(1+\tau\right)\beta_{i}}\right)\left[\frac{\lambda Av_{2}-\sum_{i\in S}\eta_{i}}{\left(\sum_{i\in S}\frac{\lambda^{2}v_{2}}{\left(1+\tau\right)\beta_{i}}\right)-\left(\lambda^{2}u_{2}-r\right)}\right]+\left\{ \sum_{j\notin S}\frac{\lambda Aw_{j,2}-\eta_{j}}{\beta_{j}\left[\frac{\lambda^{2}w_{j,2}}{\beta_{j}}-\left(\lambda^{2}u_{2}-r\right)\right]}\right\} }{1-\left[\frac{\sum_{i\in S}\frac{\lambda^{2}v_{2}}{\left(1+\tau\right)\beta_{i}}}{\left(\sum_{i\in S}\frac{\lambda^{2}v_{2}}{\left(1+\tau\right)\beta_{i}}\right)-\left(\lambda^{2}u_{2}-r\right)}+\sum_{j\notin S}\frac{\frac{\lambda^{2}w_{j,2}}{\beta_{j}}}{\frac{\lambda^{2}w_{j,2}}{\beta_{j}}-\left(\lambda^{2}u_{2}-r\right)}\right]}$,
and $u_{2}$ is the solution to equation(for each region $j\notin S$, which is not in the coalition):
\begin{equation*}
\footnotesize{}
0=(n - m)u_2\lambda^2 \left[
\begin{split}
&\frac{1}{2}r(n - m + 1)-\sqrt{\left( \lambda^2 u_2 - \frac{1}{2}r \right)^2 - \left( \sum_{i \in S} \frac{\lambda^2}{(1+\tau)\beta_i} \right) \left( \sum_{i \in S} \rho_i \right)}\\
&-\sum_{j\notin S} \sqrt{\left( \lambda^2 u_2 - \frac{1}{2}r \right)^2 - \frac{\lambda^2}{\beta_j} \rho_j}\\
\end{split}
\right]
\end{equation*}

This solution extends the single-tipping case while incorporating tipping damages $L^1$ and $L^2$. 

\subsection{Model solution after first tipping occurred but second is not}\label{appB2}
For State 2 (first tipping occurred, second pending), regions solve: 
\begin{equation}
\max_{q_{i}} E\sum_{i\in S}\left[
\begin{split}
&\int_{0}^{t_{2}}e^{-rt}\left(
\begin{split}
&\left(1+\tau\right)\left(\alpha_{i}q_{i}(t)-\frac{1}{2}\beta_{i}q_{i}(t)^{2}+\epsilon_{i}\right)\\
&-\frac{1}{2}\rho_{i}T(t)^{2}-\eta_{i}T(t)-L^1_{i}\\
\end{split}
\right)dt\\
& +\int_{t_{2}}^{\infty}e^{-rt}\left(
\begin{split}
&\left(1+\tau\right)\left(\alpha_{i}q_{i}(t)-\frac{1}{2}\beta_{i}q_{i}(t)^{2}+\epsilon_{i}\right)\\
&-\frac{1}{2}\rho_{i}T(t)^{2}-\eta_{i}T(t)-L^1_{i}-L^2_{i}
\end{split}
\right)dt\\
\end{split}
\right]
\end{equation}
\begin{equation}
\max_{q_{j}} E\left[
\begin{split}
&\int_{0}^{t_{2}}e^{-rt}\left(
\begin{split}
&\alpha_{j}q_{j}(t)-\frac{1}{2}\beta_{j}q_{j}(t)^{2}+\epsilon_{j}\\
&-\frac{1}{2}\rho_{j}T(t)^{2}-\eta_{j}T(t)-L^1_{j}\\
 \end{split}
\right)dt \\
&+\int_{t_{2}}^{\infty}e^{-rt}\left(
\begin{split}
&\alpha_{j}q_{j}(t)-\frac{1}{2}\beta_{j}q_{j}(t)^{2}+\epsilon_{j}\\
&-\frac{1}{2}\rho_{j}T(t)^{2}-\eta_{j}T(t)-L^1_{j}-L^2_{j}\\
 \end{split}
\right)dt
 \end{split}
 \right]
\end{equation}
for each $j\not\in S$.

The value functions satisfy:
\begin{equation}
rV^{2}\left(T\right)= \max_{q_i}\left[
\begin{split}
&\sum_{i\in S}\left(
\begin{split}
&\left(1+\tau\right)\left(\alpha_{i}q_{i}-\frac{1}{2}\beta_{i}{q_{i}}^{2}+\epsilon_{i}\right)\\
&-\frac{1}{2}\rho_{i}T^{2}-\eta_{i}T-L^1_{i}\\
\end{split}
\right)\\
&+\frac{dV^{2}\left(T\right)}{dT}\lambda\left(\sum_{i\in S}q_{i}+\sum_{j\notin S}q_{j}\right) \\
& +H_{2}\left(T\right)\left(V^{1}\left(T\right)-V^{2}\left(T\right)\right)\\
\end{split}
\right]
\end{equation}
\begin{equation}
rW^{2}_{j}\left(T\right)=\max_{q_j}\left[
\begin{split}
&\left(\alpha_{j}q_{j}-\frac{1}{2}\beta_{j}{q_{j}}^{2}+\epsilon_{j}-\frac{1}{2}\rho_{j}T^{2}-\eta_{j}T-L^1_{i}\right)\\
 &+\frac{dW^{2}_{j}\left(T\right)}{dT} \lambda\left(\sum_{i\in S}q_{i}+\sum_{j\notin S}q_{j}\right)\\
 &+H_{2}\left(T\right)\left(W^{1}_{j}\left(T\right)-W^{2}_{j}\left(T\right)\right)\\
 \end{split}
 \right]
\end{equation}

\noindent where $\frac{dV^2\left(T\right)}{dT}$ and $\frac{dW^{2}_{j}\left(T\right)}{dT}$ are the first-order derivatives of value functions $V^{2}\left(T\right)$ and $W^{2}_{j}\left(T\right)$ on $T$, respectively. 

Yielding optimal strategies:
\begin{equation}
\begin{cases}
q_{i}^{2*}\left(T\right)=\frac{\left(1+\tau\right)\alpha_{i}+\lambda \frac{dV^{2}\left(T\right)}{dT}}{\left(1+\tau\right)\beta_{i}}\\
q_{j}^{2*}\left(T\right)=\frac{\alpha_{j}+\lambda \frac{dW^{2}_{j}\left(T\right)}{dT}}{\beta_{j}}
\end{cases}
\end{equation}

Using Chebyshev approximation on $T\in[\underline{T},\overline{T}]$: 
\begin{equation}
\begin{cases}
V^{2}\left(T\right)=\sum_{k=0}^{K}a_{k}\phi_{k}\left(T \right)\\
W^{2}_{j}\left(T\right)=\sum_{k=0}^{K}b_{k,j}\phi_{k}\left(T \right)
\end{cases}
\end{equation}

We solve at Chebyshev nodes  $T_{d}$: 
\begin{equation}
\begin{split}
0=&-\left[r+H_{2}\left(T_{d}\right)\right]\sum_{k=0}^{K}a_{k}\phi_{k}(T_{d})\\
&+\sum_{i\in S}\left[
\begin{split}
&\frac{\left(1+\tau\right)^{2}{\alpha_{i}}^{2}-\lambda^{2}\left(\sum_{k=0}^{K}a_{k}{\phi_{k}}_{T_{d}}(T_{d})\right)^{2}}{2\left(1+\tau\right)\beta_{i}}\\
&+\left(1+\tau\right)\epsilon_{i}-\frac{1}{2}\rho_{i}{T_{d}}^{2}-\eta_{i}T_{d}-L^1_{i}
\end{split}
\right]\\
&+\left(\lambda A+\lambda^{2}\frac{d{U^2}\left(T_{d}\right)}{dT_{d}}\right)\sum_{k=0}^{K}a_{k}{\phi_{k}}_{T_{d}}(T_{d})+H_{2}\left(T_{d}\right)\left(v_{0}+v_{1}T_{d}+\frac{1}{2}v_{2}{T_{d}}^{2}\right)\\
\end{split}
\end{equation}
\begin{equation}
\begin{split}
0=&-\left[r+H_{2}\left(T_{d}\right)\right]\sum_{k=0}^{K}b_{k,j}\phi_{k}(T_{d}) \\
&+\frac{{\alpha_{j}}^{2}-\lambda^{2}\left(\sum_{k=0}^{K}b_{k,j}{\phi_{k}}_{T_{d}}(T_{d})\right)^{2}}{2\beta_{j}}+\epsilon_{j}-\frac{1}{2}\rho_{j}{T_{d}}^{2}-\eta_{j}T_{d}-L^1_{j}\\
&+\left(\lambda A+\lambda^{2}\frac{d{U^2}\left(T_{d}\right)}{dT_{d}}\right)\sum_{k=0}^{K}b_{k,j}{\phi_{k}}_{T_{d}}(T_{d})\\
&+H_{2}\left(T_{d}\right)\left(w_{j,0}+w_{j,1}T_{d}+\frac{1}{2}w_{j,2}{T_{d}}^{2}\right)\\
\end{split}
\end{equation}
\noindent where $d=1,...,K+1$. Boundary conditions use analytical solutions from $T=\underline{T}$. 

\subsection{Model solution before first tipping occurred}\label{appB3}
In State 3 (no tipping events occurred), regions solve sequential optimization problems accounting for potential future tipping events:
\begin{equation}
\max_{q_i} E\sum_{i\in S}\left[
\begin{split}
&\int_{0}^{t_{1}}e^{-rt}\left(
\begin{split}
&\left(1+\tau\right)\left(\alpha_{i}q_{i}(t)-\frac{1}{2}\beta_{i}q_{i}(t)^{2}+\epsilon_{i}\right)\\
&-\frac{1}{2}\rho_{i}T(t)^{2}-\eta_{i}T(t)\\
\end{split}
\right)dt\\
 &+\int_{t_{1}}^{t_{2}}e^{-rt}\left(
 \begin{split}
&\left(1+\tau\right)\left(\alpha_{i}q_{i}(t)-\frac{1}{2}\beta_{i}q_{i}(t)^{2}+\epsilon_{i}\right)\\
&-\frac{1}{2}\rho_{i}T(t)^{2}-\eta_{i}T(t)-L^1_{i}\\
\end{split}
\right)dt\\
 &+ \int_{t_{2}}^{\infty}e^{-rt}\left(
 \begin{split}
 &\left(1+\tau\right)\left(\alpha_{i}q_{i}(t)-\frac{1}{2}\beta_{i}q_{i}(t)^{2}+\epsilon_{i}\right)\\
 &-\frac{1}{2}\rho_{i}T(t)^{2}-\eta_{i}T(t)-L^1_{i}-L^2_{i}\\
 \end{split}
 \right)dt\\
 \end{split}
 \right]
\end{equation}
\begin{equation}
\max_{q_j} E\left[
\begin{split}
&\int_{0}^{t_{1}}e^{-rt}\left(
\begin{split}
&\alpha_{j}q_{j}(t)-\frac{1}{2}\beta_{j}q_{j}(t)^{2}+\epsilon_{j}\\
&-\frac{1}{2}\rho_{j}T(t)^{2}-\eta_{j}T(t)\\
\end{split}
\right)dt\\
 &+ \int_{t_{1}}^{t_{2}}e^{-rt}\left(
 \begin{split}
 &\alpha_{j}q_{j}(t)-\frac{1}{2}\beta_{j}q_{j}(t)^{2}+\epsilon_{j}\\
 &-\frac{1}{2}\rho_{j}T(t)^{2}-\eta_{j}T(t)-L^1_{j}\\
 \end{split}
 \right)dt \\
 &+\int_{t_{2}}^{\infty}e^{-rt}\left(
 \begin{split}
 &\alpha_{j}q_{j}(t)-\frac{1}{2}\beta_{j}q_{j}(t)^{2}+\epsilon_{j}\\
 &-\frac{1}{2}\rho_{j}T(t)^{2}-\eta_{j}T(t)-L^1_{j}-L^2_{j}\\
 \end{split}
 \right)dt\\
 \end{split}
 \right]
\end{equation}
for each $j\not\in S$.

The value functions satisfy: 
\begin{equation}
rV^{3}\left(T\right)= \max_{q_i}\left[
\begin{split}
& \sum_{i\in S}\left(\left(1+\tau\right)\left(\alpha_{i}q_{i}-\frac{1}{2}\beta_{i}{q_{i}}^{2}+\epsilon_{i}\right)-\frac{1}{2}\rho_{i}T^{2}-\eta_{i}T\right)\\
 &+\frac{d{V^3}\left(T\right)}{dT} \lambda\left(\sum_{i\in S}q_{i}+\sum_{j\notin S}q_{j}\right)\\
 &+H_{1}\left(T\right)\left(V^{2}\left(T\right)-V^{3}(T)\right)\\
 \end{split}
 \right]
\end{equation}
\begin{equation}
rW^3_{j}\left(T\right)= \max_{q_j}\left[
\begin{split}
&\left(\alpha_{j}q_{j}-\frac{1}{2}\beta_{j}{q_{j}}^{2}+\epsilon_{j}-\frac{1}{2}\rho_{j}T^{2}-\eta_{j}T\right)\\
 &+\frac{dW^3_{j}\left(T\right)}{dT} \lambda\left(\sum_{i\in S}q_{i}+\sum_{j\notin S}q_{j}\right)\\
 &+ H_{1}\left(T\right)\left(W^{2}_{j}\left(T\right)-W^3_{j}\left(T\right)\right)\\
 \end{split}
 \right]
\end{equation}

Taking the optimal emission strategies of member regions and non-member regions into HJB functions, and using Chebyshev approximation, We solve:

\begin{equation}
\begin{split}
0=&-\left[r+H_{1}\left(T_{d}\right)\right]\sum_{k=0}^{K}a_{k}\phi_{k}(T_{d})\\
&+\sum_{i\in S}\left[\frac{\left(1+\tau\right)^{2}{\alpha_{i}}^{2}-\lambda^{2}\left(\sum_{k=0}^{K}a_{k}{\phi_{k}}_{T_{d}}(T_{d})\right)^{2}}{2\left(1+\tau\right)\beta_{i}}+\left(1+\tau\right)\epsilon_{i}-\frac{1}{2}\rho_{i}{T_{d}}^{2}-\eta_{i}T_{d}\right]\\
&+\left(\lambda A+\lambda^{2}\frac{d{U^3}\left(T_{d}\right)}{dT_{d}}\right)\sum_{k=0}^{K}a_{k}{\phi_{k}}_{T_{d}}(T_{d})+H_{1}\left(T_{d}\right)V^{2}\left(T\right) 
\end{split}
\end{equation}
\begin{equation}
\begin{split}
0=&-\left[r+H_{1}\left(T_{d}\right)\right]\sum_{k=0}^{K}b_{k,j}\phi_{k}(T_{d}) \\
&+\frac{{\alpha_{j}}^{2}-\lambda^{2}\left(\sum_{k=0}^{K}b_{k,j}{\phi_{k}}_{T_{d}}(T_{d})\right)^{2}}{2\beta_{j}}+\epsilon_{j}-\frac{1}{2}\rho_{j}{T_{d}}^{2}-\eta_{j}T_{d}\\
&+\left(\lambda A+\lambda^{2}\frac{d{U^3}\left(T_{d}\right)}{dT_{d}}\right)\sum_{k=0}^{K}b_{k,j}{\phi_{k}}_{T_{d}}(T_{d})+H_{1}\left(T_{d}\right)W^{2}_{j}\left(T\right) 
\end{split}
\end{equation}
\noindent where $\frac{dU^3\left(T\right)}{dT}$ is the derivative of $U^3\left(T\right)$ with respect to $T$, and $U^3\left(T\right)=\sum_{i\in S}\frac{V^{3}\left(T\right)}{\left(1+\tau\right)\beta_{i}}+\sum_{j\notin S}\frac{W^{3}_{j}\left(T\right)}{\beta_{j}}$. $d=1,...,K+1$, $V^{3}(\underline{T})$ and $W^3_{j}(\underline{T})$ are given by the analytical solution for $T=\underline{T}$. $V^{2}\left(T\right)$ and $W^{2}_{j}\left(T\right)$ can be obtained from the numerical solutions in Supplement \ref{appB2}. 

\section{Comparison of allocation mechanisms}\label{appE}
We evaluate two payment transfer mechanisms to sustain cooperation: \textit{Shapley Allocation}, benefits are distributed based on each member’s marginal contribution to the coalition; \textit{$\gamma$-core allocation}, benefits are allocated according to the proportion of benefits each member would retain if they leave the coalition. While both mechanisms are logically justified, our numerical simulations demonstrate that the $\gamma$-core allocation is more effective in fostering cooperation and maximizing collective benefits. As a result, the main text focuses on the $\gamma$-core allocation for comparative analysis.

Under single tipping event case, both Shapley and $\gamma$-core allocations sustain a grand coalition (full cooperation) over time and across rising temperatures (Figure \ref{Fa7}).And the coalition maintains sufficiently large benefits for all members, incentivizing continued participation under both mechanisms (Figure \ref{Fa8}). Under two tipping events case, the $\gamma$-core allocation supports a larger stable coalition compared to the Shapley allocation (Figure \ref{Fa9}). And the $\gamma$-core allocation consistently yields greater collective benefits than the Shapley allocation, reinforcing its advantage in complex scenarios (Figure \ref{Fa10}). 
