    \label{fig:tangent}
\end{figure}


\subsection{An optimization objective via variational formulations of elliptic problems}\label{sec:ContT:Elliptic}
The uniqueness of the pair $(\rho, \nabla s^*)$ established in the previous section means it is sufficient to look for $s$ so that $\nabla s$ satisfies the continuity equation. 
At least formally, we can then plug $\nabla s$ into the strong form \eqref{eq:prelim:continuity} of the continuity equation and obtain the problem
\begin{equation}\label{eq:Cont:EllipticProblem}
-\nabla \cdot (\rho(t, x) \nabla s(t, x)) = \partial_t \rho(t, x)\,.
\end{equation}
If $\partial_t \rho(t) / \rho(t)$ is in $L^{2}(\rho(t))$, the Poincar\'e inequality of Assumption~\ref{assumption:prelim:poincare} holds, and coercivity holds in a $\rho$-weighted sense, then \eqref{eq:Cont:EllipticProblem} is an elliptic PDE. Notice that in the standard, unweighted sense, one would require $\rho(t, x) \geq \underline{\rho} > 0$ to be strictly positive over $[0, T] \times \mathcal{X}$ to obtain coercivity. 
Notice that $\partial_t \rho$ serves as a source term because the unknown in \eqref{eq:Cont:EllipticProblem} is $s$ and not $\rho$. Thus, under the assumptions above that $\rho$ is sufficiently regular, we can interpret finding a vector field $u = \nabla s$ as solving a coupled system of PDE problems \eqref{eq:Cont:EllipticProblem}. Critically, the PDE problems are coupled via the right-hand side $\partial_t \rho$ rather than the unknown $s$. The perspective via PDE problems allows us to leverage the well-known variational formulation of \eqref{eq:Cont:EllipticProblem} to obtain 
\begin{equation}\label{eq:Cont:EllipticVarForm}
\min_s \int_0^T \int_{\mathcal{X}} \frac{1}{2}|\nabla s(t, x)|^2 \rho(t, x) - s(t, x) \partial_t \rho(t, x)\mathrm dx\,\mathrm dt\,,
\end{equation}
which provides an optimization problem for finding an $s$ given $\rho$ and $\partial_t \rho$  \citep{benamou_computational_2000}. 


\subsection{Re-writing the time derivative}\label{sec:ContT:ReWriting}

The objective of the variational problem given in \eqref{eq:Cont:EllipticVarForm} depends on the density $\rho$ and its derivative $\partial_t \rho$. 
We will later consider the setting where we have access to samples of the time marginals $\rho(t)$, which can be interpreted as being able to integrate against the density $\rho(t, \cdot)$ over time $t$.  
However, the objective in \eqref{eq:Cont:EllipticVarForm} also depends on the time derivative $\partial_t \rho$ of $\rho$, which is challenging to estimate if one can only integrate against the time marginals $\rho(t)$. 

It is helpful to rewrite the source term $t \mapsto \int_{\mathcal{X}} s(t, x)\partial_t \rho(t, x)\mathrm dx$ in \eqref{eq:Cont:EllipticVarForm} as an expectation with respect to $\rho$. To do so, note that
\begin{multline}\label{eq:Cont:ddtaureform}
\frac{\rd}{\rd t} \mathbb{E}_{x \sim \rho(t)}\left[s(t, x)\right] = \frac{\rd}{\rd \tau} \mathbb{E}_{x \sim \rho(\tau)}\left[s(t, x)\right] \bigg |_{\tau = t} + \frac{\rd}{\rd \tau} \mathbb{E}_{x \sim \rho(t)}\left[s(\tau, x)\right] \bigg |_{\tau = t} \\
= \int_{\mathcal{X}} s(t, x)\partial_t \rho(t, x) \, \mathrm dx + \int_{\mathcal{X}} \rho(t, x) \partial_t s(t, x) \, \mathrm dx
\end{multline}
holds, where $\tau$ is an artificial time. Contained in the identity \eqref{eq:Cont:ddtaureform} is the statement that 
\begin{align}\label{eq:Cont:PartialDiff}
\int_{\mathcal{X}} s(t, x)\partial_t \rho(t, x) \, \mathrm dx = \frac{\rd}{\rd \tau} \mathbb{E}_{x \sim \rho(\tau)}\left[s(t, x)\right] \bigg |_{\tau = t}\,,\qquad t \in (0, T)\,,
\end{align}
which is an expression in which the time marginals $\rho(t)$ enter only via expectations. Using \eqref{eq:Cont:PartialDiff}, we obtain an objective function that only consists of expectations with respect to $\rho(t)$
\begin{equation}\label{eq:Cont:ContLossddtau}
    L(s) = \int_0^T \left( \mathbb E_{x \sim \rho(t)} \left[ \frac{1}{2} |\nabla s(t, x)|^2 \right] - \frac{\rd}{\rd \tau} \mathbb E_{x \sim \rho(\tau)} \left[ s(t, x) \right]\bigg |_{\tau = t} \right) \rd t,
\end{equation}
and which has the same minimizers as the variational formulation \eqref{eq:Cont:EllipticVarForm} over $s$. 
Still, the objective function \eqref{eq:Cont:ContLossddtau} is not a loss function yet because it cannot be directly estimated from samples of the time marginals $\rho(t)$ because of the derivative in the artificial time $\tau$.





\section{Discrete inverse continuity equation (DICE)}
\label{sec:DICE}
In this section, we consider the problem of recovering potential field $s$ that is consistent with samples of the time marginals $\rho(t, \cdot)$ given only at discrete time points $t \in \{t_k\}_{k=0}^K.$ It is a working assumption of our methodology that these points are spaced closely in time, relative to the natural
timescale of the density evolution. \Cref{sec:Prelim:ProblemFormulation} provides a more detailed discussion of the problem setup. In \Cref{sec:DICE:Loss}, we introduce the DICE loss function that has the
potential as a minimizer. The loss is defined through a time-discrete weak form of the continuity equation corresponding to the discrete time points at which time marginals are available. In \Cref{sec:DICE:Properties}, we show that the corresponding optimization problem is well posed and admits a unique minimizer.

\subsection{Learning vector fields of  marginals at discrete time points}
\label{sec:Prelim:ProblemFormulation}
\paragraph{Learning vector fields} We now assume that we have access to $\rho(t_j)$
only at discrete time points $t \in \{t_k\}_{k=0}^K$, where 
access means that we can integrate against $\rho(t_j)$; in particular we
do not assume that we can evaluate the corresponding density function. This requirement is in preparation for later sections when we have available only samples of the time marginals; see Section~\ref{sec:DICESamples}.
We wish to find a vector field $u$ that minimizes the kinetic energy $J(u)$ given in \eqref{eq:Prelim:KinEnergy} and also minimizes a loss function defined by asking
that the continuity equation is compatible with the marginals $\{\rho(t_j)\}_{j = 0}^K$ at $t \in \{t_k\}_{k=0}^K$. This optimization problem is
simplified by recalling that finding a minimal kinetic energy field requires $u = \nabla s$, leading to an optimization problem over $s.$

\paragraph{Piece-wise geodesic interpolants}
One approach to our problems is to connect $\rho(t_{j-1})$ to $\rho(t_{j})$ on
$(t_{j-1} - t_{j})$ with Wasserstein geodesics, for $j = 1, \dots, K$. This requires solving fully nonlinear optimal transport problems between all marginals, which is computationally expensive. Furthermore, the approach does not exploit the
fact that $\Delta t_{\text{max}} := \max_{j = 1, \dots, K} |t_j - t_{j - 1}|$ is
assumed small. Instead, our approach can be interpreted as finding the tangent vector field $\nabla s(t_j, \cdot)$ at the discrete time points $t_j$ for $j = 0, \dots, K$ and approximating the curve $t \mapsto \rho(t)$ via the tangent vector fields $\nabla s(t_0, \cdot), \dots, \nabla s(t_K, \cdot)$ at the discrete time points $t_0, \dots, t_K$; see Figure~\ref{fig:tangent}. 
We will show that the linearization underlying the construction of $\nabla s$ will introduce an error that is also of the order of the maximal time-step size (see \Cref{prop:DICE:BoundForAllT}) and thus our approach does not lead to a worse scaling of the error with the maximal time-step size than connecting Wasserstein geodesics, while solving the simpler linear problem on the tangent space as opposed to the full optimal transport problem. 




\subsection{The DICE loss}\label{sec:DICE:Loss}
\paragraph{Function spaces} 
We introduce notation essential for definition of the DICE loss.  We start by defining Hilbert spaces $L^2(\rho(t_j))$
through the $\rho(t_j)-$weighted $L^2$ inner products
    \begin{align}
        \langle s^{1}_j, s^{2}_j\rangle_{L^2(\rho(t_j))} = \int_{\mathcal X} s^{1}_j(x) s^{2}_j(x) \rho(t_j, x) \, \rd x\,, \quad j = 0, \dots, K.
    \end{align}
    We also define the Hilbert spaces
    \begin{align}
        \mathcal S_j = \left\{ s \in L^2(\rho(t_j)): \nabla s \in L^2(\rho(t_j))\right\},\qquad j = 0, \dots, K\,.
    \end{align}
    The spaces $\mathcal{S}_j$ are closely related to Sobolev spaces $H^1(\mathrm dx)$, except that the integration defining $\mathcal{S}_j$ is with respect to the measure $\rho(t_j)$ instead of the Lebesgue measure used to define
    the $H^1(\mathrm dx)$ subspace of $L^2(\mathrm dx)$. Indeed, given upper
    and lower (positive) a.e. bounds on $\rho(t_j, x)$ all the Hilbert spaces 
    $\mathcal S_j$ are equivalent to $H^1(\mathrm dx).$ 
    Likewise the spaces $L^2(\rho(t_j))$ are equivalent to $L^2(\mathrm dx)$.
    The normalized counterpart of $\mathcal{S}_j$ is
    \begin{align}
    \mathcal S_j^0 = \{s \in \mathcal{S}_j \, : \, \mathbb{E}_{x \sim \rho(t_j)}[s(x)] = 0\}\,.
    \end{align}

    The Cartesian product $L^2(\rho(t_0)) \times \dots \times  L^2(\rho(t_K))$ is a Hilbert space, because $L^2(\rho(t_j))$ for $j = 0, \dots, K$ are Hilbert spaces. Likewise, because $\mathcal S_j$ for $j = 0, \dots, K$ are Hilbert spaces, the Cartesian product $\mathcal S_0 \times \dots \times \mathcal S_K$ is a Hilbert space. 
Denote the vector of functions $\bar{s}(x) = [s_0(x), \dots, s_K(x)]$ and define the 
inner product on $L^2(\rho(t_0)) \times \dots \times L^2(\rho(t_K))$ by
    \begin{align}
        \langle \bar{s}^1, \bar{s}^2 \rangle_{L^2(\rho(t_0)\cdots\rho(t_K))} = \sum_{j=0}^K  \int_{\mathcal X} \frac{t_{j+1} - t_{j-1}}{2} s^1_j(x) s^2_j(x) \, \rho(t_j, x) \, \rd x,
    \end{align}
    for $\bar{s}^1, \bar{s}^2 \in L^2(\rho(t_0)) \times \dots \times  L^2(\rho(t_K)).$

Furthermore, we note that 
    \begin{align}
        \Vert \bar{s} \Vert_{{L^2(\rho(t_0)\cdots\rho(t_K))}}^2 = \langle \bar{s}, \bar{s} \rangle_{L^2(\rho(t_0)\cdots\rho(t_K))} = \sum_{j=0}^K \frac{t_{j+1} - t_{j-1}}{2} \| s_j(x) \|^2_{L^2(\rho(t_j))}\,,
    \end{align}
defines a norm provided that all $t_0, \dots, t_K$ are distinct; this follows from\
the fact that then
    \begin{align}
        \Vert \bar{s}^1 - \bar{s}^2 \Vert_{L^2(\rho(t_0) \cdots \rho(t_K))}^2 = 0 \Leftrightarrow s_j^1 = s_j^2 \; \rho(t_j)\text{-almost-everywhere}\,, \qquad j = 0, \dots, K\,.
    \end{align}
We also introduce the notation
    \begin{align}
        \Vert \mathrm{D}\bar{s} \Vert_{{L^2(\rho(t_0)\cdots\rho(t_K))}}^2 &:= \sum_{j=0}^K  \int_{\mathcal X} \frac{t_{j+1} - t_{j-1}}{2} | \nabla s_j(x)|^2 \, \rho(t_j, x) \, \rd x,
    \end{align}
    and note that
\begin{align}
    \| \bar s \|_{\mathcal{S}_0 \times \cdots \times \mathcal{S}_K} := \Vert \bar{s} \Vert_{{L^2(\rho(t_0)\cdots\rho(t_K))}}^2+\Vert \mathrm{D}\bar{s} \Vert_{{L^2(\rho(t_0)\cdots\rho(t_K))}}^2
\end{align}
defines a norm, and by polarization an inner product, on $\mathcal S_0 \times \dots \times \mathcal S_K.$




We introduce the set of functions that intersect the Cartesian product $\mathcal{S}_0 \times \cdots \times \mathcal{S}_K$ with extensions over the time interval $[0, T]$ as \begin{align}\label{eq:DICE:SpaceS}
        \mathcal S = \{ s : [0,T] \times \mathcal X  \to \bR: s(t_j, \cdot) \in \mathcal S_j \text{ for } j = 0, \dots, K \}\,,
    \end{align}
    as well as the normalized counterpart $\mathcal{S}^0$ that intersects with $\mathcal{S}_0^0 \times \cdots \times \mathcal{S}_K^0$. Note that we do not make any statement about the behavior of functions $s \in \mathcal S$ outside of the set of time points $\{t_j\}_{j=0}^K$ for now. 

\paragraph{Weak form of continuity equation in discrete time} Let us now turn to the discrete-weak form of the continuity equation. Recall from the paragraph
on ``Learning vector fields'' that we seek a vector field defined as the gradient of potential field  $\hat{s} \in \mathcal{S}$ that satisfies the weak form of the continuity equation \eqref{eq:Prelim:ContWeakForm} at the $K + 1$ discrete time points $t_0 < t_1 < \dots < t_K$ at which the marginals $\{\rho(t_j)\}_{j = 0}^K$ are available. We use finite differences to approximate the time derivative on the left-hand side of \eqref{eq:Prelim:ContWeakForm} and use the convention that $t_{-1} = t_0$ and $t_{K+1} = t_K$, leading to the following equations that we would like to choose 
$\hat{s}$ to satisfy:
\begin{align}
    \label{eq:DICE:DiscreteCompat}
    \frac{\bE_{x\sim\rho(t_{j+1})}[\varphi(x)] - \bE_{x\sim\rho(t_{j-1})}[\varphi(x)]}{t_{j+1} - t_{j-1}} = \bE_{x\sim\rho(t_j)}[\nabla\hat{s}(t_j, x) \cdot \nabla \varphi(x)]\,,\quad j = 0, \dots, K\,,
\end{align}
for all test functions $\varphi \in \mathcal{S}_k, k \in \{j-1, j, j+1\}$. Recall that $\nabla\hat{s}(t_j, \cdot)$ has minimal kinetic energy \eqref{eq:Prelim:KinEnergy} and so it has to be in $L^2(\rho(t_j))$, i.e. in $\hat{s}(t_j, \cdot) \in \mathcal{S}_j$ at all times.  We call $\nabla\hat{s}$ discretely compatible with $\{\rho(t_j)\}_{j=0}^K$  if \eqref{eq:DICE:DiscreteCompat} holds for $j = 0, \dots, K$.
Other time-discretization schemes can be used as well.

\paragraph{The DICE loss} We now show that the system of equations \eqref{eq:DICE:DiscreteCompat} is a system of Euler-Lagrange equations of the following quadratic functional $\LD: \mathcal{S} \to \mathbb{R}$, which we call the DICE loss.

    \begin{proposition}[DICE loss]
    \label{prop:DICEEulerLagrangeEq}
    A function $\hat{s}^* \in \mathcal S$ that minimizes 
    \begin{multline}
        \label{eq:Loss_DICE}
        \LD(s) = \sum_{j=1}^{K} \left( \frac{t_j - t_{j-1}}{2} \left( \bE_{x\sim\rho(t_{j})} \left[ \frac{1}{2} |\nabla s(t_j, x)|^2 \right] + \bE_{x\sim\rho(t_{j-1})} \left[ \frac{1}{2} |\nabla s(t_{j - 1}, x)|^2 \right] \right)\right. \\
        \left.- \frac{1}{2} \left( \bE_{x\sim\rho(t_{j})} \left[ s(t_j, x) + s(t_{j-1}, x) \right] - \bE_{x\sim\rho(t_{j-1})} \left[ s(t_j, x) + s(t_{j-1}, x) \right] \right) \right)
    \end{multline}
    solves the system of equations given in \eqref{eq:DICE:DiscreteCompat}.
    \end{proposition}
The proof can be found in \Cref{proof:DICEEulerLagrangeEq}. For a minimizer $\hat{s}^*$ of $\mathrm{L}_{\mathrm{DICE}}$, the behavior outside of the time points 
$\{t_j\}_{j=0}^K \subset [0,T]$ is not specified. 
A linear interpolant of the form
\begin{align}
        \label{eq:DICEPieceWiseLinearInTime}
        \hat{s}^*(t, x) \bigg |_{t \in [t_j, t_{j+1}]} = \frac{t_{j+1} - t}{t_{j+1} - t_j} \hat{s}^*(t_j, x) + \frac{t - t_j}{t_{j+1} - t_j} \hat{s}^*(t_{j+1}, x)\,, \quad j = 0, \dots, K-1\,,
\end{align}
is one way to extend the function to the entire time interval of $[0, T]$. Any other curve $t \mapsto \hat{s}(x,t)$ that intersects all $\{ \hat{s}^*(t_j, x) \}_{j=0}^K$ is also discretely compatible with $\{\rho(t_j)\}_{j = 0}^K$ and therefore a minimizer of $\mathrm{L}_{\mathrm{DICE}}$ over $\mathcal{S}$. The value of $\LD$ is independent of the specific form of the curve between the discrete time points.



\subsection{Properties of the DICE loss}\label{sec:DICE:Properties}
Recall that we are optimizing for a gradient field $\hat{s}$ which is defined only up to a constant because $\nabla \hat{s} = \nabla (\hat{s} + f)$ holds for functions $f: [0, T] \to \mathbb{R}$ that are constant over the spatial domain $\mathcal{X}$ but can vary over the time interval $[0, T]$. The following proposition shows that the DICE loss preserves this property in the sense that it is invariant under addition of functions that are constant over the spatial domain $\mathcal{X}$. 
    \begin{proposition}[Invariance of DICE loss to constants]\label{prop:InvariantF} The loss $L_{\text{DICE}}$ is invariant under additions of functions that are constant over the spatial domain: given a gradient field $s$ and
    any function $f: [0,T] \rightarrow \bR$ we have
    \begin{align}
         \mathrm{L}_{\mathrm{DICE}}(s + f) = \mathrm{L}_{\mathrm{DICE}}(s)\,.\end{align}
    \end{proposition}

\begin{proof}
    By direct substitution, we obtain the identity 
    \begin{align}
        \mathrm{L}_{\mathrm{DICE}}(s + f) &= \mathrm{L}_{\mathrm{DICE}}(s) - \frac{1}{2} \sum_{j=1}^K \left( \bE_{x\sim\rho(t_{j})} - \bE_{x\sim\rho(t_{j-1})} \right) \left[ f(t_{j}) + f(t_{j-1}) \right] \\
        &= \mathrm{L}_{\mathrm{DICE}}(s) - \frac{1}{2} \sum_{j=1}^K \underbrace{\left( f(t_{j}) + f(t_{j-1}) - f(t_{j}) + f(t_{j-1}) \right)}_{= \, 0}.
    \end{align}
    \end{proof}

The invariance to constants is a key property of the DICE loss, which is important for stable training; see Section~\ref{sec:CmpAM}. 
We now show existence of a minimizer $\hat{s}^*$ of the DICE loss $\LD$ in $\mathcal{S}$ and discuss in what sense it is unique, building on the Poincar\'e inequality of Assumption~\ref{assumption:prelim:poincare}. The invariance to constants of the DICE loss shown in \Cref{prop:InvariantF} plays a key role in the following proposition because it allows us to ignore constants and then application of the Poincar\'e inequality to show boundedness over $\mathcal{S}$ rather than only over functions with zero mean. We formulate the following proposition, which will lead to a corollary about the uniqueness of DICE minimizers. A proof can be found in \Cref{appdx:ExistenceProof}. 
    \begin{proposition}[The DICE loss admits a unique minimizer]
\label{prop:DICESolutionDiscreteInTime} 
Let \Cref{assumption:prelim:poincare} hold. Let further the density functions satisfy
    \begin{align}
    \label{eq:DICErho_log_deriv_is_L2}
        \frac{\rho(t_{j+1}, \cdot) - \rho(t_{j-1}, \cdot)}{\rho(t_{j}, \cdot)} \in L^2(\rho(t_j, \cdot))\,,
    \end{align}
    for $j = 0, \dots, K$. Consider now the loss $\LD^K: \mathcal{S}_0 \times \dots \mathcal{S}_K \to \mathbb{R}$ defined for $\bar{\hs} = [\hs_0, \dots, \hs_K] \in \mathcal{S}_0 \times \dots \times \mathcal{S}_K$ as
    \begin{multline}
    \label{eq:DICEDiscreteDecoupled}
        \LD^K(\bar{\hs}) = \sum_{j=1}^{K} \bigg( \frac{t_j - t_{j-1}}{2} \left( \bE_{x\sim\rho(t_{j})} \left[ \frac{1}{2} |\nabla \hs_j(x)|^2 \right] + \bE_{x\sim\rho(t_{j-1})} \left[ \frac{1}{2} |\nabla \hs_{j-1}(x)|^2 \right] \right) \\
        - \frac{1}{2} \left( \bE_{x\sim\rho(t_{j})} \left[ \hs_j(x) + \hs_{j-1}(x) \right] - \bE_{x\sim\rho(t_{j-1})} \left[ \hs_j(x) + \hs_{j-1}(x) \right] \right) \bigg)\,.
    \end{multline}
    Then, the problem
    \begin{align}
        \min_{\bar{\hs} \in \mathcal{S}_0 \times \dots \times \mathcal{S}_K} \LD^K(\bar{\hs})
    \end{align}
    admits a solution $\bar{\hs}^* = [\hs_0^*, \dots, \hs_K^*] \in \mathcal{S}_0 \times \dots \times \mathcal{S}_K$. In particular, there is a solution $\bar{\hs}_0^*$ in $\mathcal{S}_0^0 \times \dots \times \mathcal{S}_K^0$ that is unique with respect to  $\|\cdot\|_{\mathcal{S}_0 \times \cdots \times \mathcal{S}_K}$. 
    \end{proposition}
    Note that $\LD^K$ is simply $\LD$ restricted to functions defined over discrete sequences in time, rather than over a time continuum.
    We obtain the following two corollaries for the DICE loss, which is formulated as an optimization problem over functions of space and time.

\begin{corollary}
\label{corr:DICESolutionParametrizedInTime}
Let \Cref{prop:DICESolutionDiscreteInTime} apply. Furthermore, let $\hs^{*} \in \mathcal S$ be a minimizer of $\LD$ and let $\bar{\hs}^* = [\hs_0^*, \dots, \hs_K^*] \in \mathcal{S}_0 \times \dots \times \mathcal{S}_K$ be a minimizer of $\LD^K$. Then, it holds that
\begin{align}\label{eq:DICEDiscSolEqual}
    \|\nabla \hs^*(t_j, \cdot) - \nabla  \hs^*_j \|_{L^2(\rho(t_j))} = 0\,,\qquad j = 0, \dots, K\,.
\end{align}
\end{corollary}

\begin{corollary}
\label{corr:DICELowerBound}
    Let  \Cref{prop:DICESolutionDiscreteInTime} apply. The loss $\LD$ is lower bounded over $\mathcal{S}$. 
\end{corollary}




\section{The DICE loss in the infinite data limit}\label{sec:DICEInfinite}
In this section, we consider the error between the gradient field $\nabla\hat{s}^*$ given by a minimizer of the DICE loss over $\mathcal{S}$ and the true gradient field $\nabla s^*$. In \Cref{sec:Infinite:BoundedDensity}, we make assumptions on the boundedness of the density $\rho(0)$ at initial time $t = 0$ and discuss their implications.  In \Cref{sec:Infinite:DiscTime}, we then bound the error of the DICE minimizer at the discrete time points $\{t_j\}_{j = 0}^K$ at which the time marginals are available. The main result is presented in \Cref{sec:Infinite:InBetweenDiscTime} and establishes that the error between the DICE optimizer and the true gradient field is of first order with respect to the maximum distance between successive time points. We further show in \Cref{sec:Infinite:BoundInference} that the error of samples generated with the flow corresponding to the learned vector field is also first order with respect to the maximum distance between successive time points.  

\subsection{Bounded density functions from flow maps}\label{sec:Infinite:BoundedDensity}

We now make stronger assumptions on the density function so that we obtain constants that only depend on the initial density $\rho(0)$ as well as the vector field $u$ that generates the flow of the samples. Recall that we assume there exists a vector field $u$ such that $\partial_t \rho + \nabla \cdot (u \rho) = 0$.

\begin{assumption}[Upper and lower bounds on $\rho(0)$ for regular flows]
\label{asm:Smooth} 
There exist constants $\overline{\rho}_0 \geq \underline{\rho}_0 > 0$ such that the density function $\rho(0, \cdot): \mathcal{X} \to \mathbb{R}$ at time $t_0 = 0$ is bounded from above and below as 
\begin{equation}
    \underline{\rho}_0 \leq \rho(0, x) \leq \overline{\rho}_0\,,\qquad x \in \mathcal{X}\,.
\end{equation}
The flow map $\phi_t: \mathcal{X} \to \mathcal{X}$ given by the ODE \eqref{eq:Prelim:ODE} corresponding to the vector field $\nabla s^* = u$ is a twice continuously differentiable diffeomorphism for all $t \in [0, T]$ at any point $x \in \mathcal{X}$.
\end{assumption}

Recall that by our assumptions on $\mathcal X$, \Cref{asm:Smooth} implies that all $\rho(t)$ satisfy a Poincaré inequality with constant $\lambda(t) = \lambda_{\mathcal X} \min_{x \in \mathcal X} \rho(t, x)$ or better so that \Cref{assumption:prelim:poincare} is satisfied. \Cref{asm:Smooth} implies that the trajectories of the flow $\phi_t$ do not cross. Thus, given a point $x \in \mathcal{X}$, we can find a point $a \in \mathcal{X}$ such that $x = \phi_t(a)$ by inverting the flow map. Note that our convention for the flow map is such that it starts at time $t = 0$. We denote by $\phi_{t, \tau}: \mathcal{X} \to \mathcal{X}$ the map from time $\tau$ to time $t$,
    \begin{align}
        \phi_{t, \tau}(x) = \phi_t(\phi_{\tau}^{-1}(x)).
    \end{align}
The point $a \in \mathcal{X}$ can be interpreted as a label for the initial position of a particle. The point $\phi_t(a) \in \mathcal{X}$ is the position of the particle at time $t$. 

The regularity of the field $u$ controls the regularity of the flow map: If $u$ is $k$-times continuously differentiable in space $x$ and $\phi_t$ is defined for all $t \in [0,T]$, then the flow map $\phi_t$ is $k$-times continuously differentiable in space at all $t \in [0, T]$ and $t \mapsto D\phi_t(x)$ is $k+1$-times differentiable at all $x \in \mathcal{X}$; see \citet[Lemma 4.1.9]{abraham_manifolds_1988} for a proof. Building on the flow map $\phi_t$, the density $\rho(t, \cdot)$ at time $t$ is
\begin{align}
\rho(t, x) = \rho_0(\phi_t^{-1}(x)) \exp\left( - \int_0^t (\nabla \cdot u)(\tau, \phi_\tau(\phi_t^{-1}(x))) \, d\tau \right)\,,\qquad (t, x) \in [0, T] \times \mathcal{X}
\end{align}
by the method of characteristics. Through this construction, we see that bounds on $\rho(0, \cdot)$ imply bounds on $\rho(t, \cdot)$ over the whole time interval $[0, T]$, as the following lemma shows.

\begin{lemma}
\label{prop:dice:bounds_on_rho}
    Let \Cref{asm:Smooth} hold, then
    \begin{align}
        \rho(t, x) \leq \overline{\rho}_0 \exp\left( \overline{c} t \right), \quad \rho(t, x) \geq \underline{\rho_0} \exp\left( - \underline{c} t \right)\,,\qquad (t, x) \in [0, T] \times \mathcal{X}\,,
    \end{align}
where $\underline{c}$ and $\overline{c}$ are positive constants that depend on the divergence $\nabla \cdot u$ of $u$ and are finite when $u(t, \cdot)$ is continuously differentiable in space for all $t \in [0, T]$.
\end{lemma}

The bounds on $\rho$ mean that functions in $L^2(\rho(t_j))$ are also in $L^2(\rd x)$ for all $j$. This simplifies the following arguments.

\subsection{Error of DICE minimizer at discrete time points}\label{sec:Infinite:DiscTime}
Consider the marginals $\{\rho(t_j)\}_{j = 0}^K$ corresponding to $K+1$ time steps. Let $\hat{s}^* \in \mathcal{S}$ be a function that minimizes the DICE loss \eqref{eq:Loss_DICE}.  
The function $\hat{s}^*$ satisfies the time-discrete weak form of the continuity equation \eqref{eq:DICE:DiscreteCompat} at the $K$ time steps,
\begin{equation}\label{eq:DICE:Smooth:ContEqsHat}
 \int_{\mathcal X} \varphi(x) \hat \delta_{t_j} \rho(t_j, x) \, \rd x = \int_{\mathcal X} \nabla \varphi(x) \cdot \nabla \hat s^*(t_j, x) \rho(t_j, x) \, \rd x \,,\quad  \varphi \in H^1_0(\mathrm dx), j = 0, \dots, K\, ,
\end{equation}
where $H^1_0(\mathrm dx)$ is the set of functions $\varphi \in L^2(\mathrm dx)$ that have bounded derivative $\nabla \varphi \in L^2(\mathrm dx)$ such that $\nabla \varphi(x) \cdot n(x) = 0$ on the boundary of $\mathcal{X}$, where $n(x)$ denotes the unit normal. Notice that we use test functions in $H_0^1(\mathrm dx)$ now because the bounds on $\rho$ in \Cref{asm:Smooth} mean that functions in $L^2(\rho(t_j))$ are in $L^2(\mathrm dx)$ too; see \Cref{prop:dice:bounds_on_rho}.
The operator $\hat{\delta}_{t_j}$ denotes the  finite-difference approximations of the time derivatives 
\begin{equation}\label{eq:DICE:Smooth:DefDeltaRho}
\hat \delta_{t_j} \rho(t_j, \cdot) = \frac{\rho(t_{j+1}, \cdot) - \rho(t_{j-1}, \cdot)}{t_{j+1} - t_{j-1}}\,,\qquad j = 0, \dots, K\,.
\end{equation}
Because of the regularity assumptions on $\rho$ made in \Cref{asm:Smooth}, the density is strictly positive and bounded. This turns the continuity equation into an elliptic problem with homogeneous Neumann boundary conditions; see Section~\ref{sec:Cont}.


\begin{proposition}[Error bound for DICE solution at data time points]\label{prop:DICEErrorBoundAtDataTimepoints} Let \Cref{asm:Smooth} hold and recall that $\nabla s^*$ is the unique gradient field that is compatible with $\rho$. Then, for $j = 0, \dots, K$, and for $\hat{s}^*$ is a DICE minimizer over $\mathcal{S}$,
    \begin{align}\label{eq:DiscTimeBound}
        \| \nabla s^*(t_j, \cdot) - \nabla \hat s^*(t_j, \cdot) \|_{L^2(\rho(t, \cdot))} \leq \lambda_{\mathcal X}^{-1/2} \underline{\rho}_0^{-1} \exp\left( \underline{c} t_j \right) \| (\partial_t - \hat \delta_{t_j}) \rho(t_j, x) \|_{L^2(\rd x)}\,.
    \end{align}
\end{proposition}
The bound \eqref{eq:DiscTimeBound} only holds at the discrete time points $t_0, \dots, t_K$. Bounding the error  between time points $t \in [t_{j-1}, t_j]$ is the topic of the next subsection. 

\subsection{Error of DICE minimizer between discrete time points}\label{sec:Infinite:InBetweenDiscTime}
To bound the error of the gradient field $\nabla\hat{s}^*$ obtained with DICE with respect to the actual gradient field $\nabla s^*$, we make assumptions on the acceleration of the density $\rho$ in time, i.e., its second derivative in time. The reason is that in DICE, we approximate $\partial_t \rho$ by finite differences. The accuracy of this approximation depends on the second derivative of $\rho$ in time.

\begin{proposition}[Error of DICE minimizer at all times]
    \label{prop:DICE:BoundForAllT}
    Let \Cref{asm:Smooth} hold. Let $\hat s$ be the linear-in-time interpolant as defined in \eqref{eq:DICEPieceWiseLinearInTime} of $\hat s^*(t_0, \cdot), \ldots, \hat s^*(t_K, \cdot)$ for a DICE minimizer $\hat{s}^* \in \mathcal{S}$. If $\rho$ is twice continuously differentiable over $t \in (0, T)$ for all $x \in \mathcal X$, then
    \begin{align}\label{eq:PropBoundOverallContTime}
        \| \nabla s^*(t, \cdot) - \nabla \hat s(t, \cdot) \|_{L^2(\rho(t))} \leq C \Delta t_{\mathrm{max}}\,, \qquad t \in [0, T],
    \end{align}
    holds, where the maximal time-step size is $\Delta t_{\mathrm{max}} = \max_{j = 1, \dots, K} \{ t_j - t_{j-1} \}$. The constant $C > 0$ can be upper bounded as
    \begin{equation}
    C \leq 3 \lambda^{-1/2}_{\mathcal X} \, \overline{\rho_0} \exp\left( \overline{c} T \right) \left( C_{\partial_t^2\rho} + \overline{\rho}_0 \exp \left( \overline{c} T \right) \left( \max_{t \in [0,T]} \| \partial_t \rho(t) \|_{L^2(\rd x)} \right ) \max_{t \in [0,T]} \|\partial_t \rho(t)\|_{L^{\infty}(\mathrm dx)} \right) \,,
    \end{equation}
    with $C_{\partial_t^2\rho} = \max_{t \in [0,T]} \| \partial_t^2 \rho(t) \|_{L^2(\rd x)};$
    thus, in particular, $C$ depends on derivatives of $\rho$ and $s^*$ only and is independent of the time-step sizes $t_j - t_{j - 1}$ for $j = 1, \dots, K$. 
    \end{proposition}

The proposition leads to a corollary for the error of the DICE minimizer $\hat{s}^*$ that is not necessarily linearly interpolating between the time points $\{t_j\}_{j = 0}^K$. 

\begin{corollary}
\label{corr:DICE:BoundForAllT_NNDiscretization}
Let \Cref{prop:DICE:BoundForAllT} apply and recall that $\hat s^* \in \mathcal{S}$ is a DICE minimizer. If $\hat{s}^*$ is Lipschitz in $t$ with respect to $\|\cdot\|_{L^2(\rho(t))}$ with constant $L^t_{\hat s^*} > 0$, 
    \begin{align}
        \| \nabla \hat s^*(t, \cdot) - \nabla \hat s^*(\tau, \cdot) \|_{L^2(\rho_t)} \leq L^t_{\hat s^*} |t - \tau| \qquad \forall t, \tau \in [0, T]\,,
    \end{align}
then the bound \eqref{eq:PropBoundOverallContTime} remains true for $\hat{s}^*$ and not only the linear interpolant $\hat{s}$, 
\begin{equation}
\label{eq:PropBoundOverallContTime_NNDiscretization}
        \| \nabla s^*(t, \cdot) - \nabla \hat s^*(t, \cdot) \|_{L^2(\rho(t))} \leq C(L^t_{\hat s^*}) \Delta t_{\mathrm{max}}\,, \qquad t \in [0, T] \, ,
\end{equation}
except that now the constant $C(L^t_{\hat{s}^*}) > 0$ depends on the Lipschitz constant $L^t_{\hat{s}^*}$ of $\hat{s}^*$. 
\end{corollary}



Because \Cref{prop:DICE:BoundForAllT} holds with a constant $C$ that can be upper bounded independent of the number of time steps $K$ and the time-step sizes $t_{j} - t_{j - 1}$, we can take the limit so that $\max_j |t_{j} - t_{j - 1}| \to 0$. Let $\hat{s}_{\Delta t_{\text{max}}}^*$ be a DICE minimizer for $\Delta t_{\text{max}} = \max_j |t_j - t_{j - 1}|$. We then  obtain convergence in the sense 
    \begin{align}
        \|\nabla \hat{s}_{\Delta t_{\text{max}}}^*(t, \cdot) - \nabla {s}^*(t, \cdot)\|_{L^2(\rho(t))} \to 0 \text{ for } \Delta t_{\text{max}} \to 0\,, \qquad t \in [0,T].
    \end{align}
This result also motivates taking the limit of $\Delta t_{\text{max}} \to 0$ on the DICE loss $\LD$ itself, which recovers \eqref{eq:Cont:ContLossddtau} as long as the time integral exists.




\subsection{Bound for the inference error}\label{sec:Infinite:BoundInference}
Let \Cref{asm:Smooth} hold and, furthermore, assume that $\hat{s}^*$ is a DICE minimizer. The following proposition bounds the error between the law $\hat{\rho}$ obtained from the continuity equation with the field $\nabla \hat{s}^*$ and the law $\rho$ corresponding to the actual gradient field $\nabla s^*$ in the 2-Wasserstein metric $W_2$. The key step in the proof is a Gr\"onwall-type argument. 

\begin{proposition}[DICE inference error]
\label{prop:bound_on_inference_error_w2}
Let \Cref{asm:Smooth} apply and let $\hat{s}^*$ be a twice continuously differentiable DICE minimizer so that \Cref{prop:DICE:BoundForAllT} holds. Let $\hat{\rho}$ be the density function obtained from $\nabla \hat{s}^*$ via the continuity equation in weak form \eqref{eq:Prelim:ContWeakForm} with $\hat{\rho}(0, \cdot) = \rho(0, \cdot)$. Then, the difference between $\rho(t, \cdot)$ and $\hat{\rho}(t, \cdot)$ in the $W_2$ metric is bounded as
\begin{align}
    W_2(\rho(t, \cdot), \hat \rho(t, \cdot))
    \leq \left( W_2(\rho(0, \cdot), \hat \rho(0, \cdot)) + C(L^t_{\hat s^*}) t \Delta t_{\text{max}}
    \right) \mathrm e^{ \int_0^t L_{\hat s^*}^x(\tau) \, \rd \tau}
\end{align}
where $C(L^t_{\hat s^*})$ denotes the constant in \eqref{eq:PropBoundOverallContTime_NNDiscretization} in \Cref{corr:DICE:BoundForAllT_NNDiscretization} and the constant $L_{\hat s^*}^x(t)$ is  
\begin{align}
L_{\hat s^*}^{x}(t) =  \sup_{x \in \mathcal X} \Vert D^2_x \hat s^*(t, x) \Vert_{\mathrm{op}}\,,
\end{align}
with $D^2_x \hat s^*(t, x)$ denoting the Hessian of $\hat{s}^*$ with respect to $x$. 
    \end{proposition}

    There are two ways to control $L_{\hat s^*}^x(t)$. First, in practice, $\hat s^*$ will be represented in parametrized form such as a neural network, which can be chosen to limit the norm of $D^2 \hat s^*$. Second, bounds on the difference $D^2 s^*(t_j, \cdot) - D^2 \hat s^*(t_j, \cdot)$ in H\"older norms can be derived when $\rho$ and the domain are regular enough (by tools from Schauder theory, c.f. \citet[Chapter 6]{gilbarg_elliptic_2001}). Estimates at time $t_j$ can then be extended to $t \in [t_j, t_{j+1}]$ as we did for $\nabla s^*(t, \cdot) - \nabla \hat s^*(t, \cdot)$ in \Cref{prop:DICE:BoundForAllT}. We leave a thorough investigation of this for future work.


\section{Comparing DICE to Action Matching}\label{sec:CmpAM}
We compare training with the DICE loss to the AM loss. We first describe the AM loss in \Cref{sec:AM:AMLoss}. We then show in \Cref{sec:AM:ResidualTerm} that the DICE loss avoids residual terms that can emerge in the time-discrete AM loss and destabilize the training by growing arbitrarily large. A concrete example where AM is unstable is introduced in \Cref{sec:blowup_example}. 


\subsection{The AM loss function}\label{sec:AM:AMLoss}
The AM loss is derived by \cite{neklyudov_action_2023} with partial integration in time from the dynamical transport problem introduced by \cite{benamou_computational_2000}, and reads
    \begin{align}
        \label{eq:OV_Loss}
        \cAM(\hat s) 
        &= \int_0^T \mathbb{E}_{x \sim \rho(t)} \left[ \frac{1}{2} |\nabla \hat s(t, x)|^2 + \partial_t \hat s(t, x) \right] \rd t - \mathbb{E}_{x \sim \rho(t)} \left[ \hat s(t, x) \right] \bigg|_{t=0}^T.
    \end{align}
In the time-continuous formulation, the AM loss controls the continuous counterpart of the error that is controlled by the minimizers of the DICE loss (\Cref{corr:DICE:BoundForAllT_NNDiscretization}), 
\begin{equation}\label{eq:AM:Error}
   \int_0^T \|\nabla s^*(t, x) - \nabla \hat s(t, x)\|_{L^2(\rho(t))}\mathrm dt = \cAM(\hat s) + C(\nabla s^*)\,,
   \end{equation}
   where $C(\nabla s^*)$ is a constant that only depends on the actual gradient field $\nabla s^*$ but is independent of $\hat s$ \citep{neklyudov_action_2023}. 

   The time-discrete AM loss  is
    \begin{align}
        \label{eq:AM_Loss}
        \LAM(\hat s) = \sum_{j=0}^{K} w_j \, \E_{x \sim \rho(t_j)} \left[ \left( \partial_t \hat s + \frac{1}{2} | \nabla \hat s |^2 \right) (t_j, x) \right] - \E_{x \sim \rho(t)} \left[ \hat s(t, x) \right] \bigg |_{t = 0}^{T}.
    \end{align}
    Here the integral in time is numerically computed with a quadrature rule given by $K+1$ nodes $\{(t_j, w_j) \}_{j = 0}^{K}$; this may be, for example, a Monte Carlo estimator as in \cite{neklyudov_action_2023}, or it may be a deterministic rule as in \cite{berman2024parametric}.  The time-discrete AM loss controls the error \eqref{eq:AM:Error} then up to the quadrature error $|\cAM(\hat s) - \LAM(\hat s)|$.


\subsection{The DICE loss avoids unbounded residual terms that can emerge in the empirical AM loss during training}\label{sec:AM:ResidualTerm}
Recall that our problem statement from \Cref{sec:Prelim:ProblemFormulation} determines a field $\hat s$ only up to a function $f: [0,T] \to \mathbb{R}$ because $\nabla (\hat s + f) = \nabla \hat s$ for any $f$ that is constant in space $\mathcal{X}$ but can vary with time $t$. 
Notice that, for such $f$, the time-continuous AM loss satisfies $\cAM(\hat s + f) = \cAM(\hat s)$.
The DICE loss, which is time-discrete by definition, is also invariant in that $\LD(\hat s + f) = \LD(\hat s)$ for such $f$; see \Cref{prop:InvariantF}.
However, the time-discrete AM loss $\LAM$ can violate this invariance.
    \begin{proposition}\label{prop:AM:BadConstant}
        The time-discrete AM Loss is not necessarily invariant with respect to addition of a spatially constant but time varying function $f: [0, T] \to \bR$. It holds that
        \begin{align}
        \label{eq:AM:LossInvariance}
            \LAM(\hat s + f) = \LAM(\hat s) + R(f)\,,
        \end{align}
        where
        \begin{align}\label{eq:AM:ResTerm}
            R(f) = \sum_{j=0}^{K} w_j \, \partial_t f(t_j) - f(T) + f(0)\,.
        \end{align}
    \end{proposition}

    \begin{proof}
    We substitute $\hat s + f$ into \eqref{eq:AM_Loss}: 
    \begin{multline}
        \LAM(\hat s + f) = \sum_{j=0}^{K} w_j \, \E_{x \sim \rho(t_j)} \left[ \left( \partial_t s + \partial_t f + \frac{1}{2} | \nabla \hat s + \nabla f|^2 \right) (t_j, x) \right] \\ 
            - \E_{x \sim \rho(t)} \left[ (\hat s + f)(t, x) \right] \bigg |_{t = 0}^{T}\,.
    \end{multline}
    Because $\nabla f = 0$, we obtain 
    \begin{align}
        \LAM(\hat s + f) = \LAM(\hat s) + \sum_{j=0}^{K} w_j \, \partial_t f(t_j) - f(T) + f(0)\,,
    \end{align}
    as claimed.
    \end{proof}

Because of the residual term $R(f)$, the quadrature error in the time-discrete AM loss can be made arbitrarily large, which means that $|\cAM(\hat s) - \LAM(\hat s)|$ gets large and thus minimizing the time-discrete AM loss $\LAM(\hat s)$ does not reflect the error \eqref{eq:AM:Error} well anymore. When $f$ is a function with sharp gradients, the second, spurious term of the discrete AM loss can dominate the first term in \eqref{eq:AM:LossInvariance}. This can lead to a negative feedback loop that destabilizes the training with the AM loss; as shown 
in the next section. The residual term $R(f)$ given in \eqref{eq:AM:ResTerm} depends on the quadrature rule used for the time integral.  \cite{berman2024parametric} investigate higher-order quadrature rules in time to keep the residual term small; however, it does not vanish. 

We illustrate this in \Cref{fig:t_tau_dep_of_s}. We view the function $t \mapsto \bE_{x \sim \rho(t)}[s(t, x) + f(t)]$ in terms of the map $(\tau,t) \mapsto \bE_{x \sim \rho(\tau)}[s(t, x) + f(t)]$ evaluated at point $\tau=t$ for a potentially rough $f$. Then, the function $\tau \mapsto \bE_{x \sim \rho(\tau)}[s(t, x) + f(t)]$ for fixed $t$ is a regular function, controlled by the evolution of samples. In contrast, $t \mapsto \bE_{x \sim \rho(\tau)}[s(t, x) + f(t)]$, for fixed $\tau$, can be an arbitrarily rough function when the value of the constant $f(t)$ is not controlled. The DICE loss only depends on map $\tau \mapsto \bE_{x \sim \rho(\tau)}[s(t, x) + f(t)]$ (see \Cref{eq:Cont:ContLossddtau}). In contrast, the AM loss, through the $\partial_t s$ term therein, depends on $t \mapsto \bE_{x \sim \rho(\tau)}[s(t, x) + f(t)]$.

