\includegraphics[width=0.9\columnwidth]{plots_dice/dice_dt_converge.pdf}\caption{error versus number training samples in time}
\end{subfigure}
\caption{Known potential: Training with the DICE loss leads to stabler training behavior compared to the AM loss in this example. We observe a decrease in error as we increase the batch size in time $n_t$. At around $n_t = 128$, the error is mostly dominated by the error in $n_x$, which is held constant at $n_x = 256$.}
\label{fig:AnalyticExampleErrorPlot}
\end{figure}

In this experiment, we consider a process $X(t)$ that follows the time-dependent potential 
\begin{align}
    V(t, x) = \sin \left(\frac \pi 2 t \right)^2 V_1(x) + \cos \left(\frac \pi 2 t \right)^2 V_0(x)
\end{align}
with
\begin{align}
    V_0(x) = \sum_{i=1}^d \left( \sin(x_i) + \cos(x_i) + x_i^2 + x_i \right), \quad
    V_1(x) = \sum_{i=1}^d \left( x_i^4 - 16 x_i^2 + 5 x_i \right)\,.
\end{align}
Having the potential $V$ given analytically allows us to estimate the error 
$$ \int_t \bE_{x \sim \rho(t)} \left[ | \nabla \hat s(t, \cdot) - \nabla V(t, \cdot) |^2 \right] \mathrm dt,$$
which is the error of $\hat{s}$ that is also considered in Proposition~\ref{prop:DICE:BoundForAllT}. We consider the relative error of the potential, which we estimate as  
\begin{align}
    \sum_{j=0}^K w_j \, \frac{ \hat{\mathbb E}_{x \sim \rho(t_j)} \left[ | \nabla \hat s(t_j, \cdot) - \nabla V(t_j, \cdot) |^2 \right] }{ \hat{\mathbb E}_{x \sim \rho(t_j)} \left[ | \nabla V(t_j, \cdot) |^2 \right]  }
\end{align}
on the training data time steps $t_0, \dots, t_K$, where the $w_0, \dots, w_K$ denote quadrature weights for the composite trapezoidal integration.


We draw $N_0 = 2048$ samples from $\rho_0 = \mathcal N(0, 1)$ where $d = 2$ and set the time-step size to $\Delta t = 1/512$. The rest of the setup is as described at the beginning of \Cref{sec:NumExp}.  Figure~\ref{fig:AnalyticExampleErrorPlot} shows that the DICE loss allows us to accurately infer the time-dependent gradient field $\nabla V$. The example shows that DICE does indeed recover the sample dynamics in cases where they follow a time-dependent gradient flow. In contrast, the AM loss exhibits the same instability that was observed in the example in subsection \ref{ssec:DvsAM} for high optimization iteration numbers.

