\section{Proofs}

\subsection{The DICE loss is a variational formulation of the continuity equation}
\begin{proof}[\Cref{prop:DICEEulerLagrangeEq}]
    \label{proof:DICEEulerLagrangeEq}
    Consider $s^\varepsilon$ such that $s^\varepsilon(t_j, x) = \hat{s}^*(t_j, x) + \varepsilon \varphi_j(x)$ with $\varphi_j \in \mathcal C^\infty_0(\mathcal X)$ for all $j$. If $\hat{s}^*$ is optimal for \eqref{eq:Loss_DICE}, then it has to hold that
        \begin{align}\label{eq:DICE:DICEMinimizer:EqB}
            \frac{\rd}{\rd \varepsilon} \mathrm{L}_{\mathrm{DICE}}(s^\varepsilon) \bigg |_{\varepsilon = 0} = 0\,, \qquad \text{ for all } \varphi_j \in \mathcal C^\infty_0(\mathcal X) \text{ and  } j = 0, \dots, K.
        \end{align}
        We now write for brevity
        \begin{align}
            \bE_j = \bE_{x\sim\rho(t_{j})}, \; \hat{s}_j^* = \hat{s}^*(t_j, \cdot), \text{ and } (\bE_{j+1} - \bE_{j})[s] = \bE_{j+1}[s] - \bE_{j}[s].
        \end{align}
        Because
        \begin{align}
            \frac{\rd}{\rd \varepsilon} \bE_j \left[ \frac{1}{2} |\nabla s^\varepsilon_j |^2 \right]
            &= \frac{\rd}{\rd \varepsilon} \bE_j \left[ \frac{1}{2} |\nabla \hat{s}^*_j + \varepsilon \nabla \varphi_j|^2 \right] \\
            &= \bE_j \left[ \nabla \hat{s}^*_j \cdot \nabla \varphi_j + \varepsilon |\nabla \varphi_j|^2 \right]
        \end{align}
        and
        \begin{align}
            \frac{\rd}{\rd \varepsilon} \bE_j \left[ s^\varepsilon_j \right] = \bE_j \left[ \varphi_j \right],
        \end{align}
        we find
        \begin{multline}\label{eq:DICE:DICELossEqA}
            \frac{\rd}{\rd \varepsilon} \mathrm{L}_{\mathrm{DICE}}(s^\varepsilon) \bigg |_{\varepsilon = 0} 
            = \sum_{j=1}^{K} \bigg( \frac{t_j - t_{j-1}}{2} \left( \bE_j \left[ \nabla \hat{s}^*_j \cdot \nabla \varphi_j \right] + \bE_{j-1} \left[ \nabla \hat{s}^*_{j-1} \cdot \nabla \varphi_{j-1} \right] \right)  \\
            - \frac{1}{2} \left( \bE_j - \bE_{j-1} \right) \left[ \varphi_j + \varphi_{j-1} \right] \bigg)\,,  
        \end{multline}
        for all $\varphi_j  \in \mathcal C^\infty_0(\mathcal X)$ and for $j = 0, \dots, K$. 

        Now let $j^* = 1, \dots, K - 1$ and set $\varphi_j$ to the constant zero $\varphi_j \equiv 0$ function for all $j \in \{0, \dots, K\}\setminus \{j^*\}$. Recall that \eqref{eq:DICE:DICELossEqA} has to be zero for all $\varphi_j  \in \mathcal C^\infty_0(\mathcal X)$ and thus it has to be zero also for our particular choice of test functions. We therefore obtain that for all $j^* = 1, \dots, K - 1$, the following equation has to hold for all $\varphi_{j^*} \in C^\infty_0(\mathcal X)$ 
        \begin{multline}
            0 = \frac{t_{j^*} - t_{j^*-1}}{2}  \bE_{j^*} \left[\nabla \hat{s}^*_{j^*} \cdot \nabla \varphi_{j^*} \right]  - \frac{1}{2} \left( \bE_{j^*} - \bE_{j^* - 1} \right) \left[ \varphi_{j^*} \right] \\
            + \frac{t_{j^*+1} - t_{j^*}}{2}  \bE_{j^*} \left[ \nabla \hat{s}^*_{j^*} \cdot \nabla \varphi_{j^*} \right]  - \frac{1}{2} \left( \bE_{j^* +1 } - \bE_{j^*} \right) \left[ \varphi_{j^*} \right]\,,
        \end{multline}
        which can be re-written as
        \begin{align}
            \frac{1}{t_{j^*+1} - t_{j^*-1}} (\bE_{j^* + 1} - \bE_{j^*})\left[ \varphi_{j^*} \right] = \bE_{j^*} \left[\nabla \hat{s}^*( t_{{j^*}}, \cdot) \cdot \nabla \varphi_{j^*} \right] ,
        \end{align}
        which is equation $j^*$ in the system of equations given in \eqref{eq:DICE:DiscreteCompat}.
        For $j^* \in \{0, K\}$, we find
        \begin{align}
            0 &= \frac{t_{1} - t_{0}}{2} \left( \bE_{0} \left[ \nabla \hat{s}^*_{0} \cdot \nabla \varphi_{0} \right] \right) - \frac{1}{2} \left( \bE_{1} - \bE_{0} \right) \left[ \varphi_{0} \right], \\
            0 &= \frac{t_{K} - t_{K-1}}{2} \left( \bE_{K} \left[ \nabla \hat{s}^*_{K} \cdot \nabla \varphi_{K} \right] \right) - \frac{1}{2} \left( \bE_{K} - \bE_{K-1} \right) \left[ \varphi_{K} \right],
        \end{align}
        which correspond to equations $j = 0$ and $j = K$, respectively, of the system \eqref{eq:DICE:DiscreteCompat}.
        % \begin{align}
        %     \frac{\bE_{x\sim\rho(t_{{1}})} - \bE_{x\sim\rho(t_0)}}{t_{1} - t_{0}} \left[ \varphi_{0}(x) \right] &= \bE_{x\sim \rho(t_{{0}})} \left[\nabla \hat{s}^*(x, t_{0}) \cdot \nabla \varphi_{0}(x) \right], \\
        %     \frac{\bE_{x\sim\rho(t_{{K}})} - \bE_{x\sim\rho(t_{K-1})}}{t_{K} - t_{K-1}} \left[ \varphi_{K}(x) \right] &= \bE_{x\sim \rho(t_{{K}})} \left[\nabla \hat{s}^*(x, t_{K}) \cdot \nabla \varphi_{K}(x) \right]\,,
        % \end{align}
        % respectively. 
    In summary we showed that a minimizer of the DICE loss satisfies \eqref{eq:DICE:DICEMinimizer:EqB} and thus also has to solve  the system of equations \eqref{eq:DICE:DiscreteCompat} corresponding to the time-discrete weak form of the continuity equation. 
    \end{proof}

\subsection{Existence and uniqueness of DICE minimizers}\label{appdx:ExistenceProof}
\begin{proof}[\Cref{prop:DICESolutionDiscreteInTime}]
\label{proof:DICESolutionDiscreteInTime} First, denote the Poincaré constant of \Cref{assumption:prelim:poincare} at time $t_j$ as $\lambda(t_j) = \lambda_j$ for $j = 0, \dots, K$. 
    We can then re-write the objective function in  \eqref{eq:DICEDiscreteDecoupled} as
    \begin{equation}\label{eq:DICE:Unique:LFun}
        \mathrm{L}_{\mathrm{DICE}}^{K}(\bar{\hat s}) = \sum_{j=0}^K  \int_{\mathcal X} \left( \frac{t_{j+1} - t_{j-1}}{4} |\nabla \hat s_j(x)|^2 - \frac{\rho(t_{j+1}, x) - \rho(t_{j-1}, x)}{2\rho(t_j, x)} \hat s_j (x) \right) \rho(t_j, x) \, \rd x\,.
    \end{equation}
    We obtain the bounds 
    \begin{align}
            \mathrm{L}_{\mathrm{DICE}}^{K}(\bar{\hat s}) &\geq \sum_{j=0}^K  \left( \frac{t_{j+1} - t_{j-1}}{4} \Vert \nabla \hat s_j \Vert_{L^2(\rho(t_j))}^2 - \left \Vert \frac{\rho(t_{j+1}, x) - \rho(t_{j-1}, x)}{2 \rho(t_j, x)} \right \Vert_{L^2(\rho(t_j))} \Vert \hat s_j \Vert_{L^2(\rho(t_j))} \right) \\
            &{\geq} \sum_{j=0}^K  \left( \lambda_j \frac{t_{j+1} - t_{j-1}}{4} \Vert \hat s_j \Vert_{L^2(\rho(t_j))}^2 - \left \Vert \frac{\rho(t_{j+1}, x) - \rho(t_{j-1}, x)}{2\rho(t_j, x)} \right \Vert_{L^2(\rho( t_j))} \Vert \hat s_j \Vert_{L^2(\rho(t_j))} \right) \\
            &\geq - \frac{1}{2} \sum_{j=0}^K \frac{2}{\lambda_j (t_{j+1} - t_{j-1})} \left \Vert \frac{\rho(t_{j+1}, x) - \rho(t_{j-1}, x)}{2\rho(t_j, x)} \right \Vert_{L^2(\rho( t_j))}^2,\label{eq:DICE:LowerBoundInProof}
        \end{align}
        where we used first the Cauchy-Schwarz inequality, then the Poincar\'e inequality, and then the fact that $\min_a \frac{ \lambda }{2} a^2 - ab = - \frac{1}{2\lambda} b^2$ for $a, b \in \mathbb{R}$ for $\lambda > 0$. Notice that when applying the Poincar\'e inequality, we assumed without loss of generality that $\mathbb{E}_{x \sim \rho(t_j)}[\hat{s}_j(x)] = 0$. We indeed can assume this without loss of generality because of \Cref{prop:InvariantF}, which also applies to the loss  \eqref{eq:DICE:Unique:LFun}. Thus, the loss value is unchanged:  $\mathrm{L}_{\mathrm{DICE}}^{K}(\bar{\hat s}) = \mathrm{L}_{\mathrm{DICE}}^{K}(\bar{\hat s}^0)$ for normalized $\bar{\hat{s}}^0$ that subtracts the constant $\mathbb{E}_{x \sim \rho(t_j)}[\hat{s}_j]$ from each component of $\bar{\hat{s}}$. 

        Given the quadratic nature of the objective function in \eqref{eq:DICEDiscreteDecoupled} and boundedness from below over $\mathcal{S}_0 \times \cdots \times \mathcal{S}_K$ as shown in  \eqref{eq:DICE:LowerBoundInProof}, existence and uniqueness of a minimizer now follows from standard arguments: We define the vector $\bar{l}(x) = [l_0, \dots, l_K]$ with components $j = 0, \dots, K$ given by 
        \begin{align}
            l_j(x) = \frac{1}{t_{j+1} - t_{j-1}} \frac{\rho(t_{j+1}, x) - \rho(t_{j-1}, x)}{ \rho(t_j, x)}.
        \end{align}
        Because \eqref{eq:DICErho_log_deriv_is_L2} holds, we obtain $\Vert \bar{l} \Vert_{L^2(\rho(t_0) \cdots \rho(t_K))}^2 < \infty$. We can then write the functional $\LD^K(\bar{\hat s})$ with \eqref{eq:DICE:Unique:LFun} as
        \begin{equation}\label{eq:DICE:LObjRewrite}
        \LD^K( \bar{\hat s}) = \frac{1}{2} \Vert \mathrm D \bar{\hat s} \Vert_{L^2(\rho(t_0) \cdots \rho(t_K))}^2 - \langle \bar{l}, \bar{\hat s}\rangle_{L^2(\rho(t_0) \cdots \rho(t_K))}\,.
    \end{equation}
    First, we again assume without loss of generality that $\bar{\hat{s}}$ has normalized components. Now notice that for any $\bar{\hat s} \in \mathcal{S}^0_0 \times \dots \times \mathcal{S}^0_K$ it holds: 
    \begin{align}
        \| \mathrm D \bar{\hat s} \|_{L^2(\rho(t_0) \cdots \rho(t_K))}^2
        &= \sum_{j=0}^K \frac{t_{j+1} - t_{j-1}}{2} \| \nabla \hat s_j \|_{L^2(\rho(t_j))}^2 \\
        &\geq \sum_{j=0}^K \frac{t_{j+1} - t_{j-1}}{2} \lambda_j \| \hat s_j \|_{L^2(\rho(t_j))}^2 \\
        &\geq \left(\min_{0 \leq j \leq K} \lambda_j \right) \sum_{j=0}^K \frac{t_{j+1} - t_{j-1}}{2} \|
        \hat s_j \|_{L^2(\rho(t_j))}^2 \\
        &= \left(\min_{0 \leq j \leq K} \lambda_j \right) \| \bar{\hat s} \|_{L^2(\rho(t_0) \cdots \rho(t_K)}^2.\label{appdx:ProofUniqueness:Existence:DSBoundHelper01A}
    \end{align}
Let now $( \bar{\hat s}_n)_n$ be a minimizing sequence with $\bar{\hat s}_n$ in $\mathcal{S}^0_0 \times \cdots \times \mathcal{S}^0_K$ such that  
    \begin{align}
        \lim_{n \to \infty} \LD^K(\bar{\hat s}_n) = \inf_{\bar{\bar{s}} \in \mathcal{S}_0 \times \dots \times \mathcal{S}_K} \LD^K(\bar{\bar{s}})\,,
    \end{align}
    with respect to the norm induced by the inner product $\langle \cdot, \cdot \rangle_{\mathcal{S}_0 \times \cdots \times \mathcal{S}_K}$.  Then, using \eqref{appdx:ProofUniqueness:Existence:DSBoundHelper01A} and the polarization identity $\frac{1}{2}|a|^2 + \frac{1}{2}|b|^2 = \frac{1}{4} |a - b| + \frac{1}{4} |a + b|$, we obtain 
        \begin{align}
            &\quad \, \max_{0 \leq j \leq K} \lambda_j^{-1}  \frac{1}{4} \Vert \bar{\hat s}_n - \bar{\hat s}_m \Vert_{L^2(\rho(t_0) \dots \rho(t_K))}^2 \nonumber \\
            &\leq \frac{1}{4} \Vert \mathrm D \bar{\hat s}_n - \mathrm D \bar{\hat s}_m \Vert_{L^2(\rho(t_0) \cdots \rho(t_K))}^2 \label{eq:DICE:InterABC01} \\
            &= \frac{1}{2} \Vert \mathrm D \bar{\hat s}_n \Vert_{L^2(\rho(t_0) \cdots \rho(t_K))}^2 + \frac{1}{2} \Vert \mathrm D \bar{\hat s}_m \Vert_{L^2(\rho(t_0) \cdots \rho(t_K))}^2 - \frac{1}{4} \Vert \mathrm D \bar{\hat s}_n + \mathrm D \bar{\hat s}_m \Vert_{L^2(\rho(t_0) \cdots \rho(t_K))}^2\,,
        \end{align}
        where \eqref{eq:DICE:InterABC01} is obtained via the Poincar\'e inequality. 
        We can add to this expression the term $0 = 2 \langle \bar{l}, \frac{1}{2} (\bar{\hat s}_n + \bar{\hat s}_n) \rangle 
        - \langle \bar{l}, \bar{\hat s}_n \rangle 
        - \langle \bar{l}, \bar{\hat s}_m \rangle$ (where $\langle \cdot, \cdot \rangle = \langle \cdot, \cdot \rangle_{L^2(\rho(t_0) \cdots \rho(t_K))}$) and collect terms to find
        \begin{align}
            \frac{1}{4} \Vert \mathrm D \bar{\hat s}_n - \mathrm D \bar{\hat s}_m \Vert_{L^2(\rho(t_0) \cdots \rho(t_K))}^2
            &= \LD^K( \bar{\hat{s}}_n) + \LD^K( \bar{\hat{s}}_m) - 2 \, \LD^{K}\left ( \frac{\bar{\hat s}_n + \bar{\hat s}_m}{2} \right ) \label{eq:DICE:InterABC02-1}\\ %  \text{by the Poincar\'e inequality,}\\
            %\intertext{by definition of $\LD^K$,}
            &\leq \LD^K( \bar{\hat{s}}_n) + \LD^K( \bar{\hat{s}}_m) - 2 \, \inf_{\bar{\bar{s}} \in \mathcal{S}_0 \times \dots \times \mathcal{S}_K} \LD^K(\bar{\bar{s}} )\,,\label{eq:DICE:InterABC02}
        \end{align}
         where \eqref{eq:DICE:InterABC02} is obtained because $\LD^K$ can be written as in \eqref{eq:DICE:LObjRewrite}. 
        Given that $(\bar{\hat{ s}}_n)_n$ is a minimizing sequence, for every $\epsilon > 0$ there exists an $n^*$ such that 
        \begin{align}
        \LD^K( \bar{\hat{s}}_n) - \inf_{\bar{\bar s} \in \mathcal{S}_0 \times \dots \times \mathcal{S}_K} \LD^K\left (\bar{\bar s} \right ) \leq \epsilon\,,\qquad \forall n > n^*.
        \end{align}        
        Therefore, for every $n,m > n^*$ it holds that $\Vert \mathrm D\bar{\hat s}_n - \mathrm D\bar{\hat s}_m \Vert_{L^2(\rho(t_0) \cdots \rho(t_K))}^2 \leq 2 \epsilon$ and thus $\left(\min_{0 \leq j \leq K} \lambda_j \right)^{-1} \frac{1}{4} \Vert \bar{\hat s}_n - \bar{\hat s}_m \Vert_{L^2(\rho(t_0) \cdots \rho(t_K))}^2 \leq 2 \epsilon$. Hence, $(\bar{\hat{s}}_n)_n$ is a Cauchy sequence in $\langle \cdot, \cdot \rangle_{\mathcal{S}_0 \times \dots \times \mathcal{S}_K}$ and the infimum is attained by a minimizer, the limit of the Cauchy sequence, since $\mathcal{S}_0 \times \dots \times \mathcal{S}_K$ is a Hilbert space.

        The minimum is unique in $\mathcal{S}_0^0 \times \dots \times \mathcal{S}_K^0$ with respect to $\|\cdot\|_{\mathcal{S}_0 \times \dots \times \mathcal{S}_K}$ by strict convexity of $\LD^K$. Suppose there exist two solutions $\bar s^*, \bar s^{**} \in \mathcal{S}_0^0 \times \dots \times \mathcal{S}_K^0$, then
        \begin{align}
            \frac{1}{2} \left( \LD^K(\bar{s}^*) + \LD^K(\bar{s}^{**}) \right) = \frac{1}{2} \, 2 \min_{\bar{\bar s} \in \mathcal{S}_0^0 \times \dots \times \mathcal{S}_K^0} \LD^K\left (\bar{\bar s} \right )\,.
        \end{align}
        At the same time, the strict convexity of $\LD^K$ implies
        \begin{align}
            \LD^K \left( \frac{ \bar{s}^* + \bar{s}^{**}}{2} \right) < \frac{1}{2} \left( \LD^K(\bar{s}^*) + \LD^K(\bar{s}^{**}) \right) = \min_{\bar{\bar s} \in \mathcal{S}_0^0 \times \dots \times \mathcal{S}_K^0} \LD^K\left (\bar{\bar s} \right )
        \end{align}
        for all $\|\mathrm D \bar s^* - \mathrm D \bar s^{**}\|_{L^2(\rho(t_0) \dots \rho(t_K))} > 0$. Thus, by contradiction, because $\bar{s}^*, \bar{s}^**$ are normalized, it holds $0 = \|\mathrm D \bar s^* - \mathrm D \bar s^{**}\|_{L^2(\rho(t_0) \dots \rho(t_K))} = \|\bar{s}^* - \bar{s}^{**}\|_{\mathcal{S}_0 \times \dots \times \mathcal{S}_K} = 0$. % Hence $\bar s^* = \bar s^{**}$.
    \end{proof}

    \begin{proof}[\Cref{corr:DICESolutionParametrizedInTime}]
        First, recall that $\LD(s) = \LD^K(\bar{s})$ for any $s \in \mathcal{S}$ with $\bar{s} = [s(t_0, \cdot), \dots, s(t_K, \cdot)]$. Let us now take the DICE minimizer $\hat s^* \in \mathcal{S}$ and evaluate it at the time points $t_0, \dots, t_K$ to obtain the vector of functions $\bar{v}^{*} = [\hat s^*(t_0, \cdot), \dots, \hat s^*(t_K, \cdot)]$, which is an element of the Cartesian product $\mathcal{S}_0 \times \dots \times \mathcal{S}_K$ per definition of $\mathcal{S}$. If $\LD^K(\bar{v}^*) < \LD^K(\bar{\hat{s}}^*)$, then $\bar{\hat{s}}^*$ cannot be a minimizer of $\LD^K$, which violates the assumption that $\bar{\hat{s}}^*$ is a minimizer of $\LD^K$. If $\LD^K(\bar{v}^*) > \LD^K(\bar{\hat{s}}^*)$, then $\hat{s}^*$ cannot be a minimizer of $\LD$ because stitching together the components of $\bar{\hat{s}}^*$ into a function over $\mathcal{S}$ would provide a lower value of $\LD$ than $\hat{s}^*$, which violates the assumption that $\hat{s}^*$ is a minimizer of $\LD$. Thus, we have $\LD^K(\bar{\hat{s}}^*) = \LD^K(\bar{v}^{*})$. This means that $\bar{v}^*$ is a minimizer of $\LD^K$ and thus the components of $\bar{v}^* = [\hat{s}^*(t_0, \cdot), \dots, \hat{s}^*(t_K, \cdot)]$ have to agree with the components of $\bar{\hat{s}}^*$ in the sense of \eqref{eq:DICEDiscSolEqual} due to the uniqueness of $\LD^K$ minimizers shown in \Cref{prop:DICESolutionDiscreteInTime}. 
        % Hence for $\hat s^*$ a minimizer of $\LD$, $\bar{v}^{*}$ is a minimizer of $\LD^K$. When $\bar{s}^*$ is a minimizer of $\LD^K$, then $\|\bar{v}^{*} - \bar{s}^{*}\|_{\mathcal{S}_0 \times \ldots \times \mathcal{S}_K} = 0$. This implies equality in every component, which is
        % \begin{align}
        %     0 = \|\nabla \bar v^*_j - \nabla \bar s^*_j \|_{L^2(\rho(t_j))} = \|\nabla s^*(t_j, \cdot) - \nabla \bar s^*_j \|_{L^2(\rho(t_j))}.
        % \end{align}
    \end{proof}

    \begin{proof}[\Cref{corr:DICELowerBound}]
        The value of the loss $\LD(s)$ at any $s \in \mathcal{S}$ only depends on the vector of functions $\bar{s} = [s(t_0, \cdot), \dots, s(t_K, \cdot)] \in \mathcal{S}_0 \times \dots \times \mathcal{S}_K$ at the discrete time points $t_0, \dots, t_K$ and thus coincides with $\LD^K$. It was shown in \eqref{eq:DICE:LowerBoundInProof} in the proof of \Cref{prop:DICESolutionDiscreteInTime} that $\LD^K$ is lower bounded over $\mathcal{S}^0_0 \times \dots \times \mathcal{S}^0_K$. For any $\bar s \in \mathcal{S}_0 \times \dots \times \mathcal{S}_K$, we can construct $\bar s^0 = [s(t_0, \cdot) - \mathbb E_{\rho(t_0)}[s(t_0, \cdot)] , \dots, s(t_K, \cdot) - \mathbb E_{\rho(t_K)}[s(t_K, \cdot)] ] \in \mathcal{S}^0_0 \times \dots \times \mathcal{S}^0_K$ and we have $\LD^K(\bar s) = \LD^K(\bar s^0)$ by \Cref{prop:InvariantF} and $\LD^K(\bar s^0)$ is bounded below by \Cref{prop:DICESolutionDiscreteInTime}.
    \end{proof}

    \subsection{Infinite data limit}

    \begin{proof}[\Cref{prop:dice:bounds_on_rho}]
    Denote by
    $[ \nabla \cdot u ]^-$ the negative part of $\nabla \cdot u$, defined as 
    \begin{align}
        [ \nabla \cdot u ]^-(t, x) = \begin{cases}
            \nabla \cdot u(t, x)\,, & \text{if } \nabla \cdot u(t, x) < 0\,, \\
            0\,, & \text{otherwise.}
        \end{cases}
    \end{align}
    Then, it holds 
    \begin{align}
        - \nabla \cdot u(t, x) \leq |[ \nabla \cdot u ]^-| (t, x)\leq \max_{(t, y) \in [0, T] \times \mathcal{X}} | [ \nabla \cdot u ]^- | (t, y)=: \overline{c} \quad \forall x \in \mathcal X
    \end{align}
    and analogously
    \begin{align}
        -\nabla \cdot u(t, x) \geq - [ \nabla \cdot u ]^+ (t, x) \geq - \max_{(t, y) \in [0, T] \times \mathcal{X}} [ \nabla \cdot u ]^+(t, y) =: - \underline{c} \quad \forall x \in \mathcal X.
    \end{align}
    Then,
    \begin{align}
        \rho(t, x) 
        &= \rho_0(\phi_t^{-1}(x)) \exp\left( - \int_0^t (\nabla \cdot u)(\tau, \phi_\tau(\phi_t^{-1}(x))) \, d\tau \right) \\
        &\leq \rho_0(\phi_t^{-1}(x)) \exp\left( - \int_0^t \overline c \, d\tau \right) \\
        &\leq \overline{\rho_0} \exp\left( - \overline c t \right).
    \end{align}
    The lower bound follows analogously.
    % Note that it is enough to control the negative part of $\nabla \cdot u$ to control the growth of $\rho$.
    \end{proof}

    \begin{proof}[\Cref{prop:DICEErrorBoundAtDataTimepoints}]
    A consequence of \Cref{asm:Smooth} and $\hat{s}^*$ satisfying \eqref{eq:DICE:Smooth:ContEqsHat} is
    \begin{align}
        \int_{\mathcal X} \varphi(x) (\partial_t - \hat \delta_{t_j}) \rho(t_j, x) \, \rd x &= \int_{\mathcal X} \nabla \varphi(x) \cdot \left(  \nabla s^*(t_j, x) - \nabla \hat s^*(t_j, x) \right) \rho(t_j, x) \, \rd x
    \end{align}
    for all $\varphi \in H^1_0(\mathrm dx)$ and $j = 0, \dots, K$. We used the fact that any function in $H^1_0(\mathrm dx)$ is also in $H^1_0(\rho(t_j))$ since $\rho$ is bounded above and below.
    The case $\varphi_j = s^*(t_j, \cdot) - \hat s^*(t_j, \cdot)$ gives
    \begin{align}
        \| \nabla s^*(t_j, \cdot) - \nabla \hat s^*(t_j, \cdot) \|_{L^2(\rho(t_j))}^2 
        &= \int_{\mathcal{X}} ( s^*(t_j, x) - \hat s^*(t_j, x)) (\partial_t - \hat \delta_{t_j}) \rho(t_j, x) \, \rd x \\
        &\leq \| s^*(t_j, x) - \hat s^*(t_j, x) \|_{L^2(\rd x)}  \| (\partial_t - \hat \delta_{t_j}) \rho(t_j, x) \|_{L^2(\rd x)} \\
        &\leq \lambda_{\mathcal X}^{-1/2} \| \nabla s^*(t_j, x) - \nabla \hat s^*(t_j, x) \|_{L^2(\rd x)}  \| (\partial_t - \hat \delta_{t_j}) \rho(t_j, x) \|_{L^2(\rd x)} \, ,
    \end{align}
   for $j = 0, \dots, K$. In the last step, we used the Poincaré inequality of the domain (with constant $\lambda_{\mathcal X}$). Then, with
    \begin{align}
        \| \nabla s^*(t_j, \cdot) - \nabla \hat s^*(t_j, \cdot) \|_{L^2(\rho(t))} \geq \left( \min_{x \in \mathcal{X}} \rho(t_j, x) \right) \| \nabla s^*(t_j, \cdot) - \nabla \hat s^*(t_j, \cdot) \|_{L^2(\rd x)},
    \end{align}
    we find with \Cref{prop:dice:bounds_on_rho} that 
    \begin{align}
        \| \nabla s^*(t_j, \cdot) - \nabla \hat s^*(t_j, \cdot) \|_{L^2(\rho(t_j))} \leq \lambda^{-1/2}_{\mathcal X} \underline{\rho}_0^{-1} \exp\left( \underline{c} t_j \right) \| (\partial_t - \hat \delta_{t_j}) \rho(t_j, x) \|_{L^2(\rd x)}
    \end{align}
    holds. 

    \end{proof}

\begin{proof}[\Cref{prop:DICE:BoundForAllT}]
    In this proof, we will abbreviate $s_t^* = s^*(\cdot, t), \hat{s}_j^* = \hat{s}^*(\cdot, t_j)$, $\hat{s}_t = \hat{s}(t, \cdot)$ as well as $\rho_j = \rho(t_j)$ and $\rho_t = \rho(t)$.
    Recall that $s^*_t$ and $\hat s^*_j$ satisfy
    \begin{align}
    \label{eq:dice:proof_between_tj_1}
        \partial_t \rho_t &= - \nabla \cdot (\rho_t \nabla s_t^*), \\
        \hat \delta_{t_j} \rho_j &= - \nabla \cdot (\rho_j \nabla \hat s_j^*)
    \end{align}
    in $H^1_0(\mathrm dx)$ with homogeneous Neumann boundary conditions as per \Cref{asm:Smooth} and \eqref{eq:DICE:Smooth:ContEqsHat}, respectively. We write the equations formally in strong form for the sake of readability. 

    We can write, by adding zero terms,
    \begin{align}
    \label{eq:dice:proof_between_tj_2}
        - \hat \delta_{t_j} \rho_j &= - \nabla \cdot ((\rho_t - \rho_j) \nabla \hat s_j^*) - \nabla \cdot( \rho_t (\nabla \hat s_t - \nabla \hat s_j^*)) + \nabla \cdot( \rho_t \nabla \hat s_t ).
    \end{align}
    Adding \eqref{eq:dice:proof_between_tj_1} and \eqref{eq:dice:proof_between_tj_2}, together with the definition of $\hat s_t$,
    \begin{align}
        \hat{s}_t\bigg |_{t \in [t_j, t_{j+1}]} = \frac{t_{j+1} - t}{t_{j+1} - t_j} \hat{s}^*_j + \frac{t - t_j}{t_{j+1} - t_j} \hat{s}^*_{j + 1}\,, \quad j = 0, \dots, K-1\,,
    \end{align}
    implying that
    \begin{align}
        \nabla \hat s_t - \nabla \hat s_j^* = \frac{t - t_j}{t_{j+1} - t_j} (\nabla \hat s_{j+1}^* - \nabla \hat s_j^*)\,,
    \end{align}
    gives us
    \begin{align}
    \label{eq:dice:proof_between_tj_3}
        \partial_t \rho_t - \hat \delta_{t_j} \rho_j & = - \nabla \cdot ((\rho_t - \rho_j) \nabla \hat s_j^*) - \frac{t - t_j}{t_{j+1} - t_j} \nabla \cdot (\rho_t (\nabla \hat s_{j+1}^* - \nabla \hat s_j^*)) + \nabla \cdot (\rho_t (\nabla \hat s_t - \nabla s_t^*)).
    \end{align}
    We can multiply this expression with $\hat s_t - s_t^*$ and integrate over $\mathcal X$ (i.e., test with this function) to obtain
    \begin{align}
    \label{eq:dice:proof_between_tj_4}
        \| \nabla \hat s_t - \nabla s_t^* \|^2_{L^2(\rho_t)} 
        &= \underbrace{- \int_{\mathcal X} (\hat s_t - s_t^*) (\partial_t \rho_t - \hat \delta_{t_j} \rho_j) \, \rd x}_{=: \, (i)} \nonumber \\
        &\quad \, \underbrace{+ \int_{\mathcal X} (\nabla \hat s_t - \nabla s_t^*) \cdot \nabla \hat s_j^* (\rho_t - \rho_j) \, \rd x}_{=: \, (ii)} \nonumber \\
        &\quad \,  \underbrace{+ \frac{t - t_j}{t_{j+1} - t_j} \int_{\mathcal X}  (\nabla \hat s_t - \nabla s_t^*) \cdot (\nabla \hat s_{j+1}^* - \nabla \hat s_j^*) \rho_t \, \rd x}_{=: \, (iii)}\,.
    \end{align}
    We now look at these terms one by one. We already see that $(i)$ depends on the accuracy of the finite-difference approximation, $(ii)$ depends on the change of $\rho$ in time, and $(iii)$ on the change of $\hat s$ in time.

    Let us consider term $(i)$ first: 
    We can expand $\rho_t$ about $t_{j + 1}$ to obtain  
    \begin{align}
    \rho_{j+1} = \rho_t + (t_{j+1} - t) \partial_t \rho_t + \frac{1}{2}(t_{j+1} - t)^2 \partial_t^2 \rho_{\tau} \end{align}
    with a Taylor remainder theorem for a $\tau \in [t, t_{j+1}]$ by using that $\rho$ is twice continuously differentiable in $t$.  We use the analogous expansion of $\rho_t$ about $t_{j - 1}$ to obtain $\rho_{j-1} = \rho_t - (t - t_{j-1}) \partial_t \rho_t + \frac{1}{2}(t - t_{j-1})^2 \partial_t^2 \rho_{\tau'} $ for a $\tau' \in [t_{j-1}, t]$. Substituting the two expansions into the definition of $\hat \delta_{t_j} \rho_j$ given in \eqref{eq:DICE:Smooth:DefDeltaRho} and simplifying gives
    \begin{align}
        \hat \delta_{t_j} \rho_j = \partial_t \rho_t + \frac{1}{2} \frac{(t_{j+1} - t)^2}{t_{j+1} - t_{j-1}} \partial_t^2 \rho_\tau - \frac{1}{2} \frac{(t - t_{j-1})^2}{t_{j+1} - t_{j-1}} \partial_t^2 \rho_{\tau'}\,, \qquad t \in [t_{j - 1}, t_{j + 1}]\,. 
    \end{align}
    Because $t \in [t_{j-1}, t_{j+1}]$, we have $\frac{(t_{j+1} - t)^2}{t_{j+1} - t_{j-1}} \leq t_{j+1} - t_j$ and $\frac{(t - t_{j-1})^2}{t_{j+1} - t_{j-1}} \leq t_{j} - t_{j-1}$, and thus
    \begin{align}
        (i) &\leq \| \hat s_t - s_t^* \|_{L^2(\rd x)} \| \partial_t \rho_t - \hat \delta_{t_j} \rho_j \|_{L^2(\rd x)} \\
        &\leq \| \hat s_t - s_t^* \|_{L^2(\rd x)} \frac{1}{2} \| (t_{j+1} - t_j) | \partial^2_t \rho_\tau | + (t_{j} - t_{j-1}) |\partial^2_t \rho_{\tau'}| \|_{L^2(\rd x)} \\
        &\leq \| \hat s_t - s_t^* \|_{L^2(\rd x)} \sup_{\tau \in [t_{j-1}, t_{j+1}]} \| \partial^2_t \rho_\tau \|_{L^2(\rd x)} \, \max \{ t_{j+1} - t_j, t_{j} - t_{j-1}\}\,.
    \end{align}
    Lastly, we can use the Poincar\'e inequality (which holds because of \Cref{asm:Smooth}) and boundedness of $\rho$ to get 
    \begin{align}
    \label{eq:DICE:Smooth:InterProof_bound_on_grads}
        \| \hat s_t - s_t^* \|_{L^2(\rd x)} \leq \lambda^{-1/2}_{\mathcal X} \| \nabla \hat s_t - \nabla s_t^* \|_{L^2(\rd x)} \leq \lambda^{-1/2}_{\mathcal X} \overline{\rho}_0 \exp\left( \overline{c} t \right) \| \nabla \hat s_t - \nabla s_t^* \|_{L^2(\rho_t)}
    \end{align}
    and conclude
    \begin{align}
    \label{eq:DICE:Smooth:InterProof_bound_i}
        (i) &\leq C_{(i)} \max \{ t_{j+1} - t_j, t_{j} - t_{j-1}\} \| \nabla \hat s_t - \nabla s_t^* \|_{L^2(\rho_t)}\,,
    \end{align}
    where $C_{(i)} = \lambda^{-1/2}_{\mathcal X} \overline{\rho}_0 \exp\left( \overline{c} t \right) \max_{\tau \in [t_{j-1}, t_{j+1}]} \| \partial^2_t \rho_\tau \|_{L^2(\rd x)}$.

    Let us now consider term $(ii)$ of \eqref{eq:dice:proof_between_tj_4}: 
    First, with the Cauchy-Schwarz inequality, we obtain
    \begin{align}
        (ii) &\leq \| \nabla \hat s_t - \nabla s_t^* \|_{L^2(\rd x)} \left \| \nabla \hat s_j^* (\rho_j - \rho_t) \right \|_{L^2(\rd x)} \\
        &\leq \| \nabla \hat s_t - \nabla s_t^* \|_{L^2(\rd x)} \left \| \nabla \hat s_j^* \right \|_{L^2(\rd x)} \max_{x \in \mathcal X} |\rho(t_j, x) - \rho(t, x)|\,.
    \end{align}
    The steps to \eqref{eq:DICE:Smooth:InterProof_bound_on_grads} can be repeated for the equation $\hat \delta_{t_j} \rho_j = - \nabla \cdot (\rho_j \nabla \hat s^*_j)$ to find
    \begin{align}
        \left \| \nabla \hat s_j^* \right \|_{L^2(\rd x)}  \leq \lambda^{-1/2}_{\mathcal X} \overline{\rho}_0 \exp\left( \overline{c} t_j \right) \| \hat \delta_{t_j} \rho_j \|_{L^2(\rd x)} \, .
    \end{align}
    The definition of $\hat \delta_{t_j}$ and
    \begin{align}
        | \rho(t_{j+1}) - \rho(t_{j-1}) | \leq |t_{j+1} - t_{j-1}| \max_{\tau \in [t_{j+1}, t_{j-1}]} | \partial_t \rho(\tau) |
    \end{align}
    then imply that
    \begin{align}
        \left \| \nabla \hat s_j^* \right \|_{L^2(\rd x)}  \leq \lambda^{-1/2}_{\mathcal X} \overline{\rho}_0 \exp\left( \overline{c} t_j \right) \| \hat \delta_{t_j} \rho_j \|_{L^2(\rd x)} \leq \lambda^{-1/2}_{\mathcal X} \overline{\rho}_0 \exp\left( \overline{c} t_j \right) \max_{\tau \in [t_{j-1}, t_{j+1}]} \| \partial_t \rho_\tau \|_{L^2(\rd x)} \, .
    \end{align}
    Second, by Taylor's theorem and because $\rho$ is assumed to be twice differentiable in $t$, there exists for all $x$ a $\tau \in [t_j, t]$ such that $|\rho(t_j, x) - \rho(t, x)| = |t - t_j| \partial_t \rho(\tau, x)$ holds, which means that we obtain the bound
    \begin{align}
    \label{eq:DICE:Smooth:InterProof_bound_ii}
        (ii) &\leq C_{(ii)} |t - t_j| \| \nabla \hat s_t - \nabla s_t^* \|_{L^2(\rho_t)}\,,
    \end{align}
    where the constant is
    \begin{align}
    C_{(ii)} = \lambda^{-1/2}_{\mathcal X} \overline{\rho}_0^2 \exp \left( \overline{c} (t + t_j) \right) \left( \max_{x \in \mathcal X} \max_{\tau \in [t_{j}, t_{j+1}]} |\partial_t \rho(x, \tau)| \right) \max_{\tau \in [t_j, t_{j+1}]} \| \partial_t \rho_\tau \|_{L^2(\rd x)}.
    \end{align}
    The constant $C_{(ii)}$ is finite because $\rho$ is continuously differentiable in time.

    Let us now consider term $(iii)$ of \eqref{eq:dice:proof_between_tj_4}: 
    From the Cauchy-Schwarz inequality and $t - t_j \leq t_{j+1} - t_j$ for $t \in [t_j, t_{j+1}]$, we obtain 
    \begin{align}\label{eq:DICE:Smooth:InterProofABC002}
        (iii) \leq \| \nabla \hat s_t - \nabla s_t^* \|_{L^2(\rho_t)} \left \| \nabla \hat s_{j+1}^* - \nabla \hat s_j^* \right \|_{L^2(\rho_t)}.
    \end{align}
    To estimate the second factor in \eqref{eq:DICE:Smooth:InterProofABC002}, we can repeat the analogous procedure as in the derivation of \eqref{eq:dice:proof_between_tj_4}:  use 
    \begin{align}
        \hat \delta_{t_{j+1}} \rho_{j+1} = - \nabla \cdot (\rho_{j+1} \nabla \hat s_{j+1}^*)
    \end{align}
    to find
    \begin{align}
    \label{eq:dice:proof_between_tj_5}
        \hat \delta_{t_{j+1}} \rho_{j+1} - \hat \delta_{t_j} \rho_{j} 
        &= - \nabla \cdot (\rho_{j+1} \nabla \hat s_{j+1}^* - \rho_{j} \nabla \hat s_{j}^*) \\
        &= - \nabla \cdot ((\rho_{j+1} - \rho_t) \nabla \hat s_{j+1}^* + (\rho_t - \rho_{j}) \nabla \hat s_{j}^*) - \nabla \cdot (\rho_t (\nabla \hat s_{j+1}^* - \nabla \hat s_{j}^*)).
    \end{align}
    When $j > K - 2$, we can use $\hat \delta_{t_{j-1}} \rho_{j-1}$ in place of $\hat \delta_{t_{j+1}} \rho_{j+1}$ here without changing the argument. We test this equation with $\hat s_{j+1}^* - \hat s_j^*$ and obtain
    \begin{align}
        \| \nabla \hat s_{j+1}^* - \nabla \hat s_j^* \|^2_{L^2(\rho_t)} 
        &= \underbrace{\int_{\mathcal X} (\nabla \hat s_{j+1}^* - \nabla \hat s_j^*) \cdot \nabla \hat s_{j+1}^* (\rho_t - \rho_{j+1}) \, \rd x}_{=: \, (iv)} \nonumber \\
        &\quad \, \underbrace{+ \int_{\mathcal X} (\nabla \hat s_{j+1}^* - \nabla \hat s_j^*) \cdot \nabla \hat s_j^* (\rho_j - \rho_t) \, \rd x}_{=: \, (v)} \nonumber \\
        &\quad \, \underbrace{+ \int_{\mathcal X} (\hat s_{j+1}^* - \hat s_j^*) (\hat \delta_{t_{j+1}} \rho_{j+1} - \hat \delta_{t_j} \rho_{j}) \, \rd x}_{=: \, (vi)}\,.
    \end{align}
    For the terms $(iv)$ and $(v)$ we obtain the bounds $(iv) \leq C_{(iv)} |t_{j+1} - t| \| \nabla \hat s_{j+1}^* - \nabla \hat s_j^* \|_{L^2(\rho_t)}$ and $(v) \leq C_{(v)} |t - t_j| \| \nabla \hat s_{j+1}^* - \nabla \hat s_j^* \|_{L^2(\rho_t)}$ using the analogous arguments as used to bound $(ii)$, respectively with $C_{(v)} = C_{(ii)}$ and
    \begin{align}
        C_{(iv)} &= \overline{\rho}_0^2 \exp \left( \overline{c} (t + t_{j+1}) \right) \left( \max_{x \in \mathcal X} \max_{\tau \in [t_{j}, t_{j+1}]} |\partial_t \rho(x, \tau)| \right) \max_{\tau \in [t_j, t_{j+2}]} \| \partial_t \rho_\tau \|_{L^2(\rd x)}.
    \end{align}
    The term $(vi)$ can be bounded as
    \begin{align}\label{eq:ProofPropContTime:Aux3441}
        (vi) \leq \| \hat s^*_{j+1} - \hat s^*_j \|_{L^2(\rd x)} \left( \| \partial_t \rho_t - \hat \delta_{t_{j+1}} \rho_{j+1} \|_{L^2(\rd x)} + \| \partial_t \rho_t - \hat \delta_{t_j} \rho_j \|_{L^2(\rd x)}\right)\,.
    \end{align}
    The second term in \eqref{eq:ProofPropContTime:Aux3441} is analogous to the estimate $(i)$. The first term is also analogous but for the interval $[t_j, t_{j+2}]$ instead of $[t_{j-1}, t_{j + 1}]$. Hence,
    \begin{align}
        \| \nabla \hat s^*_{j+1} - \nabla \hat s_j^* \|^2_{L^2(\rho_t)} 
        &\leq C_{(iv)} |t_{j+1} - t| \| \nabla \hat s^*_{j+1} - \nabla \hat s^*_j \|_{L^2(\rho_t)} \nonumber \\
        &\quad \, + C_{(v)} |t - t_j| \| \nabla \hat s^*_{j+1} - \nabla \hat s^*_j \|_{L^2(\rho_t)} \nonumber \\
        &\quad \, + C_{(vi)} \max \{ t_{j+2} - t_{j+1}, t_{j+1} - t_j, t_{j} - t_{j-1}\} \| \nabla \hat s^*_{j+1} - \nabla \hat s_j^* \|_{L^2(\rho_t)}\,,
    \end{align}
    where 
    \begin{align}
        C_{(vi)} = C_{(i)} + \lambda^{-1/2}_{\mathcal X} \overline{\rho_0} \exp\left( \overline{c} t \right) \max_{\tau \in [t_{j}, t_{j+2}]} \| \partial^2_t \rho_\tau \|_{L^2(\rd x)}.
    \end{align}
    This results in the estimate
    \begin{align}
        \| \nabla \hat s^*_{j+1} - \nabla \hat s_j^* \|_{L^2(\rho_t)} &\leq (C_{(iv)} + C_{(v)} + C_{(vi)} ) \max \{ t_{j+2} - t_{j+1}, t_{j+1} - t_j, t_{j} - t_{j-1}\}
    \end{align}
    and hence
    \begin{align}
    \label{eq:DICE:Smooth:InterProof_bound_iii}
        (iii) \leq \| \nabla \hat s_t - \nabla s_t^* \|_{L^2(\rho_t)} (C_{(iv)} + C_{(v)} + C_{(vi)} ) \max \{ t_{j+2} - t_{j+1}, t_{j+1} - t_j, t_{j} - t_{j-1}\}
    \end{align}
    Now taking the bounds for all three terms $(i) - (iii)$ together (i.e. Equations \eqref{eq:DICE:Smooth:InterProof_bound_i}, \eqref{eq:DICE:Smooth:InterProof_bound_ii}, \eqref{eq:DICE:Smooth:InterProof_bound_iii}) and collecting all terms, we thus find (using $t-t_j < t_{j+1} - t_j$):
    \begin{align}
        \| \nabla \hat s_t - \nabla s^*_t \|_{L^2(\rho_t)} \leq \left( C_{(i)} + \ldots + C_{(vi)} \right) \max \{ t_{j+2} - t_{j+1}, t_{j+1} - t_j, t_{j} - t_{j-1}\}
    \end{align}
    for any $t \in [t_j, t_{j+1}]$. Taking the maximum over $j$ proves the claim. Note that
    \begin{align}
        C_{(i)}, \frac 1 2 C_{(vi)} \leq \lambda^{-1/2}_{\mathcal X} \overline{\rho}_0 \exp\left( \overline{c} T \right) \max_{\tau \in [0, T]} \| \partial^2_t \rho_\tau \|_{L^2(\rd x)}
    \end{align}
    and
    \begin{align}
    C_{(ii)}, C_{(iv)}, C_{(vi)} \leq \lambda^{-1/2}_{\mathcal X} \overline{\rho}_0^2 \exp \left( 2\overline{c} T \right) \left( \max_{\tau \in [0, T]} \|\partial_t \rho(\tau) \|_{L^\infty(\rd x)} \right) \max_{\tau \in [0, T]} \| \partial_t \rho_\tau \|_{L^2(\rd x)} \, .
    \end{align}








\end{proof}

\begin{proof}[\Cref{corr:DICE:BoundForAllT_NNDiscretization}]
    The only part of the proof of \Cref{prop:DICE:BoundForAllT} that needs to be modified in this case is the bound for $(iii)$ in \eqref{eq:dice:proof_between_tj_4}. It can be replaced by
    \begin{align}
        \int_{\mathcal X}  (\nabla s^*_t - \nabla \hat s_t) \cdot (\nabla \hat s_{t} - \nabla s^*_j) \rho_t \, \rd x 
        &\leq \| \nabla \hat s_t - \nabla s^*_t \|_{L^2(\rho_t)} \| \nabla \hat s_t - \nabla \hat s^*_j \|_{L^2(\rho_t)} \\
        &\leq \| \nabla \hat s_t - \nabla s^*_t \|_{L^2(\rho_t)} L^t_{\hat s} |t - t_j|.
    \end{align}
    The remainder of the proof is unchanged.
\end{proof}

\subsection{Inference error bound}

\begin{proof}[\Cref{prop:bound_on_inference_error_w2}]
We start by recalling the following result from \citet[Theorem 8.13]{villani_topics_2016}: 
        Let $(\epsilon, \epsilon) \ni t \mapsto \rho(t)$ be an absolutely continuous curve through $\mathcal P(\xdomain)$ and $\sigma \in \mathcal P(\xdomain)$ be a fixed absolutely continuous measure. When $\partial_t \rho + \nabla \cdot (\rho v) = 0$ for a bounded $v$ of class $C^1$ in both $t$ and $x$, then
        \begin{align}
            \frac{\rd}{\rd t} \frac{1}{2} W_2(\rho(t), \sigma)^2 = \int_\xdomain (x - T_{\rho(t) \rightarrow \sigma}(x)) \cdot v(x,t) \rho(t, x) \, \rd x,
        \end{align}
        where $T_{\rho(t) \rightarrow \sigma}$ denotes the optimal transport map from $\rho(t)$ to $\sigma$.



Let us now return to the proof of \Cref{prop:bound_on_inference_error_w2}. 
        The claim follows from \citet[Theorem 8.13]{villani_topics_2016} stated above together with the fact that
        $\Vert\mathrm{id} - T_{\rho(t) \rightarrow \hat \rho(t)} \Vert_{L^2(\rho(t))} = W_2(\rho(t), \hat \rho(t))$, where $T_{\rho(t) \rightarrow \hat \rho(t)}$ denotes the optimal transport map from $\rho(t)$ to $\hat \rho(t)$ and $\operatorname{id}$ the identity map.
        We obtain 
        \begin{align}
            \frac{\rd}{\rd t} \frac{1}{2} W_2(\rho(t), \hat \rho(t))^2
            &= \int_\xdomain (\mathrm{id} - T_{\rho(t) \rightarrow \hat \rho(t)}) \cdot \nabla s^*(t, \cdot) \rho(t) \, \rd x +\notag\\
            & \qquad \qquad\qquad \int_\xdomain (\mathrm{id} - T_{\hat \rho(t) \rightarrow \rho(t)}) \cdot \nabla \hat s^*(t, \cdot) \hat \rho(t) \, \rd x \\
            &= \int_\xdomain (\mathrm{id} - T_{\rho(t) \rightarrow \hat \rho(t)}) \cdot \nabla s^*(t, \cdot) \rho(t) \, \rd x\notag\\
            & \qquad\qquad\qquad\qquad + \int_\xdomain (T_{\rho(t) \rightarrow \hat \rho(t)} - \mathrm{id}) \cdot \nabla \hat s^*(t, \cdot) \circ T_{\rho(t) \rightarrow \hat \rho(t)} \rho(t) \, \rd x \\
            &= \int_\xdomain (\mathrm{id} - T_{\rho(t) \rightarrow \hat \rho(t)}) \cdot \left( \nabla s^*(t, \cdot) - \nabla \hat s^*(t, \cdot) \circ T_{\rho(t) \rightarrow \hat \rho(t)} \right) \rho(t) \, \rd x \\
            &\leq \Vert\mathrm{id} - T_{\rho(t) \rightarrow \hat \rho(t)} \Vert_{L^2(\rho(t))} \Vert \nabla s^*(t, \cdot) - \nabla \hat s^*(t, \cdot) \circ T_{\rho(t) \rightarrow \hat \rho(t)} \Vert_{L^2(\rho(t))} \\
            &= W_2(\rho(t), \hat \rho(t)) \, \Vert \nabla s^*(t, \cdot) - \nabla \hat s^*(t, \cdot) \circ T_{\rho(t) \rightarrow \hat \rho(t)} \Vert_{L^2(\rho(t))} \\
            &\leq W_2(\rho(t), \hat \rho(t)) \left( \Vert \nabla s^*(t, \cdot) - \nabla \hat s^*(t, \cdot) \Vert_{L^2(\rho(t, \cdot))}\right.\notag\\
             & \left.\qquad\qquad\qquad + \Vert \nabla \hat s^*(t, \cdot) - \nabla \hat s^*(t, \cdot) \circ T_{\rho(t, \cdot) \rightarrow \hat \rho(t, \cdot)} \Vert_{L^2(\rho(t))} \right)\,.
        \end{align}
        By Taylor's theorem, there exists a point $y$ on the line connecting $x$ to $T_{\rho(t) \rightarrow \hat \rho(t)}(x)$ such that
        \begin{align}
            \nabla \hat s^*(t, \cdot) \circ T_{\rho(t) \rightarrow \hat \rho(t)}(x) = \nabla \hat s^*(t, x) + D^2 \hat s^*(t, y) (T_{\rho(t) \rightarrow \hat \rho(t)}(x) - x)
        \end{align}
        and therefore
        \begin{align}
            \Vert \nabla \hat s^*(t, \cdot) - \nabla \hat s^*(t, \cdot) \circ T_{\rho(t) \rightarrow \hat \rho(t)} \Vert_{L^2(\rho)} &\leq \sup_{x \in \mathcal X} \Vert D^2_x \hat s^*(t, x) \Vert_{\mathrm{op}} \| T_{\rho(t) \rightarrow \hat \rho(t)} - \mathrm{id} \|_{L^2(\rho(t))}\\
            & = L_{\hat s^*}^x(t) W_2(\rho(t), \hat \rho(t)).
        \end{align}
        Together, this implies that
        \begin{align}
            \frac{\rd}{\rd t} W_2(\rho(t), \hat \rho(t))
            &\leq \Vert \nabla s^*(t, \cdot) - \nabla \hat s^*(t, \cdot) \Vert_{L^2(\rho(t))} + L_{\hat s^*}^x(t) W_2(\rho(t), \hat \rho(t))
        \end{align}
        and thus 
        \begin{align}
            W_2(\rho(t), \hat \rho(t)) &\leq W_2(\rho(0), \hat \rho(0)) + \int_0^t \Vert \nabla s^*(\cdot, \tau) - \nabla \hat s^*(\cdot, \tau) \Vert_{L^2(\rho(\tau))} \, \rd \tau \nonumber \\
            &\quad \, + \int_0^t L_{\hat s^*}^x(\tau) W_2(\rho(\tau), \hat \rho(\tau)) \, \rd \tau.
        \end{align}
        Plugging in the bound of \Cref{prop:DICE:BoundForAllT} and an application of the Gr\"onwall inequality concludes the proof.
    \end{proof}





