    \includegraphics[width=\textwidth]{Figures/gencast_vs_ens_operational_scorecard_cycle_48r1_2023.pdf}
    \caption{CRPS scorecard comparing the currently operational version of \gencast (used as the baseline in this work) to ENS on 00/12 initialization times after the 27th of June 2023, against \hresfczero ground truth. On these dates, ENS natively operates at a resolution \tenthdegree and is conservatively downsampled to \quarterdegree for this evaluation. \gencast outperforms ENS on 95.0\% of targets, with an average improvement of 3.7\% and a maximum improvement of 15.2\%.}
    \label{fig:sup:gencast_ens_cycle_48r1}
\end{figure}

\begin{figure}
    \centering
    \includegraphics[width=\textwidth]{Figures/FGN_vs_ens_operational_scorecard_2023.pdf}
    \caption{CRPS scorecard comparing \ourmodel to ENS, on all 00/12 initialization times in 2023, against \hresfczero ground truth (note the vlim of 30\%). \ourmodel achieves better CRPS on 99.3\% of targets, with an average improvement of 10.8\% and a maximum improvement of 27.7\%. Notably,  while \gencast suffered compared to ENS at short lead times, \ourmodel is strong across all lead times.}
    \label{fig:sup:fnv3_ens}
\end{figure}

\begin{figure}
    \centering
    \includegraphics[width=\textwidth]{Figures/FGN_vs_ens_operational_scorecard_cycle_47r3_2023.pdf}
    \caption{CRPS scorecard comparing \ourmodel to ENS, on 00/12 initialization times before the 27th of June 2023, against \hresfczero ground truth (note the vlim of 30\%). On these initializations, both models natively operate at resolutions (close to) \quarterdegree. \ourmodel achieves better CRPS on 99.5\% of targets, with an average improvement of 12.0\% and a maximum improvement of 30.6\%.}
    \label{fig:sup:fnv3_ens_cycle_47r3}
\end{figure}

\begin{figure}
    \centering
    \includegraphics[width=\textwidth]{Figures/FGN_vs_ens_operational_scorecard_cycle_48r1_2023.pdf}
    \caption{CRPS scorecard comparing ENS to \ourmodel on 00/12 initialization times, after the 27th of June 2023, against \hresfczero ground truth (note the vlim of 30\%). On these initializations, ENS natively operates at a resolution \tenthdegree and is conservatively downsampled to \quarterdegree for comparison. \ourmodel achieves better CRPS on 99.2\% of targets, with an average improvement of 9.7\% and a maximum improvement of 26.5\%.}
    \label{fig:sup:fnv3_ens_cycle_48r1}
\end{figure}



\subsection{Extended Results}\label{sup:extended results}

\cref{fig:sup:rmse} shows the ensemble mean RMSE scorecards comparing \ourmodel to \gencast. 
\begin{figure}[p]
    \centering
    \includegraphics[width=\textwidth]{Figures/rmse_scorecard_with_significance_2023.pdf}
    \caption{Ensemble mean RMSE scorecard comparing \ourmodel to \gencast, where blue cells indicate \ourmodel outperforms \gencast, red denotes where \gencast is better. \ourmodel is significantly better ($p < 0.05$) in 100\% of cases, with improvements of up to 18\% and an average of 5.8\%.}
    \label{fig:sup:rmse}
\end{figure}

We evaluate precipitation forecasting skill using RMSE and CRPS as well as  Stable Equitable Error in Probability Space (SEEPS), which is often used as a specialized metric for precipitation evaluation \citep{rodwell2010new,haiden2012intercomparison,north2013assessment}, using the same methodology as in \citet{lam2023learning} and \citet{price2025probabilistic}. Because SEEPS is a metric for deterministic categorical forecasts (dry, light-rain, and heavy-rain) we evaluated the ensembles computing the category of the ensemble mean.
Results for 12-hour and 24-hour accumulated precipitation are shown in \cref{fig:sup:precip_12}  and \cref{fig:sup:precip_24} respectively.

\begin{figure}[p]
    \centering
    \includegraphics[width=\textwidth]{Figures/fig_tp12hr_2023.pdf}
    \caption{Results on 12h accumulated precipitation against ERA5 show \ourmodel outperforming \gencast when comparing Ensemble-Mean RMSE, CRPS and SEEPS (with dry thresholds of 0.1 and 0.25) for the predicted total accumulated precipitation over 12 hours. All metrics were calculated globally and over the full test period, except for SEEPS which excludes very dry regions according to the criteria in \citet{lam2023learning}. SEEPS is evaluated on the ensemble mean prediction. Absolute and relative plots are shown in the top and bottom rows respectively.}
    \label{fig:sup:precip_12}
\end{figure}


\begin{figure}[htbp]
    \centering
    \includegraphics[width=\textwidth]{Figures/fig_tp24hr_2023.pdf}
    \caption{Similar to \cref{fig:sup:precip_12}, results on 24h accumulated precipitation against ERA5 also show \ourmodel outperforming \gencast.}
    \label{fig:sup:precip_24}
\end{figure}

\cref{fig:sup:rev_high_wind,fig:sup:rev_high_2t,fig:sup:rev_low_2t}, and \ref{fig:sup:rev_low_msl} show REV results on prediction of extreme high 10m wind speed, high 2m temperature, low 2m temperature, and low mean sea level pressure, respectively, for different extreme thresholds, across different cost/loss ratios, for different lead times. \ourmodel achieves significantly higher REV than \gencast ($p < 0.05$), with a few exceptions at longer lead times for certain  cost-loss and lead time combinations for high 2m temperature. 


